window.ASSIGNMENTS={"1": {"English": {"book": "Mridang", "questions": [{"n": 1, "type": "MCQ", "topic": "Letter sounds (phonics)", "q": "Which word begins with the 'b' sound?\\n(a) cat (b) ball (c) sun (d) pen", "marks": 1, "answer": "(b) ball"}, {"n": 2, "type": "Fill in the blank", "topic": "Missing letters", "q": "(Picture: a cat)\\nFill in the missing letter: c _ t", "marks": 1, "answer": "a (cat)"}, {"n": 3, "type": "MCQ", "topic": "Rhyming words", "q": "Which word rhymes with 'hat'?\\n(a) cup (b) bat (c) dog (d) hen", "marks": 1, "answer": "(b) bat"}, {"n": 4, "type": "True/False", "topic": "Alphabet", "q": "The word 'apple' begins with the letter 'a'. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Animal sounds (vocabulary)", "q": "Match the animal with its sound:\\n(i) cow        (a) bark\\n(ii) dog        (b) moo", "marks": 1, "answer": "(i) cow - (b) moo; (ii) dog - (a) bark (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Capital and small letters", "q": "Write the capital letters for: a, m, t, e", "marks": 2, "answer": "A, M, T, E (½ mark each)"}, {"n": 7, "type": "Short answer", "topic": "Reading a short poem", "q": "Read the lines:\\n'Little bird, little bird,\\nUp in the tree,\\nSing a sweet song\\nJust for me.'\\n(a) Where is the bird?\\n(b) What does the bird sing?", "marks": 2, "answer": "(a) Up in the tree. (b) A sweet song. (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Naming words", "q": "Write the names of two things you can see in your classroom.", "marks": 2, "answer": "Any two correct naming words, e.g. desk, board, chair, bag, book, fan (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Picture reading", "q": "(Picture: A girl named Riya is flying a red kite in a park. The sun is shining.)\\nAnswer:\\n(a) What is the girl's name?\\n(b) What is she flying?\\n(c) What colour is the kite?\\n(d) Where is she?\\n(e) Is it a sunny day or a rainy day?", "marks": 5, "answer": "(a) Riya (b) A kite (c) Red (d) In a park (e) A sunny day (1 mark each)"}, {"n": 10, "type": "Activity", "topic": "Speaking: My family", "q": "Oral activity: Stand up and tell the class about your family in 4 short sentences. Example: 'My mother's name is Sita.'", "marks": 4, "answer": "1 mark for each clear, complete sentence about family members (names, what they do, what the child likes doing with them). Look for loud clear voice and simple correct sentences."}]}, "Maths": {"book": "Joyful Mathematics", "questions": [{"n": 1, "type": "MCQ", "topic": "Numbers 1 to 20 (order)", "q": "Which number comes just after 7?\\n(a) 6 (b) 8 (c) 9 (d) 5", "marks": 1, "answer": "(b) 8"}, {"n": 2, "type": "Fill in the blank", "topic": "Addition within 9", "q": "3 + 2 = ____", "marks": 1, "answer": "5"}, {"n": 3, "type": "MCQ", "topic": "Comparing numbers", "q": "Which is the biggest number?\\n(a) 4 (b) 9 (c) 2 (d) 6", "marks": 1, "answer": "(b) 9"}, {"n": 4, "type": "True/False", "topic": "Shapes around us", "q": "A ball is round in shape. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Fill in the blank", "topic": "Counting", "q": "(Picture: 6 stars in a row)\\nHow many stars are there? ____", "marks": 1, "answer": "6"}, {"n": 6, "type": "Short answer", "topic": "Addition and subtraction within 9", "q": "Solve:\\n(a) 8 - 3 = ____\\n(b) 5 + 4 = ____", "marks": 2, "answer": "(a) 5 (b) 9 (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Patterns", "q": "Complete the pattern by writing the next two shapes:\\ncircle, triangle, circle, triangle, circle, ____, ____", "marks": 2, "answer": "triangle, circle (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Addition word problem", "q": "Riya has 4 pencils. Her mother gives her 3 more pencils. How many pencils does Riya have now?", "marks": 2, "answer": "4 + 3 = 7. Riya has 7 pencils. (1 mark for adding, 1 mark for answer)"}, {"n": 9, "type": "Long answer", "topic": "Numbers 11 to 20", "q": "Fill in the missing numbers:\\n11, ___, 13, ___, 15, ___, 17, ___, 19, ___", "marks": 5, "answer": "12, 14, 16, 18, 20 (1 mark each)"}, {"n": 10, "type": "Activity", "topic": "Measurement: longer and shorter", "q": "Put your pencil on the desk. Find 2 things in your classroom that are longer than your pencil and 2 things that are shorter than it. Say or write their names.", "marks": 4, "answer": "1 mark for each correct object. Longer: e.g. desk, door, ruler (30 cm), duster stick. Shorter: e.g. eraser, sharpener, chalk, crayon. Check the child actually compared."}]}, "Hindi": {"book": "सारंगी", "questions": [{"n": 1, "type": "MCQ", "topic": "वर्णमाला (व्यंजन)", "q": "'क' के बाद कौन-सा अक्षर आता है?\\n(क) ग (ख) ख (ग) घ (घ) च", "marks": 1, "answer": "(ख) ख"}, {"n": 2, "type": "Fill in the blank", "topic": "आ की मात्रा", "q": "'आ' की मात्रा लगाकर लिखिए:\\nक + ा = ____", "marks": 1, "answer": "का"}, {"n": 3, "type": "MCQ", "topic": "स्वर पहचान", "q": "'आम' शब्द किस अक्षर से शुरू होता है?\\n(क) अ (ख) आ (ग) इ (घ) उ", "marks": 1, "answer": "(ख) आ"}, {"n": 4, "type": "True/False", "topic": "शब्द और अक्षर", "q": "'कमल' शब्द में तीन अक्षर हैं। सही या गलत लिखिए।", "marks": 1, "answer": "सही (क, म, ल)"}, {"n": 5, "type": "Match the following", "topic": "जीव-जंतु और उनके घर", "q": "मिलान कीजिए:\\n(i) मछली        (क) आसमान\\n(ii) चिड़िया      (ख) पानी", "marks": 1, "answer": "(i) मछली - (ख) पानी; (ii) चिड़िया - (क) आसमान (आधा-आधा अंक)"}, {"n": 6, "type": "Short answer", "topic": "दो अक्षर वाले शब्द", "q": "दो अक्षर वाले कोई दो शब्द लिखिए।", "marks": 2, "answer": "कोई भी दो सही शब्द, जैसे - जल, घर, बस, नल, फल (1-1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "कविता पढ़ना", "q": "कविता पढ़िए:\\n'चिड़िया रानी आई है,\\nदाना चुगने आई है।\\nचीं-चीं करती गाती है,\\nसबके मन को भाती है।'\\n(क) चिड़िया क्यों आई है?\\n(ख) चिड़िया कैसे गाती है?", "marks": 2, "answer": "(क) चिड़िया दाना चुगने आई है। (ख) चिड़िया चीं-चीं करती गाती है। (1-1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "अक्षर जोड़कर शब्द बनाना", "q": "अक्षर जोड़कर शब्द बनाइए:\\n(क) न + ल = ____\\n(ख) ब + स = ____", "marks": 2, "answer": "(क) नल (ख) बस (1-1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "चित्र पढ़ना", "q": "(चित्र: एक बगीचे में लाल फूल हैं, एक हरा पेड़ है, एक लड़का गेंद से खेल रहा है और आसमान में सूरज चमक रहा है।)\\nउत्तर दीजिए:\\n(क) फूल किस रंग के हैं?\\n(ख) पेड़ किस रंग का है?\\n(ग) लड़का किससे खेल रहा है?\\n(घ) आसमान में क्या चमक रहा है?\\n(ङ) यह जगह कौन-सी है?", "marks": 5, "answer": "(क) लाल (ख) हरा (ग) गेंद से (घ) सूरज (ङ) बगीचा (1-1 अंक)"}, {"n": 10, "type": "Activity", "topic": "बोलना: मेरा परिवार", "q": "मौखिक गतिविधि: अपने परिवार के चार सदस्यों के नाम बोलिए। हर सदस्य के बारे में एक वाक्य बोलिए, जैसे - 'मेरी माँ का नाम सीता है।'", "marks": 4, "answer": "हर सही और साफ़ वाक्य के लिए 1 अंक। देखें कि बच्चा साफ़ आवाज़ में, पूरे वाक्य में बोले।"}]}}, "2": {"English": {"book": "Mridang", "questions": [{"n": 1, "type": "MCQ", "topic": "Use of a / an", "q": "Choose the correct word: I have ___ umbrella.\\n(a) a (b) an (c) is (d) am", "marks": 1, "answer": "(b) an"}, {"n": 2, "type": "Fill in the blank", "topic": "Opposites", "q": "Write the opposite: big - ____", "marks": 1, "answer": "small (or little)"}, {"n": 3, "type": "MCQ", "topic": "One and many (plurals)", "q": "One cat, many ____.\\n(a) cat (b) cates (c) cats (d) caties", "marks": 1, "answer": "(c) cats"}, {"n": 4, "type": "True/False", "topic": "Naming words (nouns)", "q": "'Rahul' is a naming word. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Opposites", "q": "Match the opposites:\\n(i) hot        (a) down\\n(ii) up        (b) cold", "marks": 1, "answer": "(i) hot - (b) cold; (ii) up - (a) down (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Making sentences", "q": "Put the words in the right order to make sentences:\\n(a) is / sky / The / blue.\\n(b) like / I / mangoes.", "marks": 2, "answer": "(a) The sky is blue. (b) I like mangoes. (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Reading comprehension", "q": "Read:\\n'Meena has a pet dog. His name is Tommy. Tommy is brown. He likes to play with a ball. Meena gives him milk every morning.'\\n(a) What is the dog's name?\\n(b) What colour is the dog?", "marks": 2, "answer": "(a) Tommy (b) Brown (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Reading comprehension", "q": "Read the passage in Q7 again and answer:\\n(a) What does Tommy like to play with?\\n(b) What does Meena give Tommy every morning?", "marks": 2, "answer": "(a) A ball (b) Milk (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Writing sentences: My School", "q": "Write 5 sentences about 'My School'.\\nHints: name of school, teacher, friends, what you like, playground.", "marks": 5, "answer": "1 mark per correct, meaningful sentence. Example: My school is big. My teacher is kind. I have many friends. I like to read books. We play in the playground. Check capital letters and full stops."}, {"n": 10, "type": "Activity", "topic": "Action words (verbs)", "q": "Act out 4 actions in front of the class (like run, jump). Your friends guess the action. Then write the 4 action words.", "marks": 4, "answer": "1 mark for each correct action word acted and written, e.g. run, jump, clap, sing, dance, swim, eat, sleep. Look for correct spelling and clear acting."}]}, "Maths": {"book": "Joyful Mathematics", "questions": [{"n": 1, "type": "MCQ", "topic": "Numbers up to 100", "q": "Which number comes just before 50?\\n(a) 51 (b) 40 (c) 49 (d) 60", "marks": 1, "answer": "(c) 49"}, {"n": 2, "type": "Fill in the blank", "topic": "Tens and ones", "q": "4 tens and 7 ones = ____", "marks": 1, "answer": "47"}, {"n": 3, "type": "MCQ", "topic": "Comparing numbers", "q": "Which is the greatest number?\\n(a) 38 (b) 83 (c) 58 (d) 29", "marks": 1, "answer": "(b) 83"}, {"n": 4, "type": "True/False", "topic": "Shapes", "q": "A triangle has 4 corners. Write True or False.", "marks": 1, "answer": "False. A triangle has 3 corners."}, {"n": 5, "type": "Fill in the blank", "topic": "Skip counting", "q": "Skip count by 5: 5, 10, 15, ____", "marks": 1, "answer": "20"}, {"n": 6, "type": "Short answer", "topic": "Addition and subtraction of 2-digit numbers", "q": "Solve:\\n(a) 34 + 25 = ____\\n(b) 68 - 23 = ____", "marks": 2, "answer": "(a) 59 (b) 45 (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Ordering numbers", "q": "Arrange from smallest to biggest: 45, 12, 78, 30", "marks": 2, "answer": "12, 30, 45, 78"}, {"n": 8, "type": "Short answer", "topic": "Subtraction word problem", "q": "A shop had 56 balloons. 24 balloons were sold. How many balloons are left?", "marks": 2, "answer": "56 - 24 = 32. 32 balloons are left. (1 mark for method, 1 mark for answer)"}, {"n": 9, "type": "Long answer", "topic": "Money", "q": "Anu has ₹50. She buys a pencil for ₹10, an eraser for ₹5 and a notebook for ₹20.\\n(a) Cost of pencil and eraser together?\\n(b) Total money spent?\\n(c) Money left with Anu?\\n(d) Which item costs the most?\\n(e) How many ₹5 coins make ₹20?", "marks": 5, "answer": "(a) ₹10 + ₹5 = ₹15 (b) ₹10 + ₹5 + ₹20 = ₹35 (c) ₹50 - ₹35 = ₹15 (d) Notebook (e) 4 coins (1 mark each)"}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Place value (thinking)", "q": "Use the digits 2 and 6 (each only once) to make:\\n(a) the biggest 2-digit number\\n(b) the smallest 2-digit number\\n(c) Add the two numbers.", "marks": 4, "answer": "(a) 62 (1 mark) (b) 26 (1 mark) (c) 62 + 26 = 88 (2 marks)"}]}, "Hindi": {"book": "सारंगी", "questions": [{"n": 1, "type": "MCQ", "topic": "उलटे अर्थ वाले शब्द", "q": "'दिन' का उलटा शब्द कौन-सा है?\\n(क) सुबह (ख) शाम (ग) रात (घ) धूप", "marks": 1, "answer": "(ग) रात"}, {"n": 2, "type": "Fill in the blank", "topic": "शब्द बनाना", "q": "जोड़कर शब्द बनाइए:\\nकि + ताब = ____", "marks": 1, "answer": "किताब"}, {"n": 3, "type": "MCQ", "topic": "शब्द पहचान (फल)", "q": "इनमें से फल का नाम कौन-सा है?\\n(क) गाजर (ख) सेब (ग) आलू (घ) गोभी", "marks": 1, "answer": "(ख) सेब"}, {"n": 4, "type": "True/False", "topic": "पक्षी", "q": "'मोर' एक पक्षी है। सही या गलत लिखिए।", "marks": 1, "answer": "सही"}, {"n": 5, "type": "Match the following", "topic": "एक और अनेक", "q": "एक और अनेक का मिलान कीजिए:\\n(i) लड़का        (क) कपड़े\\n(ii) कपड़ा        (ख) लड़के", "marks": 1, "answer": "(i) लड़का - (ख) लड़के; (ii) कपड़ा - (क) कपड़े (आधा-आधा अंक)"}, {"n": 6, "type": "Short answer", "topic": "ए की मात्रा", "q": "'े' (ए) की मात्रा वाले दो शब्द लिखिए।", "marks": 2, "answer": "कोई भी दो सही शब्द, जैसे - केला, मेला, सेब, रेल, खेत (1-1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "अपठित गद्यांश", "q": "पढ़िए:\\n'राजू के पास एक तोता है। तोते का नाम मिट्ठू है। मिट्ठू हरे रंग का है। उसकी चोंच लाल है। वह रोज़ अमरूद खाता है।'\\n(क) तोते का नाम क्या है?\\n(ख) तोता किस रंग का है?", "marks": 2, "answer": "(क) मिट्ठू (ख) हरे रंग का (1-1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "अपठित गद्यांश", "q": "प्रश्न 7 का गद्यांश फिर से पढ़कर उत्तर दीजिए:\\n(क) तोते की चोंच किस रंग की है?\\n(ख) तोता रोज़ क्या खाता है?", "marks": 2, "answer": "(क) लाल (ख) अमरूद (1-1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "वाक्य लेखन", "q": "'मेरा प्रिय खिलौना' पर पाँच वाक्य लिखिए।\\nसंकेत: खिलौने का नाम, रंग, किसने दिया, कैसे खेलते हो, क्यों पसंद है।", "marks": 5, "answer": "हर सही और पूरे वाक्य के लिए 1 अंक। उदाहरण: मेरा प्रिय खिलौना गेंद है। यह लाल रंग की है। यह मुझे पापा ने दी है। मैं इससे दोस्तों के साथ खेलता हूँ। मुझे यह बहुत अच्छी लगती है। वर्तनी और पूर्ण विराम (।) देखें।"}, {"n": 10, "type": "Activity", "topic": "अक्षर से शब्द", "q": "इन अक्षरों से शुरू होने वाला एक-एक शब्द बोलिए और लिखिए:\\nप, म, स, ग", "marks": 4, "answer": "हर सही शब्द के लिए 1 अंक। उदाहरण: प - पतंग, म - मछली, स - सूरज, ग - गमला।"}]}}, "3": {"English": {"book": "Santoor", "questions": [{"n": 1, "type": "MCQ", "topic": "Pronouns", "q": "Which of these is a pronoun?\\n(a) run (b) she (c) table (d) happy", "marks": 1, "answer": "(b) she"}, {"n": 2, "type": "Fill in the blank", "topic": "Action words (verbs)", "q": "Fill in with the correct word (fly / flies):\\nBirds ____ in the sky.", "marks": 1, "answer": "fly"}, {"n": 3, "type": "MCQ", "topic": "Spelling", "q": "Which spelling is correct?\\n(a) freind (b) frend (c) friend (d) friynd", "marks": 1, "answer": "(c) friend"}, {"n": 4, "type": "True/False", "topic": "Capital letters", "q": "A sentence always begins with a capital letter. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Word meanings", "q": "Match the word with its meaning:\\n(i) glad        (a) very small\\n(ii) tiny        (b) happy", "marks": 1, "answer": "(i) glad - (b) happy; (ii) tiny - (a) very small (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Punctuation", "q": "Rewrite using capital letters and the correct punctuation mark:\\n(a) rohan lives in delhi\\n(b) where do you live", "marks": 2, "answer": "(a) Rohan lives in Delhi. (b) Where do you live? (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Rhyming words in a poem", "q": "Read:\\n'The sun comes up, so bright and round,\\nThe birds all sing a happy sound.\\nThe flowers wake and start to play,\\nHello, hello, a brand-new day!'\\nWrite two pairs of rhyming words from the poem.", "marks": 2, "answer": "round - sound; play - day (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Poem comprehension", "q": "Read the poem in Q7 again.\\n(a) What do the birds do?\\n(b) At what time of the day is the poem set?", "marks": 2, "answer": "(a) The birds sing a happy sound. (b) In the morning (when the sun comes up). (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Paragraph writing", "q": "Write a paragraph of 5-6 sentences on 'My Best Friend'.\\nHints: name, class, looks, what you do together, why you like him/her.", "marks": 5, "answer": "Content: 3 marks (covers name, activities together, reason for liking). Language: 2 marks (correct sentences, capital letters, full stops, spelling). Sample: My best friend is Aman. He is in my class. He is tall and cheerful. We play football together. He shares his tiffin with me. I like him because he is kind."}, {"n": 10, "type": "Activity", "topic": "Describing words (adjectives)", "q": "Bring or think of your favourite fruit. Write 4 describing words about it (colour, shape, taste, size). Then say one sentence using two of these words.", "marks": 4, "answer": "½ mark for each correct describing word (2 marks), 2 marks for a correct sentence using two of them. Example: mango - yellow, sweet, juicy, oval. 'The mango is yellow and sweet.'"}]}, "Maths": {"book": "Maths Mela", "questions": [{"n": 1, "type": "MCQ", "topic": "Place value (3-digit numbers)", "q": "What is the place value of 5 in 352?\\n(a) 5 (b) 50 (c) 500 (d) 3", "marks": 1, "answer": "(b) 50"}, {"n": 2, "type": "Fill in the blank", "topic": "Multiplication tables", "q": "7 × 6 = ____", "marks": 1, "answer": "42"}, {"n": 3, "type": "MCQ", "topic": "Half (fractions)", "q": "What is half of 18?\\n(a) 8 (b) 6 (c) 9 (d) 12", "marks": 1, "answer": "(c) 9"}, {"n": 4, "type": "True/False", "topic": "Measurement of length", "q": "1 metre = 100 centimetres. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Fill in the blank", "topic": "Number names", "q": "Write the number name of 406: ______________", "marks": 1, "answer": "Four hundred six"}, {"n": 6, "type": "Short answer", "topic": "Addition and subtraction of 3-digit numbers", "q": "Solve:\\n(a) 245 + 132 = ____\\n(b) 568 - 243 = ____", "marks": 2, "answer": "(a) 377 (b) 325 (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Division as equal sharing", "q": "24 sweets are shared equally among 4 children. How many sweets does each child get?", "marks": 2, "answer": "24 ÷ 4 = 6. Each child gets 6 sweets. (1 mark for method, 1 mark for answer)"}, {"n": 8, "type": "Short answer", "topic": "Time", "q": "(a) The short hand of a clock is at 3 and the long hand is at 12. What time is it?\\n(b) What time will it be half an hour later?", "marks": 2, "answer": "(a) 3 o'clock (3:00) (b) Half past 3 (3:30) (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Word problems (addition, subtraction, division)", "q": "A fruit seller had 250 mangoes. He sold 115 in the morning and 87 in the evening.\\n(a) How many mangoes did he sell in all?\\n(b) How many mangoes are left?\\n(c) He packs the leftover mangoes in boxes of 6. How many boxes does he fill?", "marks": 5, "answer": "(a) 115 + 87 = 202 mangoes (2 marks) (b) 250 - 202 = 48 mangoes (2 marks) (c) 48 ÷ 6 = 8 boxes (1 mark)"}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Place value (thinking)", "q": "Use the digits 2, 7 and 5 (each only once) to make:\\n(a) the biggest 3-digit number\\n(b) the smallest 3-digit number\\n(c) Find their difference.", "marks": 4, "answer": "(a) 752 (1 mark) (b) 257 (1 mark) (c) 752 - 257 = 495 (2 marks)"}]}, "Hindi": {"book": "वीणा", "questions": [{"n": 1, "type": "MCQ", "topic": "समान अर्थ वाले शब्द", "q": "'पानी' का समान अर्थ वाला शब्द कौन-सा है?\\n(क) आग (ख) जल (ग) हवा (घ) धरती", "marks": 1, "answer": "(ख) जल"}, {"n": 2, "type": "Fill in the blank", "topic": "लिंग", "q": "'लड़का' का स्त्रीलिंग शब्द लिखिए: ____", "marks": 1, "answer": "लड़की"}, {"n": 3, "type": "MCQ", "topic": "संज्ञा", "q": "इनमें से संज्ञा शब्द कौन-सा है?\\n(क) दौड़ना (ख) सुंदर (ग) दिल्ली (घ) धीरे", "marks": 1, "answer": "(ग) दिल्ली"}, {"n": 4, "type": "True/False", "topic": "विलोम शब्द", "q": "'ऊँचा' का विलोम शब्द 'नीचा' है। सही या गलत लिखिए।", "marks": 1, "answer": "सही"}, {"n": 5, "type": "Match the following", "topic": "वचन", "q": "एकवचन का बहुवचन से मिलान कीजिए:\\n(i) चिड़िया        (क) पुस्तकें\\n(ii) पुस्तक        (ख) चिड़ियाँ", "marks": 1, "answer": "(i) चिड़िया - (ख) चिड़ियाँ; (ii) पुस्तक - (क) पुस्तकें (आधा-आधा अंक)"}, {"n": 6, "type": "Short answer", "topic": "शुद्ध वर्तनी", "q": "सही वर्तनी वाला शब्द चुनकर लिखिए:\\n(क) किताब / कीताब\\n(ख) दुध / दूध", "marks": 2, "answer": "(क) किताब (ख) दूध (1-1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "अपठित गद्यांश", "q": "पढ़िए:\\n'सोनू हर सुबह जल्दी उठता है। वह अपने दादाजी के साथ बगीचे में टहलने जाता है। दादाजी उसे पेड़-पौधों के नाम बताते हैं। सोनू को नीम का पेड़ सबसे अच्छा लगता है, क्योंकि उसकी छाया ठंडी होती है।'\\n(क) सोनू किसके साथ टहलने जाता है?\\n(ख) सोनू को कौन-सा पेड़ सबसे अच्छा लगता है?", "marks": 2, "answer": "(क) सोनू अपने दादाजी के साथ टहलने जाता है। (ख) नीम का पेड़। (1-1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "गद्यांश और संज्ञा", "q": "प्रश्न 7 का गद्यांश फिर से पढ़िए।\\n(क) सोनू को नीम का पेड़ क्यों अच्छा लगता है?\\n(ख) गद्यांश से कोई दो संज्ञा शब्द लिखिए।", "marks": 2, "answer": "(क) क्योंकि उसकी छाया ठंडी होती है। (1 अंक) (ख) कोई दो - सोनू, दादाजी, बगीचा, नीम, पेड़, सुबह (आधा-आधा अंक)"}, {"n": 9, "type": "Long answer", "topic": "अनुच्छेद लेखन", "q": "'मेरा प्रिय त्योहार' पर 5-6 वाक्य लिखिए।\\nसंकेत: त्योहार का नाम, कब आता है, कैसे मनाते हैं, क्या खाते हैं, क्यों पसंद है।", "marks": 5, "answer": "विषय-वस्तु 3 अंक, भाषा (सही वाक्य, वर्तनी, पूर्ण विराम) 2 अंक। उदाहरण: मेरा प्रिय त्योहार दीवाली है। यह अक्टूबर या नवंबर में आता है। इस दिन हम घर साफ़ करते हैं और दीये जलाते हैं। हम मिठाइयाँ खाते और बाँटते हैं। मुझे दीवाली बहुत अच्छी लगती है।"}, {"n": 10, "type": "Thinking (HOTS)", "topic": "वाक्य बनाना", "q": "इन शब्दों से एक-एक वाक्य बनाइए:\\nखेलना, पेड़, माँ, बारिश", "marks": 4, "answer": "हर सही और अर्थपूर्ण वाक्य के लिए 1 अंक। उदाहरण: मुझे मैदान में खेलना अच्छा लगता है। पेड़ हमें छाया देता है। मेरी माँ खाना बनाती हैं। बारिश में मोर नाचता है।"}]}, "EVS": {"book": "Our Wondrous World", "questions": [{"n": 1, "type": "MCQ", "topic": "Getting to know plants", "q": "Which part of a plant makes food for it?\\n(a) root (b) stem (c) leaf (d) flower", "marks": 1, "answer": "(c) leaf"}, {"n": 2, "type": "Fill in the blank", "topic": "Water - a precious gift", "q": "We should not waste ______ because it is precious and we cannot live without it.", "marks": 1, "answer": "water"}, {"n": 3, "type": "MCQ", "topic": "Animals around us", "q": "Which animal lives in water?\\n(a) goat (b) fish (c) parrot (d) cat", "marks": 1, "answer": "(b) fish"}, {"n": 4, "type": "True/False", "topic": "Food we eat", "q": "Eating fruits and vegetables helps us stay healthy. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Plants and animals live together", "q": "Match what we get from each animal:\\n(i) cow        (a) honey\\n(ii) honeybee        (b) milk", "marks": 1, "answer": "(i) cow - (b) milk; (ii) honeybee - (a) honey (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Water - a precious gift", "q": "Write two ways to save water at home.", "marks": 2, "answer": "Any two: close the tap while brushing; use a bucket instead of a shower; fix leaking taps; reuse water from washing vegetables to water plants (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Getting to know plants", "q": "Write two things that plants give us.", "marks": 2, "answer": "Any two: fruits, vegetables, shade, wood, flowers, oxygen/fresh air, medicines (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Taking charge of waste", "q": "Sort this waste into wet waste and dry waste:\\nbanana peel, paper, vegetable peels, plastic bottle", "marks": 2, "answer": "Wet waste: banana peel, vegetable peels. Dry waste: paper, plastic bottle. (½ mark each)"}, {"n": 9, "type": "Long answer", "topic": "Staying healthy and happy", "q": "Write five good habits that keep us healthy and happy.", "marks": 5, "answer": "Any five (1 mark each): wash hands before eating; brush teeth twice a day; bathe daily; eat fresh fruits and vegetables; drink enough water; play outdoors/exercise; sleep on time; keep surroundings clean; share and be kind to others."}, {"n": 10, "type": "Activity", "topic": "Plants and animals live together", "q": "Observe a tree near your home or school and write:\\n(a) Name of the tree\\n(b) Shape of its leaves\\n(c) One bird or animal you saw on or near it\\n(d) One way this tree helps us", "marks": 4, "answer": "1 mark for each sensible answer based on real observation, e.g. (a) Neem (b) long and pointed with jagged edges (c) squirrel / crow / ants (d) gives shade / fresh air. Accept any correct local tree."}]}, "Arts": {"book": "Bansuri", "questions": [{"n": 1, "type": "MCQ", "topic": "Colours (visual arts)", "q": "What colour do we get when we mix yellow and blue?\\n(a) orange (b) purple (c) green (d) pink", "marks": 1, "answer": "(c) green"}, {"n": 2, "type": "Fill in the blank", "topic": "Primary colours", "q": "Red, blue and yellow are called ______ colours.", "marks": 1, "answer": "primary"}, {"n": 3, "type": "MCQ", "topic": "Musical instruments", "q": "Which of these is a musical instrument?\\n(a) tabla (b) spoon (c) pillow (d) bucket", "marks": 1, "answer": "(a) tabla"}, {"n": 4, "type": "True/False", "topic": "Clay modelling", "q": "We can make toys and shapes with clay. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Musical instruments", "q": "Match the instrument with how it is played:\\n(i) flute (bansuri)        (a) played by beating with hands\\n(ii) dholak        (b) played by blowing air", "marks": 1, "answer": "(i) flute - (b) played by blowing air; (ii) dholak - (a) played by beating with hands (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Art from nature", "q": "Name two things from nature that we can use to make art.", "marks": 2, "answer": "Any two: leaves, flowers, twigs, stones, seeds, sand, feathers (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Folk dances of India", "q": "Name two folk dances of India.", "marks": 2, "answer": "Any two, e.g. Bhangra (Punjab), Garba (Gujarat), Bihu (Assam), Ghoomar (Rajasthan), Lavani (Maharashtra) (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Care of art materials", "q": "Write two things you should do with your art materials after the art class.", "marks": 2, "answer": "Any two: close colour/glue bottles; wash brushes; put materials back in the box; clean the desk; throw waste paper in the dustbin (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Leaf printing", "q": "Write 5 steps to make a leaf print on paper.", "marks": 5, "answer": "1 mark per correct step in order: 1) Collect a fresh leaf with clear veins. 2) Apply poster/water colour on the back (vein side) of the leaf with a brush. 3) Place the coloured side down on the paper. 4) Press gently all over (with a cloth or hand). 5) Lift the leaf carefully and let the print dry."}, {"n": 10, "type": "Activity", "topic": "Theatre: role play", "q": "Choose an animal (like an elephant, cat or monkey). Act like it in front of the class for 1 minute - show how it walks, the sound it makes and its face.", "marks": 4, "answer": "1 mark each for: correct walk/movement; correct sound; facial expression; confidence and involvement. Encourage every child; do not mark for perfection."}]}, "Physical Education": {"book": "Khel Yoga", "questions": [{"n": 1, "type": "MCQ", "topic": "Warm-up", "q": "What should we do before we start playing or exercising?\\n(a) sleep (b) warm-up (c) eat a big meal (d) watch TV", "marks": 1, "answer": "(b) warm-up"}, {"n": 2, "type": "Fill in the blank", "topic": "Yoga asanas", "q": "Tadasana is also called the ______ pose.", "marks": 1, "answer": "mountain"}, {"n": 3, "type": "MCQ", "topic": "Games and sports", "q": "Which game is played with a bat and a ball?\\n(a) kabaddi (b) kho-kho (c) cricket (d) swimming", "marks": 1, "answer": "(c) cricket"}, {"n": 4, "type": "True/False", "topic": "Health and hygiene", "q": "We should drink water after playing. Write True or False.", "marks": 1, "answer": "True"}, {"n": 5, "type": "Match the following", "topic": "Yoga asanas", "q": "Match the asana with its English name:\\n(i) Vrikshasana        (a) cobra pose\\n(ii) Bhujangasana        (b) tree pose", "marks": 1, "answer": "(i) Vrikshasana - (b) tree pose; (ii) Bhujangasana - (a) cobra pose (½ mark each)"}, {"n": 6, "type": "Short answer", "topic": "Safety in play", "q": "Write two safety rules to follow while playing.", "marks": 2, "answer": "Any two: wear proper shoes; play in a safe, clear area; do not push others; follow the teacher's instructions; tell an adult if hurt (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Benefits of yoga and exercise", "q": "Write two benefits of doing yoga or exercise every day.", "marks": 2, "answer": "Any two: keeps body fit and strong; makes body flexible; helps us focus; keeps us happy and calm; helps us sleep well (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Traditional Indian games", "q": "Name two traditional Indian games.", "marks": 2, "answer": "Any two: kho-kho, kabaddi, gilli-danda, pitthu (lagori), langdi, stapu (hopscotch) (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Tadasana", "q": "Write 5 steps to do Tadasana (mountain pose).", "marks": 5, "answer": "1 mark per step: 1) Stand straight with feet together and arms by your sides. 2) Join your fingers and raise both arms above your head. 3) Breathe in and slowly rise up on your toes. 4) Stretch your whole body up and hold for a few seconds, looking ahead. 5) Breathe out and slowly come back down, lowering your arms."}, {"n": 10, "type": "Activity", "topic": "Fitness activity", "q": "Do 10 jumping jacks with your teacher. Then put your hand on your chest and tell: Is your heart beating faster or slower? How is your breathing?", "marks": 4, "answer": "1 mark each: takes part willingly; does jumping jacks with correct arm-leg movement; counts to 10 correctly; says the heart beats faster and breathing becomes faster after exercise."}]}}, "4": {"English": {"book": "Santoor", "questions": [{"n": 1, "type": "MCQ", "topic": "Nouns", "q": "Which of these words is a noun?\\n(a) run (b) happy (c) garden (d) quickly", "marks": 1, "answer": "(c) garden"}, {"n": 2, "type": "Fill in the blank", "topic": "Articles", "q": "Fill in the blank with 'a' or 'an': I saw ___ owl sitting on the tree.", "marks": 1, "answer": "an"}, {"n": 3, "type": "True/False", "topic": "Opposites", "q": "State True or False: The opposite of 'early' is 'late'.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Singular and Plural", "q": "What is the plural of 'child'?\\n(a) childs (b) childes (c) children (d) childrens", "marks": 1, "answer": "(c) children"}, {"n": 5, "type": "Fill in the blank", "topic": "Punctuation", "q": "Put the correct punctuation mark at the end of the sentence: What is your name___", "marks": 1, "answer": "? (question mark), because the sentence asks a question."}, {"n": 6, "type": "Short answer", "topic": "Reading comprehension", "q": "Read: 'Meena planted a small mango seed in her backyard. Every morning she watered it. After many weeks, a tiny green shoot came out. Meena clapped with joy and ran to tell her grandmother.'\\nWhat did Meena plant? What did she do every morning?", "marks": 2, "answer": "Meena planted a small mango seed (1 mark). She watered it every morning (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Verbs (action words)", "q": "Pick out the three action words (verbs) in this sentence and use any one of them in a sentence of your own: 'The children sing, dance and play in the park.'", "marks": 2, "answer": "Verbs: sing, dance, play (1 mark). Any correct sentence using one of them, e.g. 'My sister sings a sweet song.' (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Poem: rhyming words", "q": "Read the lines:\\n'The rain comes down with a pitter-pat,\\nIt taps on my window and on my hat.'\\n(a) Write the pair of rhyming words. (b) What sound does the rain make?", "marks": 2, "answer": "(a) pat - hat (1 mark). (b) The rain makes a 'pitter-pat' sound (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Paragraph writing", "q": "Write a paragraph of 80-100 words on 'My Favourite Festival'. Say which festival it is, how you prepare for it, what you eat and do, and why you like it.", "marks": 5, "answer": "Marking points: Names the festival and when it comes (1); how the family prepares - cleaning, decorating, shopping (1); food and activities on the day (1); why the writer likes it / feelings (1); correct sentences, spelling and punctuation, within word limit (1)."}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Creative thinking", "q": "Imagine you find a lost, hungry puppy near your school gate. Write four sentences telling what you would do and why.", "marks": 4, "answer": "Any four sensible sentences, 1 mark each, e.g. I would give it water and some food. I would tell my teacher or parents. I would ask people nearby if they know its owner. If no owner is found, I would take help from an animal shelter. (Credit kindness, safety - not touching an injured/aggressive animal alone - and correct sentences.)"}]}, "Maths": {"book": "Maths Mela", "questions": [{"n": 1, "type": "MCQ", "topic": "Place value", "q": "What is the place value of 7 in 4,725?\\n(a) 7 (b) 70 (c) 700 (d) 7000", "marks": 1, "answer": "(c) 700"}, {"n": 2, "type": "Fill in the blank", "topic": "Measurement of length", "q": "1 metre = ___ centimetres.", "marks": 1, "answer": "100"}, {"n": 3, "type": "True/False", "topic": "Shapes", "q": "State True or False: A triangle has 4 corners.", "marks": 1, "answer": "False. A triangle has 3 corners and 3 sides."}, {"n": 4, "type": "MCQ", "topic": "Fractions", "q": "Which fraction shows 'half'?\\n(a) 1/4 (b) 1/2 (c) 1/3 (d) 2/3", "marks": 1, "answer": "(b) 1/2"}, {"n": 5, "type": "Fill in the blank", "topic": "Multiplication", "q": "25 × 4 = ___", "marks": 1, "answer": "100"}, {"n": 6, "type": "Short answer", "topic": "Money", "q": "Riya bought a pencil for ₹15 and an eraser for ₹8. She gave the shopkeeper ₹50. How much money will she get back?", "marks": 2, "answer": "Total cost = 15 + 8 = ₹23 (1 mark). Change = 50 - 23 = ₹27 (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Time", "q": "A movie started at 3:30 pm and ended at 5:15 pm. How long was the movie?", "marks": 2, "answer": "3:30 pm to 5:00 pm = 1 hour 30 minutes; 5:00 pm to 5:15 pm = 15 minutes (1 mark). Total = 1 hour 45 minutes (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Patterns", "q": "Find the next two numbers and write the rule: 5, 10, 20, 40, ___, ___", "marks": 2, "answer": "80, 160 (1 mark). Rule: each number is double (× 2) the number before it (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Multiplication and division (word problems)", "q": "A school has 4 classes with 36 students in each class.\\n(a) How many students are there in all?\\n(b) If all the students are put into groups of 8, how many groups are formed?\\n(c) If 58 students are girls, how many are boys?", "marks": 5, "answer": "(a) 36 × 4 = 144 students (2 marks: method 1, answer 1). (b) 144 ÷ 8 = 18 groups (2 marks: method 1, answer 1). (c) 144 - 58 = 86 boys (1 mark)."}, {"n": 10, "type": "Activity", "topic": "Data handling", "q": "Children's favourite fruits: Mango 12, Apple 8, Banana 6, Grapes 4.\\n(a) Which fruit is liked most? (b) How many more children like mango than grapes? (c) How many children in all? (d) Draw a pictograph where one ☺ = 2 children. How many ☺ for mango?", "marks": 4, "answer": "(a) Mango (1). (b) 12 - 4 = 8 more (1). (c) 12 + 8 + 6 + 4 = 30 children (1). (d) Mango = 12 ÷ 2 = 6 symbols; pictograph: Apple 4, Banana 3, Grapes 2 symbols, with key (1)."}]}, "Hindi": {"book": "Veena", "questions": [{"n": 1, "type": "MCQ", "topic": "संज्ञा", "q": "इनमें से संज्ञा शब्द कौन-सा है?\\n(a) दौड़ना (b) सुंदर (c) किताब (d) धीरे", "marks": 1, "answer": "(c) किताब"}, {"n": 2, "type": "Fill in the blank", "topic": "विलोम शब्द", "q": "'दिन' का विलोम शब्द ___ है।", "marks": 1, "answer": "रात"}, {"n": 3, "type": "True/False", "topic": "पर्यायवाची शब्द", "q": "सही या गलत लिखिए: 'पानी' का पर्यायवाची शब्द 'जल' है।", "marks": 1, "answer": "सही"}, {"n": 4, "type": "MCQ", "topic": "वचन", "q": "'लड़का' शब्द का बहुवचन क्या होगा?\\n(a) लड़की (b) लड़के (c) लड़कियाँ (d) लड़कों", "marks": 1, "answer": "(b) लड़के"}, {"n": 5, "type": "Fill in the blank", "topic": "लिंग", "q": "'शेर' का स्त्रीलिंग ___ होता है।", "marks": 1, "answer": "शेरनी"}, {"n": 6, "type": "Short answer", "topic": "अपठित गद्यांश", "q": "गद्यांश पढ़िए: 'रीना हर सुबह जल्दी उठती है। वह अपने बगीचे के पौधों को पानी देती है। पौधों पर रंग-बिरंगे फूल खिलते हैं। तितलियाँ फूलों पर मँडराती हैं। रीना को यह देखकर बहुत खुशी होती है।'\\n(क) रीना हर सुबह क्या करती है? (ख) फूलों पर कौन मँडराती हैं?", "marks": 2, "answer": "(क) रीना हर सुबह जल्दी उठकर बगीचे के पौधों को पानी देती है। (1 अंक) (ख) फूलों पर तितलियाँ मँडराती हैं। (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "कविता - तुकांत शब्द", "q": "कविता की पंक्तियाँ पढ़िए:\\n'चिड़िया रानी, चिड़िया रानी,\\nपीती है नदिया का पानी।\\nदाना चुगती, गाना गाती,\\nसुबह-सुबह सबको जगाती।'\\n(क) दो तुकांत शब्द-जोड़े लिखिए। (ख) चिड़िया सुबह-सुबह क्या करती है?", "marks": 2, "answer": "(क) रानी-पानी, गाती-जगाती (1 अंक) (ख) चिड़िया सुबह-सुबह गाना गाकर सबको जगाती है। (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "वाक्य रचना", "q": "निम्नलिखित शब्दों से एक-एक वाक्य बनाइए: (क) मित्र (ख) बादल", "marks": 2, "answer": "कोई भी सही वाक्य, जैसे - (क) मेरा मित्र मेरे साथ स्कूल जाता है। (1 अंक) (ख) आकाश में काले बादल छाए हैं। (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "अनुच्छेद लेखन", "q": "'मेरा प्रिय खेल' विषय पर 60-80 शब्दों में एक अनुच्छेद लिखिए। खेल का नाम, कैसे खेला जाता है, आप किसके साथ खेलते हैं और यह आपको क्यों पसंद है - यह बताइए।", "marks": 5, "answer": "अंक-बिंदु: खेल का नाम और परिचय (1); खेल कैसे खेला जाता है (1); किसके साथ और कहाँ खेलते हैं (1); खेल पसंद होने के कारण व उससे लाभ (1); शुद्ध वर्तनी, सही वाक्य और शब्द-सीमा (1)।"}, {"n": 10, "type": "Thinking (HOTS)", "topic": "कल्पनाशील लेखन", "q": "कल्पना कीजिए कि पेड़ बोल सकते हैं। वे हम बच्चों से क्या कहेंगे? चार वाक्य लिखिए।", "marks": 4, "answer": "कोई भी चार सार्थक वाक्य (प्रत्येक 1 अंक), जैसे - हमें मत काटो। हम तुम्हें छाया, फल और साफ़ हवा देते हैं। हमें समय पर पानी दो। हर साल एक नया पेड़ ज़रूर लगाओ।"}]}, "EVS": {"book": "Our Wondrous World", "questions": [{"n": 1, "type": "MCQ", "topic": "Animals and their food", "q": "Which of these animals eats only plants?\\n(a) Tiger (b) Cow (c) Lion (d) Eagle", "marks": 1, "answer": "(b) Cow"}, {"n": 2, "type": "Fill in the blank", "topic": "Plants around us", "q": "Green plants make their own food in their ___.", "marks": 1, "answer": "leaves"}, {"n": 3, "type": "True/False", "topic": "Saving water", "q": "State True or False: We should keep the tap running while brushing our teeth.", "marks": 1, "answer": "False. We should close the tap to save water."}, {"n": 4, "type": "MCQ", "topic": "Directions", "q": "The Sun rises in the ___.\\n(a) West (b) North (c) East (d) South", "marks": 1, "answer": "(c) East"}, {"n": 5, "type": "Fill in the blank", "topic": "Useful animals", "q": "Honey is made by ___.", "marks": 1, "answer": "honeybees (bees)"}, {"n": 6, "type": "Short answer", "topic": "Water and its sources", "q": "Write two ways in which we can save water at home.", "marks": 2, "answer": "Any two, 1 mark each: close the tap while brushing; use a bucket instead of a shower; reuse water used for washing vegetables to water plants; repair leaking taps; collect rainwater."}, {"n": 7, "type": "Short answer", "topic": "Food and health", "q": "What is a balanced diet? Name two foods that give us energy.", "marks": 2, "answer": "A balanced diet has all the nutrients our body needs in the right amounts (1 mark). Energy foods: rice, wheat roti, potatoes, sugar/jaggery, ghee (any two) (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Shelter", "q": "What is the difference between a kutcha house and a pucca house? Give one material used for each.", "marks": 2, "answer": "A kutcha house is made of mud, straw, bamboo or wood and is not very strong; a pucca house is made of bricks, cement, iron and stone and is strong (1 mark). One material each, e.g. mud / bricks (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Water and its sources", "q": "Name any three sources of water. Why is it important to drink clean water? Describe two ways to make water safe for drinking.", "marks": 5, "answer": "Three sources, e.g. rain, river, well, pond, lake, tubewell/handpump (1.5 marks). Dirty water can carry germs that cause diseases like diarrhoea, cholera and typhoid (1.5 marks). Ways to make water safe: boiling, filtering through cloth or a water filter, using a water purifier or chlorine tablets (any two, 2 marks)."}, {"n": 10, "type": "Activity", "topic": "Maps and directions", "q": "Draw a simple map of the way from your home to your school. Mark your home, your school and at least three landmarks (like a shop, temple or park). Show North with an arrow.", "marks": 4, "answer": "Marking points: home and school clearly marked (1); at least three landmarks shown (1); path/road drawn connecting them in correct order (1); North direction arrow and labels/key (1)."}]}, "Arts": {"book": "Bansuri", "questions": [{"n": 1, "type": "MCQ", "topic": "Colours", "q": "Which of these is a primary colour?\\n(a) Green (b) Orange (c) Blue (d) Purple", "marks": 1, "answer": "(c) Blue"}, {"n": 2, "type": "Fill in the blank", "topic": "Mixing colours", "q": "Mixing red and yellow colours gives ___.", "marks": 1, "answer": "orange"}, {"n": 3, "type": "True/False", "topic": "Musical instruments", "q": "State True or False: The tabla is a percussion (rhythm) instrument.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Dances of India", "q": "Bharatanatyam is a classical dance from which state?\\n(a) Tamil Nadu (b) Punjab (c) Assam (d) Gujarat", "marks": 1, "answer": "(a) Tamil Nadu"}, {"n": 5, "type": "Fill in the blank", "topic": "Musical instruments", "q": "The flute called 'bansuri' is made from ___.", "marks": 1, "answer": "bamboo"}, {"n": 6, "type": "Short answer", "topic": "Colours", "q": "What are warm colours and cool colours? Give two examples of each.", "marks": 2, "answer": "Warm colours remind us of fire and the Sun and feel bright, e.g. red, orange, yellow (1 mark). Cool colours remind us of water, sky and leaves and feel calm, e.g. blue, green, purple (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Folk dances", "q": "Name any two folk dances of India and the state each belongs to.", "marks": 2, "answer": "Any two, 1 mark each: Bhangra - Punjab; Garba - Gujarat; Bihu - Assam; Ghoomar - Rajasthan; Lavani - Maharashtra."}, {"n": 8, "type": "Short answer", "topic": "Traditional art - Rangoli", "q": "What is a rangoli? Name two materials used to make it.", "marks": 2, "answer": "Rangoli is a colourful design made on the floor, usually at the doorstep, during festivals and special occasions (1 mark). Materials: coloured powder, rice flour, flower petals, chalk (any two) (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Theatre - Puppetry", "q": "Explain how you would make a simple paper-bag puppet. How can you use it to tell a short story to your class?", "marks": 5, "answer": "Marking points: materials - paper bag, colours, glue, scissors, wool/paper scraps (1); steps - draw/stick eyes, nose, mouth on the bag's flap so the mouth moves, add hair and clothes (2); performance - put hand inside, move the flap to 'talk', change voice for the character (1); story with a beginning, middle and end / a message (1)."}, {"n": 10, "type": "Activity", "topic": "Printing with nature", "q": "Do a leaf-printing activity. Collect three different leaves, apply paint on the veined side and press them on paper. Write the steps you followed and two things you noticed in the prints.", "marks": 4, "answer": "Marking points: materials listed - leaves, paint, brush, paper (1); correct steps in order - apply paint, press, lift gently (1); neat print of three leaves (1); two observations, e.g. veins are clearly seen, each leaf has a different shape/size (1)."}]}, "Physical Education": {"book": "Khel Yoga", "questions": [{"n": 1, "type": "MCQ", "topic": "Yoga asanas", "q": "Which asana is called the 'Tree Pose'?\\n(a) Tadasana (b) Vrikshasana (c) Bhujangasana (d) Shavasana", "marks": 1, "answer": "(b) Vrikshasana"}, {"n": 2, "type": "Fill in the blank", "topic": "Warm-up", "q": "We should do ___ exercises before playing any game to prepare our body.", "marks": 1, "answer": "warm-up"}, {"n": 3, "type": "True/False", "topic": "Health and hygiene", "q": "State True or False: We should drink water after playing hard to replace lost water.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Games and sports", "q": "Which game is played with a bat and a ball?\\n(a) Football (b) Cricket (c) Kabaddi (d) Kho-kho", "marks": 1, "answer": "(b) Cricket"}, {"n": 5, "type": "Fill in the blank", "topic": "Yoga asanas", "q": "In Bhujangasana, the body looks like a raised ___.", "marks": 1, "answer": "cobra (snake)"}, {"n": 6, "type": "Short answer", "topic": "Benefits of yoga", "q": "Write any two benefits of doing yoga every day.", "marks": 2, "answer": "Any two, 1 mark each: makes the body flexible; improves balance and posture; keeps the mind calm and improves concentration; makes muscles strong; improves breathing."}, {"n": 7, "type": "Short answer", "topic": "Safety in play", "q": "Write two safety rules to follow while playing in the playground.", "marks": 2, "answer": "Any two, 1 mark each: wear proper shoes and clothes; do not push others; play in open space away from sharp objects; follow the teacher's instructions; do warm-up first; use equipment properly."}, {"n": 8, "type": "Short answer", "topic": "Sportsmanship", "q": "What is 'fair play'? Give one example.", "marks": 2, "answer": "Fair play means following the rules honestly and respecting teammates, opponents and the referee (1 mark). Example: shaking hands after a game, accepting the referee's decision, helping a fallen player (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Traditional Indian games - Kabaddi", "q": "Explain how Kabaddi is played. Write about the teams, the raider, how players get out and how points are scored.", "marks": 5, "answer": "Marking points: two teams on a court divided into two halves (1); a raider enters the other team's half saying 'kabaddi-kabaddi' in one breath (1); the raider tries to touch defenders and return to his own half (1); touched defenders are out, and if defenders catch the raider before he returns, the raider is out (1); a team gets a point for each opponent put out, and the team with more points wins (1)."}, {"n": 10, "type": "Activity", "topic": "Fitness habits", "q": "Make a one-week fitness chart for yourself. Include one warm-up, one yoga asana and one outdoor game for each day, and tick the days you complete it.", "marks": 4, "answer": "Marking points: chart with 7 days (1); a warm-up activity listed (1); a yoga asana listed (1); an outdoor game listed, with a tick column to record completion (1)."}]}}, "5": {"English": {"book": "Santoor", "questions": [{"n": 1, "type": "MCQ", "topic": "Adjectives", "q": "Which word is an adjective in the sentence 'The tall boy won the race'?\\n(a) tall (b) boy (c) won (d) race", "marks": 1, "answer": "(a) tall"}, {"n": 2, "type": "Fill in the blank", "topic": "Simple past tense", "q": "Fill in the blank with the correct form of 'go': Yesterday we ___ to the zoo.", "marks": 1, "answer": "went"}, {"n": 3, "type": "True/False", "topic": "Adverbs", "q": "State True or False: In 'She ran quickly', the word 'quickly' is an adverb.", "marks": 1, "answer": "True. 'Quickly' tells us how she ran."}, {"n": 4, "type": "MCQ", "topic": "Synonyms", "q": "Which word means the same as 'enormous'?\\n(a) tiny (b) huge (c) quiet (d) fast", "marks": 1, "answer": "(b) huge"}, {"n": 5, "type": "Fill in the blank", "topic": "Prepositions", "q": "Fill in the blank with a suitable preposition: The cat is hiding ___ the table.", "marks": 1, "answer": "under (also accept 'below' or 'beneath')"}, {"n": 6, "type": "Short answer", "topic": "Reading comprehension", "q": "Read: 'Arjun lived in a village near the hills. One day, heavy rain flooded the small bridge over the stream. Arjun saw an old man trying to cross it. He held the man's hand and helped him walk safely to the other side. The man said, \"Kindness is the greatest strength.\"'\\nWhat problem did the old man face and how did Arjun help?", "marks": 2, "answer": "The bridge over the stream was flooded, so the old man could not cross safely (1 mark). Arjun held his hand and helped him walk safely to the other side (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Poem appreciation", "q": "Read the lines:\\n'The moon is a silver boat,\\nOn the dark sea it seems to float;\\nThe stars are tiny lamps that glow,\\nTo light its path as on we go.'\\n(a) What is the moon compared to? (b) Write two pairs of rhyming words.", "marks": 2, "answer": "(a) The moon is compared to a silver boat (1 mark). (b) boat - float, glow - go (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Sentences: negative and interrogative", "q": "Change the sentence 'She plays the guitar.' into (a) a negative sentence and (b) a question.", "marks": 2, "answer": "(a) She does not play the guitar. (1 mark) (b) Does she play the guitar? (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Informal letter writing", "q": "Write a letter to your friend telling him/her about a trip you took with your family during the holidays.", "marks": 5, "answer": "Marking points: correct format - address, date, greeting 'Dear ...' (1); opening lines asking about the friend (0.5); where you went, how you travelled, with whom (1); what you saw and did, one interesting experience (1.5); closing lines and signing off 'Your loving friend, name' (0.5); grammar, spelling and neatness (0.5)."}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Values and reflection", "q": "What does the saying 'Kindness is the greatest strength' mean? Describe one time when you or someone you know showed kindness, and how it made others feel.", "marks": 4, "answer": "Meaning: being kind and helpful to others is more powerful and valuable than physical strength or power (2 marks). A suitable real-life example of kindness, with how it made the other person feel (2 marks)."}]}, "Maths": {"book": "Maths Mela", "questions": [{"n": 1, "type": "MCQ", "topic": "Large numbers - comparison", "q": "Which is the largest number?\\n(a) 45,098 (b) 45,890 (c) 45,809 (d) 45,980", "marks": 1, "answer": "(d) 45,980"}, {"n": 2, "type": "Fill in the blank", "topic": "Equivalent fractions", "q": "3/4 = ___/8", "marks": 1, "answer": "6 (since 3 × 2 = 6 and 4 × 2 = 8)"}, {"n": 3, "type": "True/False", "topic": "Angles", "q": "State True or False: A right angle measures 90 degrees.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Perimeter", "q": "What is the perimeter of a square with side 6 cm?\\n(a) 12 cm (b) 24 cm (c) 36 cm (d) 18 cm", "marks": 1, "answer": "(b) 24 cm (4 × 6 = 24)"}, {"n": 5, "type": "Fill in the blank", "topic": "Measurement of weight", "q": "1 kilogram = ___ grams.", "marks": 1, "answer": "1000"}, {"n": 6, "type": "Short answer", "topic": "Area and perimeter", "q": "A rectangular garden is 12 m long and 8 m wide. Find its area and its perimeter.", "marks": 2, "answer": "Area = 12 × 8 = 96 square metres (1 mark). Perimeter = 2 × (12 + 8) = 2 × 20 = 40 m (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Fractions - addition and subtraction", "q": "Solve: (a) 2/5 + 1/5 (b) 3/4 - 1/2", "marks": 2, "answer": "(a) 3/5 (1 mark). (b) 3/4 - 2/4 = 1/4 (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Multiplication", "q": "Multiply: 2,345 × 24", "marks": 2, "answer": "2,345 × 4 = 9,380 and 2,345 × 20 = 46,900 (1 mark). 9,380 + 46,900 = 56,280 (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Word problems (four operations)", "q": "A shopkeeper had 1,250 kg of rice. He sold 475 kg on Monday and 380 kg on Tuesday.\\n(a) How much rice did he sell in all? (b) How much rice is left?\\n(c) He packs the rest into 5 kg bags. How many bags? (d) If each bag sells for ₹250, how much money will he get?", "marks": 5, "answer": "(a) 475 + 380 = 855 kg (1). (b) 1,250 - 855 = 395 kg (1). (c) 395 ÷ 5 = 79 bags (1). (d) 79 × 250 = ₹19,750 (2: method 1, answer 1)."}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Symmetry", "q": "Look at the capital letters A, B, F, H, M, N, S.\\n(a) Which letters have a vertical (standing) line of symmetry?\\n(b) Which letters have a horizontal (sleeping) line of symmetry?\\n(c) Which letter has both?\\n(d) Which letters have no line of symmetry?", "marks": 4, "answer": "(a) A, H, M (1). (b) B, H (1). (c) H (1). (d) F, N, S (1)."}]}, "Hindi": {"book": "Veena", "questions": [{"n": 1, "type": "MCQ", "topic": "सर्वनाम", "q": "'वह स्कूल जाता है।' - इस वाक्य में सर्वनाम शब्द कौन-सा है?\\n(a) स्कूल (b) वह (c) जाता (d) है", "marks": 1, "answer": "(b) वह"}, {"n": 2, "type": "Fill in the blank", "topic": "विशेषण", "q": "'लाल गुलाब' में विशेषण शब्द ___ है।", "marks": 1, "answer": "लाल"}, {"n": 3, "type": "True/False", "topic": "पर्यायवाची शब्द", "q": "सही या गलत लिखिए: 'आकाश' का पर्यायवाची शब्द 'धरती' है।", "marks": 1, "answer": "गलत। 'आकाश' के पर्यायवाची 'नभ', 'आसमान', 'गगन' हैं।"}, {"n": 4, "type": "MCQ", "topic": "मुहावरे", "q": "'आँखों का तारा' मुहावरे का अर्थ क्या है?\\n(a) बहुत प्यारा (b) आँख का रोग (c) आकाश का तारा (d) गुस्सा होना", "marks": 1, "answer": "(a) बहुत प्यारा"}, {"n": 5, "type": "Fill in the blank", "topic": "विलोम शब्द", "q": "'सुख' का विलोम शब्द ___ है।", "marks": 1, "answer": "दुख"}, {"n": 6, "type": "Short answer", "topic": "अपठित गद्यांश", "q": "गद्यांश पढ़िए: 'राजू के गाँव में एक पुराना बरगद का पेड़ था। गर्मियों में सब लोग उसकी छाया में बैठते थे। बच्चे उसकी डालियों पर झूला झूलते थे। एक दिन कुछ लोग पेड़ काटने आए। राजू और उसके दोस्तों ने पेड़ से लिपटकर उसे बचा लिया।'\\n(क) लोग पेड़ की छाया में कब बैठते थे? (ख) राजू ने पेड़ को कैसे बचाया?", "marks": 2, "answer": "(क) लोग गर्मियों में पेड़ की छाया में बैठते थे। (1 अंक) (ख) राजू और उसके दोस्तों ने पेड़ से लिपटकर उसे कटने से बचा लिया। (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "शुद्ध वर्तनी", "q": "निम्नलिखित शब्दों को शुद्ध करके लिखिए: (क) कीताब (ख) पाठशला (ग) बिमार (घ) दुध", "marks": 2, "answer": "(क) किताब (ख) पाठशाला (ग) बीमार (घ) दूध (प्रत्येक आधा अंक)"}, {"n": 8, "type": "Short answer", "topic": "वाक्य रचना", "q": "निम्नलिखित शब्दों से एक-एक वाक्य बनाइए: (क) परिश्रम (ख) ईमानदार", "marks": 2, "answer": "कोई भी सही वाक्य, जैसे - (क) परिश्रम करने से सफलता मिलती है। (1 अंक) (ख) रमेश एक ईमानदार लड़का है। (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "प्रार्थना-पत्र लेखन", "q": "बीमार होने के कारण दो दिन की छुट्टी के लिए अपने विद्यालय के प्रधानाचार्य को प्रार्थना-पत्र लिखिए।", "marks": 5, "answer": "अंक-बिंदु: सेवा में, पद और विद्यालय का पता (1); दिनांक और विषय (1); संबोधन 'महोदय/महोदया' (0.5); मुख्य भाग - बीमारी का कारण और छुट्टी की तिथियाँ (1.5); समापन - 'आपका आज्ञाकारी शिष्य/आपकी आज्ञाकारी शिष्या', नाम, कक्षा (1)।"}, {"n": 10, "type": "Thinking (HOTS)", "topic": "जल संरक्षण - चिंतन", "q": "यदि आपके मोहल्ले में पानी की कमी हो जाए, तो आप पानी बचाने के लिए कौन-से चार उपाय करेंगे? लिखिए।", "marks": 4, "answer": "कोई भी चार उपाय (प्रत्येक 1 अंक), जैसे - ब्रश करते समय नल बंद रखना; टपकते नल ठीक करवाना; सब्ज़ियाँ धोने वाले पानी से पौधों को सींचना; वर्षा का पानी इकट्ठा करना; बाल्टी से नहाना; लोगों को पानी बचाने के लिए जागरूक करना।"}]}, "EVS": {"book": "Our Wondrous World", "questions": [{"n": 1, "type": "MCQ", "topic": "Sense organs", "q": "Which sense organ helps us to smell?\\n(a) Eyes (b) Ears (c) Nose (d) Skin", "marks": 1, "answer": "(c) Nose"}, {"n": 2, "type": "Fill in the blank", "topic": "Water cycle", "q": "When water is heated by the Sun and changes into water vapour, the process is called ___.", "marks": 1, "answer": "evaporation"}, {"n": 3, "type": "True/False", "topic": "Seed dispersal", "q": "State True or False: Seeds can be carried to new places by wind, water and animals.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Natural resources", "q": "Which of these is a resource that can get used up and cannot be replaced quickly?\\n(a) Sunlight (b) Wind (c) Coal (d) Rainwater", "marks": 1, "answer": "(c) Coal"}, {"n": 5, "type": "Fill in the blank", "topic": "Health and diseases", "q": "Mosquitoes that spread malaria breed in stagnant (still) ___.", "marks": 1, "answer": "water"}, {"n": 6, "type": "Short answer", "topic": "Animals - migration", "q": "Why do some birds migrate? Name one bird that migrates to India in winter.", "marks": 2, "answer": "Some birds travel long distances to escape extreme cold and to find food and a safe place to breed (1 mark). Example: Siberian crane, flamingo, bar-headed goose (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Food - spoilage and preservation", "q": "Write two signs that food has spoiled and two ways to keep food fresh for a long time.", "marks": 2, "answer": "Signs (any two, 1 mark): bad smell, change in colour, fungus/mould, sour taste, sticky texture. Ways (any two, 1 mark): keeping in a refrigerator, drying in the sun, making pickles with salt/oil, making jam with sugar, keeping in airtight containers."}, {"n": 8, "type": "Short answer", "topic": "Maps", "q": "What is a map? Why do we use symbols on a map?", "marks": 2, "answer": "A map is a drawing of a place (large or small) on a flat surface as seen from above (1 mark). Symbols save space and make it easy to show things like roads, rivers, schools and hospitals clearly; a key explains them (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Water cycle", "q": "Explain the water cycle in steps. Imagine a picture showing the Sun heating a lake, clouds forming above, and rain falling on hills that flows back to the lake. Name each step and explain it.", "marks": 5, "answer": "Marking points: Evaporation - the Sun heats water in lakes, rivers and seas and it turns into water vapour (1); Condensation - vapour rises, cools and forms tiny drops that make clouds (1); Precipitation - drops join, become heavy and fall as rain, snow or hail (1); Collection - water flows through streams and rivers back to lakes and seas or soaks into the ground (1); the cycle repeats continuously and gives us fresh water (1)."}, {"n": 10, "type": "Thinking (HOTS)", "topic": "Cleanliness and community health", "q": "Many people in a village are falling ill with fever and stomach problems. There is a dirty pond near their houses where garbage is thrown. What could be the reasons? Suggest three things the villagers should do.", "marks": 4, "answer": "Reason: stagnant dirty water breeds mosquitoes (malaria, dengue) and germs that contaminate drinking water (1 mark). Any three suggestions (1 mark each): stop throwing garbage in the pond; clean the pond / do not let water stagnate; boil or filter drinking water; use mosquito nets; dispose garbage in dustbins; visit a doctor or health centre."}]}, "Arts": {"book": "Bansuri", "questions": [{"n": 1, "type": "MCQ", "topic": "Colours", "q": "Which colour do we get by mixing blue and yellow?\\n(a) Orange (b) Green (c) Purple (d) Brown", "marks": 1, "answer": "(b) Green"}, {"n": 2, "type": "Fill in the blank", "topic": "Classical dances of India", "q": "Kathakali is a classical dance from the state of ___.", "marks": 1, "answer": "Kerala"}, {"n": 3, "type": "True/False", "topic": "Musical instruments", "q": "State True or False: The sitar is a string instrument.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Folk art of India", "q": "Madhubani painting is a folk art of which state?\\n(a) Bihar (b) Kerala (c) Punjab (d) Rajasthan", "marks": 1, "answer": "(a) Bihar"}, {"n": 5, "type": "Fill in the blank", "topic": "Music - swaras", "q": "The seven basic notes in Indian music are Sa, Re, Ga, Ma, Pa, Dha and ___.", "marks": 1, "answer": "Ni"}, {"n": 6, "type": "Short answer", "topic": "Collage", "q": "What is a collage? Name two materials you can use to make one.", "marks": 2, "answer": "A collage is a picture made by sticking pieces of different materials on a surface (1 mark). Materials: old magazine cuttings, coloured paper, cloth pieces, leaves, buttons, seeds (any two) (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Drawing - types", "q": "What is the difference between a still-life drawing and a landscape drawing?", "marks": 2, "answer": "Still life is a drawing of non-moving objects arranged together, like a vase, fruits or bottles (1 mark). Landscape is a drawing of natural scenery, like hills, rivers, trees and sky (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Theatre - expressions", "q": "Why do actors use facial expressions and gestures in a play? Give one example.", "marks": 2, "answer": "Expressions and gestures show feelings and help the audience understand the story even without many words (1 mark). Example: waving a hand to say goodbye, a frown to show anger, wide eyes to show surprise (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Folk art - Warli", "q": "Describe Warli art. Where does it come from, which shapes are used, what colours are used and what does it usually show?", "marks": 5, "answer": "Marking points: made by the Warli tribe of Maharashtra (1); uses simple shapes - circle, triangle, square and lines; human figures are two triangles joined at the tip (1.5); white colour (traditionally rice paste) on a mud-red or brown background (1); shows daily life - farming, harvest, dancing in a circle, animals, trees, festivals (1.5)."}, {"n": 10, "type": "Activity", "topic": "Theatre - planning a skit", "q": "Plan a short skit on 'Keep Your School Clean' with your group. Write the names of the characters, two props you will use, and the message of the skit.", "marks": 4, "answer": "Marking points: at least three characters with roles, e.g. student, teacher, dustbin (1); two suitable props, e.g. broom, dustbin, placards (1); a short story outline with beginning, problem and solution (1); a clear message about cleanliness (1)."}]}, "Physical Education": {"book": "Khel Yoga", "questions": [{"n": 1, "type": "MCQ", "topic": "Yoga asanas", "q": "Which asana is done lying on the stomach?\\n(a) Bhujangasana (b) Tadasana (c) Vajrasana (d) Padmasana", "marks": 1, "answer": "(a) Bhujangasana"}, {"n": 2, "type": "Fill in the blank", "topic": "Pranayama", "q": "Pranayama is the practice of controlling our ___.", "marks": 1, "answer": "breath (breathing)"}, {"n": 3, "type": "True/False", "topic": "Games and sports", "q": "State True or False: In football, each team has 11 players on the field.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Nutrition for fitness", "q": "Which food is a good source of protein for a player?\\n(a) Dal (pulses) (b) Chips (c) Soft drinks (d) Candy", "marks": 1, "answer": "(a) Dal (pulses)"}, {"n": 5, "type": "Fill in the blank", "topic": "Posture", "q": "The way we hold our body while standing, sitting or walking is called ___.", "marks": 1, "answer": "posture"}, {"n": 6, "type": "Short answer", "topic": "Warm-up and cool-down", "q": "Why should we warm up before exercise and cool down after it?", "marks": 2, "answer": "Warm-up raises heart rate and body temperature and loosens muscles, preventing injury (1 mark). Cool-down slowly brings the heart rate back to normal, relaxes muscles and reduces stiffness (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "First aid", "q": "Your friend gets a small scrape on the knee while playing. What two things should you do?", "marks": 2, "answer": "Any two, 1 mark each: inform the teacher/adult; wash the wound gently with clean water; apply antiseptic; cover with a clean bandage; let the friend rest."}, {"n": 8, "type": "Short answer", "topic": "Components of fitness", "q": "Name two components of physical fitness and one activity that improves each.", "marks": 2, "answer": "Any two, 1 mark each: strength - push-ups/climbing; endurance (stamina) - running/cycling/swimming; flexibility - stretching/yoga; speed - sprinting; balance - Vrikshasana/walking on a line."}, {"n": 9, "type": "Long answer", "topic": "Surya Namaskar", "q": "What is Surya Namaskar? Write how many steps it has, three benefits, and two precautions to take while doing it.", "marks": 5, "answer": "Marking points: Surya Namaskar (Sun Salutation) is a set of yoga postures done in a flowing sequence with breathing (1); it has 12 steps/postures (1); benefits (any three) - improves flexibility, strengthens muscles, improves blood circulation and digestion, calms the mind (1.5); precautions (any two) - do on an empty stomach, move slowly without jerks, breathe correctly, stop if there is pain, practise under a teacher's guidance (1.5)."}, {"n": 10, "type": "Activity", "topic": "Measuring fitness", "q": "Count how many times you can skip with a rope in one minute, every day for five days. Record it in a table. Did your count improve? Write one reason why.", "marks": 4, "answer": "Marking points: neat table with day and count (1); five days of records (1); correct observation of whether the count increased or not (1); sensible reason, e.g. regular practice improves stamina, speed and coordination (1)."}]}}, "6": {"English": {"book": "Poorvi", "questions": [{"n": 1, "type": "MCQ", "topic": "Vocabulary: synonyms", "q": "Choose the word closest in meaning to 'brave'.\\n(a) timid (b) courageous (c) lazy (d) careless", "marks": 1, "answer": "(b) courageous"}, {"n": 2, "type": "Fill in the blank", "topic": "Grammar: prepositions", "q": "Fill in the blank with a suitable preposition: The cat is hiding ______ the table.", "marks": 1, "answer": "under (also accept: below/beneath)"}, {"n": 3, "type": "MCQ", "topic": "Grammar: articles", "q": "Choose the correct article: She saw ___ owl sitting on the branch.\\n(a) a (b) an (c) the (d) no article", "marks": 1, "answer": "(b) an"}, {"n": 4, "type": "Match the following", "topic": "Vocabulary: antonyms", "q": "Match each word with its opposite:\\n(i) ancient  (ii) generous\\n(a) selfish  (b) modern", "marks": 1, "answer": "(i)-(b) ancient-modern; (ii)-(a) generous-selfish (1/2 mark each)"}, {"n": 5, "type": "True/False", "topic": "Grammar: tenses", "q": "State True or False: The sentence 'Ravi plays football every evening' is in the simple past tense.", "marks": 1, "answer": "False. It is in the simple present tense (habitual action)."}, {"n": 6, "type": "Short answer", "topic": "Grammar: nouns and adjectives", "q": "Pick out two nouns and two adjectives from the sentence: 'The tall girl carried a heavy basket to the busy market.'", "marks": 2, "answer": "Nouns (any two): girl, basket, market. Adjectives (any two): tall, heavy, busy. (1/2 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Grammar: sentence types", "q": "Rewrite as directed:\\n(i) You are late. (Change into an interrogative sentence)\\n(ii) Close the window. (Change into a polite request)", "marks": 2, "answer": "(i) Are you late? (ii) Please close the window. / Could you please close the window? (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Vocabulary: using words in sentences", "q": "Use the following words in meaningful sentences of your own: (i) curious (ii) gratitude", "marks": 2, "answer": "Any correct sentence showing meaning, e.g. (i) The curious child asked many questions about the stars. (ii) She wrote a card to express her gratitude to her teacher. (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Writing: paragraph writing", "q": "Write a paragraph of about 100-120 words on 'A Day I Will Never Forget'. Describe what happened, where, who was with you and how you felt.", "marks": 5, "answer": "Marking points: Content - clear event, place, people involved, sequence of happenings (2 marks); Expression - feelings and reasons why the day is memorable, suitable vocabulary (1 mark); Organisation - opening sentence, logical flow, concluding line (1 mark); Accuracy - grammar, spelling, punctuation, word limit (1 mark)."}, {"n": 10, "type": "Case-based", "topic": "Reading comprehension (unseen passage)", "q": "Read the passage and answer:\\nMeena lived in a small village near a river. Every morning she watched the fishermen push their boats into the water. One day she noticed plastic bottles floating near the bank. The fish were fewer than before. Meena gathered her friends, and every Sunday they cleaned the riverbank. Soon, the villagers joined them. Within a few months, the river looked cleaner and the fishermen were happy again.\\n(i) Where did Meena live?\\n(ii) What problem did Meena notice?\\n(iii) What did Meena and her friends do every Sunday?\\n(iv) Find a word from the passage that means 'collected'.", "marks": 4, "answer": "(i) In a small village near a river. (ii) Plastic bottles were floating near the bank and the fish had become fewer. (iii) They cleaned the riverbank. (iv) gathered. (1 mark each)"}]}, "Hindi": {"book": "Malhar", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्द-भंडार: पर्यायवाची शब्द", "q": "'सूर्य' का पर्यायवाची शब्द चुनिए।\\n(a) चंद्रमा (b) दिनकर (c) नीरज (d) पवन", "marks": 1, "answer": "(b) दिनकर"}, {"n": 2, "type": "Fill in the blank", "topic": "शब्द-भंडार: विलोम शब्द", "q": "रिक्त स्थान भरिए: 'मीठा' का विलोम शब्द ______ है।", "marks": 1, "answer": "कड़वा"}, {"n": 3, "type": "True/False", "topic": "व्याकरण: विशेषण", "q": "सही या गलत लिखिए: 'लाल गुलाब बहुत सुंदर है' वाक्य में 'लाल' शब्द विशेषण है।", "marks": 1, "answer": "सही। 'लाल' शब्द संज्ञा 'गुलाब' की विशेषता (रंग) बताता है, इसलिए यह विशेषण है।"}, {"n": 4, "type": "Match the following", "topic": "व्याकरण: लिंग", "q": "उचित स्त्रीलिंग शब्द से मिलान कीजिए:\\n(i) घोड़ा  (ii) शेर\\n(a) शेरनी  (b) घोड़ी", "marks": 1, "answer": "(i)-(b) घोड़ा-घोड़ी; (ii)-(a) शेर-शेरनी (प्रत्येक के 1/2 अंक)"}, {"n": 5, "type": "MCQ", "topic": "व्याकरण: संज्ञा के भेद", "q": "'हिमालय' कौन-सी संज्ञा है?\\n(a) जातिवाचक (b) भाववाचक (c) व्यक्तिवाचक (d) समूहवाचक", "marks": 1, "answer": "(c) व्यक्तिवाचक संज्ञा, क्योंकि यह एक विशेष पर्वत का नाम है।"}, {"n": 6, "type": "Short answer", "topic": "मुहावरे", "q": "निम्नलिखित मुहावरों के अर्थ लिखकर एक-एक वाक्य बनाइए:\\n(i) आँखों का तारा (ii) नौ दो ग्यारह होना", "marks": 2, "answer": "(i) आँखों का तारा - बहुत प्यारा। वाक्य: छोटा बेटा माँ की आँखों का तारा है। (ii) नौ दो ग्यारह होना - भाग जाना। वाक्य: पुलिस को देखते ही चोर नौ दो ग्यारह हो गया। (प्रत्येक के 1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "व्याकरण: वचन", "q": "निम्नलिखित शब्दों के बहुवचन रूप लिखिए:\\nकिताब, नदी, कपड़ा, बच्चा", "marks": 2, "answer": "किताब - किताबें; नदी - नदियाँ; कपड़ा - कपड़े; बच्चा - बच्चे (प्रत्येक के 1/2 अंक)"}, {"n": 8, "type": "Short answer", "topic": "व्याकरण: सर्वनाम", "q": "सर्वनाम किसे कहते हैं? दिए गए वाक्य से सर्वनाम शब्द छाँटिए:\\n'वह रोज़ विद्यालय जाती है और अपना काम स्वयं करती है।'", "marks": 2, "answer": "संज्ञा के स्थान पर प्रयोग होने वाले शब्दों को सर्वनाम कहते हैं (1 अंक)। वाक्य में सर्वनाम: वह, अपना, स्वयं (1 अंक)।"}, {"n": 9, "type": "Long answer", "topic": "लेखन: प्रार्थना-पत्र", "q": "अपने विद्यालय के प्रधानाचार्य को बीमारी के कारण दो दिन का अवकाश माँगने हेतु एक प्रार्थना-पत्र लिखिए।", "marks": 5, "answer": "अंक-विभाजन: प्रारंभ - सेवा में, प्रधानाचार्य, विद्यालय का नाम व पता, दिनांक (1 अंक); विषय - दो दिन के अवकाश हेतु प्रार्थना-पत्र, संबोधन - महोदय/महोदया (1 अंक); मुख्य भाग - बुखार/बीमारी का कारण, अवकाश की तिथियाँ, विनम्र अनुरोध (2 अंक); समापन - धन्यवाद सहित, आपका आज्ञाकारी शिष्य/आपकी आज्ञाकारिणी शिष्या, नाम, कक्षा, अनुक्रमांक (1 अंक)।"}, {"n": 10, "type": "Case-based", "topic": "अपठित गद्यांश", "q": "गद्यांश पढ़कर प्रश्नों के उत्तर दीजिए:\\nपेड़ हमारे सच्चे मित्र हैं। वे हमें फल, फूल, लकड़ी और छाया देते हैं। पेड़ हवा को शुद्ध करते हैं और वर्षा लाने में सहायता करते हैं। अनेक पक्षी पेड़ों पर घोंसले बनाकर रहते हैं। आजकल मनुष्य अपने स्वार्थ के लिए पेड़ काट रहा है, जिससे प्रदूषण बढ़ रहा है। हमें अधिक से अधिक पेड़ लगाने चाहिए और उनकी रक्षा करनी चाहिए।\\n(i) पेड़ हमें क्या-क्या देते हैं?\\n(ii) पक्षी पेड़ों पर क्या बनाते हैं?\\n(iii) पेड़ काटने से क्या हानि हो रही है?\\n(iv) 'मित्र' शब्द का विलोम लिखिए।", "marks": 4, "answer": "(i) फल, फूल, लकड़ी और छाया। (ii) घोंसले। (iii) प्रदूषण बढ़ रहा है। (iv) शत्रु। (प्रत्येक के 1 अंक)"}]}, "Maths": {"book": "Ganita Prakash", "questions": [{"n": 1, "type": "MCQ", "topic": "Prime time", "q": "Which of the following is a prime number?\\n(a) 21 (b) 27 (c) 29 (d) 33", "marks": 1, "answer": "(c) 29 (its only factors are 1 and 29; 21=3x7, 27=3x9, 33=3x11)"}, {"n": 2, "type": "Fill in the blank", "topic": "Patterns in mathematics", "q": "The sum of the first 5 odd numbers (1 + 3 + 5 + 7 + 9) is ______.", "marks": 1, "answer": "25 (the sum of the first n odd numbers is n x n; 5 x 5 = 25)"}, {"n": 3, "type": "True/False", "topic": "Symmetry", "q": "State True or False: A square has 4 lines of symmetry.", "marks": 1, "answer": "True. Two diagonals and two lines joining midpoints of opposite sides."}, {"n": 4, "type": "Assertion-Reason", "topic": "The other side of zero (integers)", "q": "Assertion (A): -5 is less than -2.\\nReason (R): On a number line, a number to the left of another number is smaller.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A. (-5 lies to the left of -2 on the number line.)"}, {"n": 5, "type": "MCQ", "topic": "Lines and angles", "q": "An angle that measures exactly 90 degrees is called:\\n(a) an acute angle (b) a right angle (c) an obtuse angle (d) a straight angle", "marks": 1, "answer": "(b) a right angle"}, {"n": 6, "type": "Short answer", "topic": "Perimeter and area", "q": "A rectangular garden is 12 m long and 7 m wide. Find (i) its perimeter and (ii) its area.", "marks": 2, "answer": "(i) Perimeter = 2 x (12 + 7) = 2 x 19 = 38 m (1 mark). (ii) Area = 12 x 7 = 84 sq m (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Fractions", "q": "Find: (i) 3/4 + 1/6  (ii) 5/6 - 1/4", "marks": 2, "answer": "(i) LCM of 4 and 6 is 12: 9/12 + 2/12 = 11/12 (1 mark). (ii) 10/12 - 3/12 = 7/12 (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "Prime time", "q": "Write the prime factorisation of 84. Using the divisibility rule, check whether 84 is divisible by 4.", "marks": 2, "answer": "84 = 2 x 2 x 3 x 7 (1 mark). The number formed by the last two digits is 84, which is divisible by 4 (84 = 4 x 21), so 84 is divisible by 4 (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Data handling and presentation", "q": "The favourite fruits of 20 students are (M = Mango, A = Apple, B = Banana, G = Grapes):\\nM, A, B, M, G, M, B, A, M, G, B, M, A, M, B, G, M, B, A, G\\n(a) Make a frequency table using tally marks.\\n(b) Which fruit is liked the most?\\n(c) How many more students like Mango than Apple?\\n(d) In a pictograph where one symbol = 2 students, how many symbols will represent Banana?", "marks": 5, "answer": "(a) Mango: tally 5 + 2, frequency 7; Apple: 4; Banana: 5; Grapes: 4; total 20 (2 marks). (b) Mango (1 mark). (c) 7 - 4 = 3 more students (1 mark). (d) 5 / 2 = 2 and a half symbols, i.e. 2 full symbols and a half symbol (1 mark)."}, {"n": 10, "type": "Thinking (HOTS)", "topic": "The other side of zero (integers)", "q": "At noon the temperature at a hill station was 5 degrees C. By midnight it dropped by 8 degrees C. By the next morning it rose by 4 degrees C.\\n(i) What was the temperature at midnight?\\n(ii) What was the temperature next morning?\\n(iii) What is the difference between the noon and midnight temperatures?\\n(iv) Arrange in increasing order: -3, 1, 5, -7", "marks": 4, "answer": "(i) 5 - 8 = -3 degrees C. (ii) -3 + 4 = 1 degree C. (iii) 5 - (-3) = 8 degrees C. (iv) -7, -3, 1, 5. (1 mark each)"}]}, "Science": {"book": "Curiosity", "questions": [{"n": 1, "type": "MCQ", "topic": "Exploring magnets", "q": "Which of the following is attracted by a magnet?\\n(a) plastic scale (b) iron nail (c) wooden pencil (d) glass bangle", "marks": 1, "answer": "(b) iron nail"}, {"n": 2, "type": "Fill in the blank", "topic": "Measurement of length and motion", "q": "The SI unit of length is the ______.", "marks": 1, "answer": "metre (m)"}, {"n": 3, "type": "True/False", "topic": "Temperature and its measurement", "q": "State True or False: Pure water boils at 100 degrees Celsius at sea level.", "marks": 1, "answer": "True"}, {"n": 4, "type": "Assertion-Reason", "topic": "Mindful eating: a path to a healthy body", "q": "Assertion (A): We should not eat only one type of food every day.\\nReason (R): A balanced diet contains all the nutrients in the right amounts.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Methods of separation in everyday life", "q": "Which method is used by farmers to separate husk from grains with the help of wind?\\n(a) sieving (b) filtration (c) winnowing (d) evaporation", "marks": 1, "answer": "(c) winnowing"}, {"n": 6, "type": "Short answer", "topic": "Living creatures: exploring their characteristics", "q": "State any four characteristics that are common to all living beings.", "marks": 2, "answer": "Any four (1/2 mark each): they need food/nutrition; they grow; they breathe (respiration); they respond to stimuli; they reproduce; they excrete waste; they move; they have a definite life span."}, {"n": 7, "type": "Short answer", "topic": "Temperature and its measurement", "q": "What is the normal human body temperature? Why should a clinical thermometer not be used to measure the temperature of boiling water?", "marks": 2, "answer": "Normal body temperature is about 37 degrees C (98.6 degrees F) (1 mark). A clinical thermometer reads only from about 35 to 42 degrees C; boiling water (100 degrees C) is far above this range, so the thermometer may break (1 mark)."}, {"n": 8, "type": "Short answer", "topic": "A journey through states of water", "q": "Differentiate between evaporation and condensation. Give one example of each.", "marks": 2, "answer": "Evaporation: change of liquid water into water vapour at any temperature; e.g. wet clothes drying in the sun (1 mark). Condensation: change of water vapour into liquid water on cooling; e.g. water droplets on the outside of a glass of cold water (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Methods of separation in everyday life", "q": "Explain any five methods of separating substances used in daily life, giving one example of each.", "marks": 5, "answer": "1 mark each for any five: Handpicking - removing stones from rice/pulses by hand; Sieving - separating flour from bran using a sieve; Winnowing - separating husk from grain using wind; Threshing - separating grains from stalks by beating; Sedimentation and decantation - letting mud settle in water and pouring off clear water; Filtration - separating tea leaves from tea using a strainer; Evaporation - obtaining salt from sea water; Magnetic separation - separating iron filings from sand using a magnet."}, {"n": 10, "type": "Case-based", "topic": "Exploring magnets", "q": "Riya tied a thread to the middle of a bar magnet and hung it from a stand, away from iron objects. Each time she turned it, the magnet came to rest pointing in the same direction. Then she brought the north pole of another magnet near its north pole.\\n(i) In which direction does the freely suspended magnet come to rest?\\n(ii) Name a device that works on this property.\\n(iii) What happens when the two north poles are brought near each other?\\n(iv) How can you find out whether an iron bar is a magnet or not?", "marks": 4, "answer": "(i) North-south direction. (ii) Magnetic compass. (iii) They repel (push) each other. (iv) Bring each end of the bar near a pole of a known magnet; if repulsion occurs at any end, the bar is a magnet (repulsion is the sure test; attraction alone is not). (1 mark each)"}]}, "Social Science": {"book": "Exploring Society: India and Beyond", "questions": [{"n": 1, "type": "MCQ", "topic": "Locating places on the Earth", "q": "The 0 degree line of latitude is called the:\\n(a) Prime Meridian (b) Tropic of Cancer (c) Equator (d) Arctic Circle", "marks": 1, "answer": "(c) Equator"}, {"n": 2, "type": "Fill in the blank", "topic": "Oceans and continents", "q": "The largest ocean on the Earth is the ______ Ocean.", "marks": 1, "answer": "Pacific"}, {"n": 3, "type": "True/False", "topic": "Grassroots democracy: local government in rural areas", "q": "State True or False: The Gram Sabha consists of all adults (18 years and above) of a village whose names are in the voters' list.", "marks": 1, "answer": "True"}, {"n": 4, "type": "Match the following", "topic": "Economic activities around us", "q": "Match the activity with its sector:\\n(i) Farming  (ii) Banking\\n(a) Tertiary sector  (b) Primary sector", "marks": 1, "answer": "(i)-(b) Farming - Primary sector; (ii)-(a) Banking - Tertiary sector (1/2 mark each)"}, {"n": 5, "type": "Assertion-Reason", "topic": "Timeline and sources of history", "q": "Assertion (A): Historians study inscriptions, coins and old buildings.\\nReason (R): These sources give us information about the past.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Maps and globes", "q": "Give two differences between a map and a globe.", "marks": 2, "answer": "Any two (1 mark each): A globe is a three-dimensional model of the Earth, a map is a flat (two-dimensional) drawing; a globe shows the whole Earth, a map can show the whole Earth or a small part; a globe is difficult to carry, a map is easy to fold and carry; a map can show more details of small areas."}, {"n": 7, "type": "Short answer", "topic": "Grassroots democracy: Panchayati Raj", "q": "Name the three levels (tiers) of the Panchayati Raj system.", "marks": 2, "answer": "Gram Panchayat at the village level, Panchayat Samiti at the block level, and Zila Parishad at the district level. (All three correct = 2 marks; two correct = 1 mark)"}, {"n": 8, "type": "Short answer", "topic": "The beginnings of Indian civilisation", "q": "Mention any two features of town planning of the Harappan (Indus-Sarasvati) cities.", "marks": 2, "answer": "Any two (1 mark each): well-planned streets crossing at right angles; covered drainage system; houses made of baked bricks of standard size; separate raised area (citadel) and lower town; large public structures such as the Great Bath at Mohenjo-daro; wells and water reservoirs (e.g. Dholavira)."}, {"n": 9, "type": "Long answer", "topic": "Unity in diversity", "q": "'India is a land of unity in diversity.' Explain this statement with suitable examples.", "marks": 5, "answer": "Marking points: Diversity in languages and scripts, e.g. many languages spoken across states (1); diversity in food, clothing and festivals, e.g. Pongal, Bihu, Onam, Lohri as harvest festivals (1); diversity in religions, customs, art and music (1); unifying threads - common cultural values, shared epics and stories, similar festivals celebrated in different forms, respect for all (1); the Constitution, national symbols and common citizenship bind us together; conclusion that diversity is our strength (1)."}, {"n": 10, "type": "Case-based", "topic": "Landforms and life", "q": "Read and answer:\\nPlains are large, flat stretches of land. Many plains are formed by rivers, which bring fertile soil (silt) and deposit it on their banks. Because the land is flat and fertile, farming is easy. Building roads, railways and houses is also easier. That is why plains are often densely populated. The Indo-Gangetic plain in India is one example.\\n(i) How are many plains formed?\\n(ii) Why are plains good for farming?\\n(iii) Give one reason why plains are densely populated.\\n(iv) Name the plain mentioned in the passage.", "marks": 4, "answer": "(i) By rivers depositing fertile soil (silt) on their banks. (ii) The land is flat and the soil is fertile. (iii) Farming is easy / roads, railways and houses are easy to build. (iv) The Indo-Gangetic plain. (1 mark each)"}]}, "Sanskrit": {"book": "Deepakam", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्दरूपाणि (अकारान्त-पुंलिङ्गः)", "q": "'बालक' शब्दस्य प्रथमाविभक्तेः बहुवचनरूपं चिनुत।\\n(a) बालकः (b) बालकौ (c) बालकाः (d) बालकम्", "marks": 1, "answer": "(c) बालकाः"}, {"n": 2, "type": "Fill in the blank", "topic": "धातुरूपाणि (लट्लकारः)", "q": "उचितपदेन रिक्तस्थानं पूरयत (पठति / पठन्ति):\\nसः पुस्तकं ______ ।", "marks": 1, "answer": "पठति (सः एकवचनम्, अतः क्रियापदम् अपि एकवचने)"}, {"n": 3, "type": "True/False", "topic": "शब्दरूपाणि (आकारान्त-स्त्रीलिङ्गः)", "q": "'सत्यम्' अथवा 'असत्यम्' इति लिखत:\\n'लता' शब्दः आकारान्त-स्त्रीलिङ्गशब्दः अस्ति।", "marks": 1, "answer": "सत्यम्"}, {"n": 4, "type": "Match the following", "topic": "सर्वनामपदानि", "q": "मेलनं कुरुत:\\n(i) सः  (ii) सा\\n(a) स्त्रीलिङ्गम्  (b) पुंलिङ्गम्", "marks": 1, "answer": "(i)-(b) सः - पुंलिङ्गम्; (ii)-(a) सा - स्त्रीलिङ्गम् (प्रत्येकस्य 1/2 अङ्कः)"}, {"n": 5, "type": "MCQ", "topic": "संख्यावाचकशब्दाः", "q": "'पञ्च' इति संख्यायाः अङ्कः कः?\\n(a) ३ (b) ४ (c) ५ (d) ६", "marks": 1, "answer": "(c) ५"}, {"n": 6, "type": "Short answer", "topic": "धातुरूपाणि (लट्लकारः)", "q": "'पठ्' धातोः लट्लकारे प्रथमपुरुषस्य त्रीणि रूपाणि, 'खाद्' धातोः उत्तमपुरुष-एकवचनरूपं च लिखत।", "marks": 2, "answer": "पठति, पठतः, पठन्ति (1.5 अङ्काः); खादामि (0.5 अङ्कः)।"}, {"n": 7, "type": "Short answer", "topic": "अनुवादः", "q": "संस्कृतभाषायाम् अनुवादं कुरुत:\\n(i) राम पढ़ता है।\\n(ii) बालिकाएँ खेलती हैं।", "marks": 2, "answer": "(i) रामः पठति। (ii) बालिकाः क्रीडन्ति। (प्रत्येकस्य 1 अङ्कः)"}, {"n": 8, "type": "Short answer", "topic": "शब्दरूपाणि (अकारान्त-नपुंसकलिङ्गः)", "q": "'फल' शब्दस्य प्रथमाविभक्तौ त्रीणि रूपाणि, 'लता' शब्दस्य प्रथमा-बहुवचनरूपं च लिखत।", "marks": 2, "answer": "फलम्, फले, फलानि (1.5 अङ्काः); लताः (0.5 अङ्कः)।"}, {"n": 9, "type": "Long answer", "topic": "रचनात्मककार्यम् (वाक्यनिर्माणम्)", "q": "'मम विद्यालयः' इति विषये संस्कृतभाषायां पञ्च वाक्यानि लिखत।", "marks": 5, "answer": "प्रत्येकं शुद्धवाक्यस्य 1 अङ्कः। आदर्श-उत्तरम्: १. मम विद्यालयः सुन्दरः अस्ति। २. विद्यालये एकं विशालं क्रीडाक्षेत्रम् अस्ति। ३. अत्र शिक्षकाः स्नेहेन पाठयन्ति। ४. छात्राः प्रतिदिनं विद्यालयं गच्छन्ति। ५. अहं मम विद्यालयं बहु स्निह्यामि (मह्यं मम विद्यालयः रोचते)।"}, {"n": 10, "type": "Case-based", "topic": "अपठितगद्यांशः", "q": "गद्यांशं पठित्वा प्रश्नान् उत्तरत:\\nइदम् उद्यानम् अस्ति। उद्याने बहवः वृक्षाः सन्ति। वृक्षेषु खगाः कूजन्ति। बालकाः उद्याने क्रीडन्ति। मालाकारः वृक्षान् जलेन सिञ्चति। उद्यानस्य पुष्पाणि सुन्दराणि सन्ति।\\n(i) उद्याने के सन्ति?\\n(ii) खगाः कुत्र कूजन्ति?\\n(iii) कः वृक्षान् सिञ्चति?\\n(iv) 'क्रीडन्ति' इति क्रियापदस्य कर्तृपदं किम्?", "marks": 4, "answer": "(i) वृक्षाः (बहवः वृक्षाः)। (ii) वृक्षेषु। (iii) मालाकारः। (iv) बालकाः। (प्रत्येकस्य 1 अङ्कः)"}]}, "Arts": {"book": "Kriti", "questions": [{"n": 1, "type": "MCQ", "topic": "Visual arts: colours", "q": "Which of the following is a primary colour?\\n(a) green (b) orange (c) red (d) purple", "marks": 1, "answer": "(c) red (the primary colours are red, yellow and blue)"}, {"n": 2, "type": "Fill in the blank", "topic": "Visual arts: colour mixing", "q": "Mixing blue and yellow gives the colour ______.", "marks": 1, "answer": "green"}, {"n": 3, "type": "True/False", "topic": "Dance: Indian classical dance forms", "q": "State True or False: Kathak is a classical dance form associated with North India.", "marks": 1, "answer": "True"}, {"n": 4, "type": "Match the following", "topic": "Music: musical instruments", "q": "Match the instrument with its type:\\n(i) Tabla  (ii) Sitar\\n(a) String instrument  (b) Percussion instrument", "marks": 1, "answer": "(i)-(b) Tabla - percussion; (ii)-(a) Sitar - string (1/2 mark each)"}, {"n": 5, "type": "MCQ", "topic": "Music: swaras", "q": "The seven basic musical notes (Sa, Re, Ga, Ma, Pa, Dha, Ni) are called:\\n(a) taal (b) swar (c) laya (d) mudra", "marks": 1, "answer": "(b) swar (swaras)"}, {"n": 6, "type": "Short answer", "topic": "Visual arts: colours", "q": "What are warm colours and cool colours? Give two examples of each.", "marks": 2, "answer": "Warm colours give a feeling of heat and energy, e.g. red, orange, yellow (1 mark). Cool colours give a calm, soothing feeling, e.g. blue, green, violet (1 mark)."}, {"n": 7, "type": "Short answer", "topic": "Visual arts: folk art of India", "q": "Name any two folk painting styles of India and the states they belong to.", "marks": 2, "answer": "Any two (1 mark each): Madhubani - Bihar; Warli - Maharashtra; Pattachitra - Odisha/West Bengal; Gond - Madhya Pradesh; Kalamkari - Andhra Pradesh/Telangana; Phad - Rajasthan."}, {"n": 8, "type": "Short answer", "topic": "Theatre: mime and expression", "q": "What is mime in theatre? Give one example of an action that can be shown through mime.", "marks": 2, "answer": "Mime is acting without words, using only facial expressions, gestures and body movements to tell a story or show an action (1 mark). Example: pretending to open a door, drink water, or fly a kite (1 mark)."}, {"n": 9, "type": "Long answer", "topic": "Visual arts: poster making", "q": "Describe the steps you would follow to make a poster on 'Save Water'. Mention how you would use lines, shapes, colours and a slogan.", "marks": 5, "answer": "Marking points (1 each): Planning - decide the message and draw a rough sketch; Layout - large central image (e.g. a tap with a drop, the Earth), balanced placement of picture and text; Lines and shapes - bold outlines, simple shapes like drops and circles to catch attention; Colours - mostly blue/green for water and nature, contrasting colour for the slogan; Slogan and finishing - short, catchy slogan in large clear letters (e.g. 'Every Drop Counts'), neat colouring and borders."}, {"n": 10, "type": "Activity", "topic": "Music: sargam, aaroh and avroh", "q": "(i) Write the full names of the seven swaras Sa, Re, Ga, Ma, Pa, Dha, Ni.\\n(ii) Write the aaroh (ascending order) of the swaras.\\n(iii) Write the avroh (descending order) of the swaras.", "marks": 4, "answer": "(i) Shadja, Rishabh, Gandhar, Madhyam, Pancham, Dhaivat, Nishad (2 marks). (ii) Aaroh: Sa Re Ga Ma Pa Dha Ni Sa' (upper Sa) (1 mark). (iii) Avroh: Sa' Ni Dha Pa Ma Ga Re Sa (1 mark)."}]}, "Physical Education": {"book": "Khel Yatra", "questions": [{"n": 1, "type": "MCQ", "topic": "Traditional games: Kabaddi", "q": "How many players of a Kabaddi team are on the court at a time?\\n(a) 5 (b) 7 (c) 9 (d) 11", "marks": 1, "answer": "(b) 7"}, {"n": 2, "type": "Fill in the blank", "topic": "Warm-up and cool-down", "q": "Before starting any game or exercise, we should always do a ______ to prepare the body.", "marks": 1, "answer": "warm-up"}, {"n": 3, "type": "True/False", "topic": "Health and hydration", "q": "State True or False: We should drink water before, during and after physical activity.", "marks": 1, "answer": "True. It replaces water lost as sweat and prevents dehydration."}, {"n": 4, "type": "Assertion-Reason", "topic": "Yoga", "q": "Assertion (A): Regular practice of yoga improves flexibility.\\nReason (R): Yoga asanas involve gentle stretching of muscles and joints.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Yoga: asanas", "q": "Which of these asanas is performed in a standing position?\\n(a) Tadasana (b) Bhujangasana (c) Shavasana (d) Padmasana", "marks": 1, "answer": "(a) Tadasana"}, {"n": 6, "type": "Short answer", "topic": "Traditional and indigenous games", "q": "Name any two traditional Indian games and write two benefits of playing them.", "marks": 2, "answer": "Games (any two, 1 mark): Kho-Kho, Kabaddi, Gilli-Danda, Pithu (Lagori), Langdi, Mallakhamb. Benefits (any two, 1 mark): improve fitness, speed and agility; teamwork and cooperation; need little or no equipment; keep our cultural heritage alive."}, {"n": 7, "type": "Short answer", "topic": "Components of physical fitness", "q": "Name any four components of physical fitness.", "marks": 2, "answer": "Any four (1/2 mark each): strength, speed, endurance (stamina), flexibility, agility, coordination, balance."}, {"n": 8, "type": "Short answer", "topic": "Safety and first aid", "q": "A classmate twists her ankle while playing. What does RICE stand for in first aid for a sprain?", "marks": 2, "answer": "R - Rest, I - Ice, C - Compression, E - Elevation (1/2 mark each)."}, {"n": 9, "type": "Long answer", "topic": "Warm-up and cool-down", "q": "Explain the importance of warming up before and cooling down after physical activity. Give two examples of exercises for each.", "marks": 5, "answer": "Warm-up importance (any two, 2 marks): raises body temperature and heart rate gradually; makes muscles flexible; prevents injuries; prepares the mind. Warm-up examples (1 mark): spot jogging, arm circles, jumping jacks, light running. Cool-down importance (1 mark): brings heart rate and breathing back to normal slowly, reduces stiffness and soreness. Cool-down examples (1 mark): slow walking, light stretching, deep breathing."}, {"n": 10, "type": "Case-based", "topic": "Healthy lifestyle and fitness", "q": "Rohan spends about 5 hours a day watching videos on his phone. He often eats chips and drinks soft drinks, sleeps late and rarely plays outside. He feels tired in class and gets breathless while climbing stairs.\\n(i) Identify two unhealthy habits of Rohan.\\n(ii) Suggest one change in his diet.\\n(iii) Suggest one physical activity he can do daily.\\n(iv) How many hours of sleep should a child of his age get?", "marks": 4, "answer": "(i) Any two: too much screen time, eating junk food, sleeping late, lack of outdoor play. (ii) Eat fruits, vegetables, whole grains and drink water/milk instead of chips and soft drinks. (iii) Any one: at least 60 minutes of outdoor play, cycling, skipping, running, yoga. (iv) About 9 to 11 hours. (1 mark each)"}]}, "Vocational Education": {"book": "Kaushal Bodh", "questions": [{"n": 1, "type": "MCQ", "topic": "Work with life forms: gardening tools", "q": "Which tool is commonly used to loosen soil and remove weeds in a small garden?\\n(a) hammer (b) khurpi (hand trowel) (c) screwdriver (d) saw", "marks": 1, "answer": "(b) khurpi (hand trowel)"}, {"n": 2, "type": "Fill in the blank", "topic": "Work with life forms: composting", "q": "Kitchen waste such as vegetable peels can be converted into ______ to be used as manure.", "marks": 1, "answer": "compost"}, {"n": 3, "type": "True/False", "topic": "Work with machines and materials: hand tools", "q": "State True or False: A screwdriver is used to tighten or loosen screws.", "marks": 1, "answer": "True"}, {"n": 4, "type": "Match the following", "topic": "Work with machines and materials: simple machines", "q": "Match the object with the simple machine:\\n(i) See-saw  (ii) Ramp\\n(a) Inclined plane  (b) Lever", "marks": 1, "answer": "(i)-(b) See-saw - lever; (ii)-(a) Ramp - inclined plane (1/2 mark each)"}, {"n": 5, "type": "Assertion-Reason", "topic": "Safety at work", "q": "Assertion (A): We should wear gloves while handling compost and sharp tools.\\nReason (R): Gloves protect our hands from germs and injuries.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Work with life forms: kitchen garden", "q": "Suggest two ways to save water while maintaining a school garden.", "marks": 2, "answer": "Any two (1 mark each): water plants in the early morning or evening to reduce evaporation; use drip irrigation or a watering can instead of a running hose; cover soil with dry leaves (mulching); reuse water from washing vegetables or RO waste water; harvest rainwater."}, {"n": 7, "type": "Short answer", "topic": "Work with life forms: vermicomposting", "q": "What is vermicomposting? Write two advantages of it.", "marks": 2, "answer": "Vermicomposting is making compost from organic/kitchen waste with the help of earthworms (1 mark). Advantages (any two, 1/2 mark each): reduces garbage; gives rich natural manure; improves soil fertility; reduces the need for chemical fertilisers."}, {"n": 8, "type": "Short answer", "topic": "Work in human services: kitchen safety and hygiene", "q": "Write any two safety or hygiene rules to follow while helping in the kitchen.", "marks": 2, "answer": "Any two (1 mark each): wash hands before handling food; handle knives carefully and keep them away from the edge; turn off the gas after use and keep flammable things away from the flame; use a cloth or holder for hot utensils; keep the kitchen and surfaces clean; wear an apron and tie back long hair."}, {"n": 9, "type": "Long answer", "topic": "Work with life forms: growing plants", "q": "Describe the steps you would follow to grow a vegetable plant (such as tomato or coriander) in a pot at home or school.", "marks": 5, "answer": "1 mark each: Select a pot with drainage holes and place it where it gets sunlight; Prepare soil by mixing garden soil, sand and compost/manure; Sow seeds at proper depth and spacing and cover lightly with soil; Water regularly but do not overwater, and remove weeds; Care and observe - give support to growing plants, check for pests, add compost, record growth, harvest when ready."}, {"n": 10, "type": "Case-based", "topic": "Project work: making and selling products", "q": "Class 6 students made 20 paper bags from old newspapers to reduce plastic use. The material and glue cost Rs 5 per bag. They sold all bags at the school fair for Rs 8 each.\\n(i) What was the total cost?\\n(ii) What was the total amount from sales?\\n(iii) How much profit did they make?\\n(iv) Give one reason why paper bags are better than plastic bags.", "marks": 4, "answer": "(i) 20 x 5 = Rs 100. (ii) 20 x 8 = Rs 160. (iii) 160 - 100 = Rs 60 profit. (iv) Paper bags are biodegradable / do not pollute land and water / reuse old newspapers. (1 mark each)"}]}}, "7": {"English": {"book": "Poorvi", "questions": [{"n": 1, "type": "MCQ", "topic": "Grammar: Subject-verb agreement", "q": "Choose the correct verb to complete the sentence: 'She ______ to school by bus every day.'\\n(a) go (b) goes (c) going (d) gone", "marks": 1, "answer": "(b) goes"}, {"n": 2, "type": "Fill in the blank", "topic": "Grammar: Prepositions", "q": "Fill in the blank with a suitable preposition: 'The frightened kitten was hiding ______ the table.'", "marks": 1, "answer": "under (beneath is also acceptable)"}, {"n": 3, "type": "True/False", "topic": "Grammar: Parts of speech (adverbs)", "q": "State True or False: In the sentence 'The athlete ran quickly', the word 'quickly' is an adverb.", "marks": 1, "answer": "True. 'Quickly' tells us how the athlete ran, so it modifies the verb and is an adverb."}, {"n": 4, "type": "Match the following", "topic": "Vocabulary: Antonyms", "q": "Match each word with its antonym:\\n(i) ancient (ii) brave (iii) generous (iv) arrive\\n(a) cowardly (b) depart (c) modern (d) mean", "marks": 1, "answer": "(i)-(c) modern, (ii)-(a) cowardly, (iii)-(d) mean, (iv)-(b) depart"}, {"n": 5, "type": "Assertion-Reason", "topic": "Grammar: Nouns", "q": "Assertion (A): 'Delhi' is a proper noun.\\nReason (R): A proper noun names a particular person, place or thing.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Grammar: Active and passive voice", "q": "Change the following sentences into passive voice:\\n(a) The children planted trees.\\n(b) Riya writes a letter.", "marks": 2, "answer": "(a) Trees were planted by the children. (1 mark)\\n(b) A letter is written by Riya. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Grammar: Direct and indirect speech", "q": "Change the following into indirect (reported) speech:\\n(a) Mother said, \"I am tired.\"\\n(b) The teacher said to us, \"Sit down quietly.\"", "marks": 2, "answer": "(a) Mother said that she was tired. (1 mark)\\n(b) The teacher told (ordered) us to sit down quietly. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Vocabulary: Word meanings and usage", "q": "Give the meaning of each word and use it in a sentence of your own: (a) curious (b) determined", "marks": 2, "answer": "(a) curious - eager to know or learn something. Example: The curious child asked many questions about the stars. (1 mark)\\n(b) determined - having made a firm decision; not giving up. Example: She was determined to finish the race despite the rain. (1 mark)\\n(Accept any correct meaning and meaningful sentence.)"}, {"n": 9, "type": "Long answer", "topic": "Writing: Paragraph / descriptive writing", "q": "Write a paragraph of 120-150 words on the topic 'A Day Without Mobile Phones'. Describe how the day might be spent, what could be difficult and what could be enjoyable about it.", "marks": 5, "answer": "Marking points:\\n1. Suitable title and clear introduction to the idea (1 mark)\\n2. Content: how the day is spent without phones, e.g., playing outdoors, reading, talking with family, hobbies (1 mark)\\n3. Difficulties mentioned, e.g., contacting friends, checking information, habit of scrolling (1 mark)\\n4. Enjoyable aspects and a thoughtful conclusion, e.g., more time together, better sleep, less screen time (1 mark)\\n5. Language: correct grammar, spelling, varied vocabulary, within word limit and well organised (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Reading comprehension: Unseen passage", "q": "Read the passage and answer the questions.\\nMeera lived in a small village near a river. Every summer the river shrank, and the villagers had to walk miles for water. Meera noticed that during the monsoon, rainwater quickly flowed away. With her teacher's help, she convinced the villagers to dig small ponds and build check dams. At first, many people laughed at the idea, but Meera and her friends kept working. The next summer the ponds were still full and the wells had water. The village head proudly called her 'the water girl'.\\n(a) What problem did the village face every summer?\\n(b) What did Meera notice during the monsoon?\\n(c) Name the two things the villagers built.\\n(d) Find a word in the passage that means 'persuaded'.", "marks": 4, "answer": "(a) The river shrank and villagers had to walk miles for water. (1)\\n(b) She noticed that rainwater quickly flowed away. (1)\\n(c) Small ponds and check dams. (1)\\n(d) convinced (1)"}]}, "Hindi": {"book": "मल्हार", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्द-भंडार: पर्यायवाची शब्द", "q": "'सूर्य' का पर्यायवाची शब्द कौन-सा है?\\n(क) चंद्र (ख) दिनकर (ग) नीरज (घ) सागर", "marks": 1, "answer": "(ख) दिनकर"}, {"n": 2, "type": "Fill in the blank", "topic": "शब्द-भंडार: विलोम शब्द", "q": "रिक्त स्थान भरिए: 'दिन' का विलोम शब्द ______ है।", "marks": 1, "answer": "रात"}, {"n": 3, "type": "True/False", "topic": "व्याकरण: विशेषण", "q": "सही या गलत बताइए: 'मीठा आम' में 'मीठा' शब्द विशेषण है।", "marks": 1, "answer": "सही। 'मीठा' शब्द संज्ञा 'आम' की विशेषता बताता है, इसलिए यह विशेषण है।"}, {"n": 4, "type": "Match the following", "topic": "मुहावरे", "q": "मुहावरों का उनके अर्थ से मिलान कीजिए:\\n(i) आँख का तारा (ii) नौ-दो ग्यारह होना (iii) हाथ बँटाना (iv) ईद का चाँद होना\\n(क) भाग जाना (ख) सहायता करना (ग) बहुत प्यारा (घ) बहुत दिनों बाद दिखाई देना", "marks": 1, "answer": "(i)-(ग) बहुत प्यारा, (ii)-(क) भाग जाना, (iii)-(ख) सहायता करना, (iv)-(घ) बहुत दिनों बाद दिखाई देना"}, {"n": 5, "type": "Assertion-Reason", "topic": "व्याकरण: वचन", "q": "अभिकथन (A): 'पुस्तकें' शब्द बहुवचन है।\\nकारण (R): संज्ञा के जिस रूप से एक से अधिक वस्तुओं का बोध हो, उसे बहुवचन कहते हैं।\\n(क) A और R दोनों सही हैं तथा R, A की सही व्याख्या है। (ख) A और R दोनों सही हैं, पर R, A की सही व्याख्या नहीं है। (ग) A सही है, पर R गलत है। (घ) A गलत है, पर R सही है।", "marks": 1, "answer": "(क) A और R दोनों सही हैं तथा R, A की सही व्याख्या है।"}, {"n": 6, "type": "Short answer", "topic": "व्याकरण: वाक्य शुद्धि", "q": "निम्नलिखित वाक्यों को शुद्ध करके लिखिए:\\n(क) मेरे को घर जाना है।\\n(ख) वह रोटी खाया।", "marks": 2, "answer": "(क) मुझे घर जाना है। (1 अंक)\\n(ख) उसने रोटी खाई। (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "व्याकरण: उपसर्ग और प्रत्यय", "q": "(क) 'अ' उपसर्ग लगाकर दो नए शब्द बनाइए।\\n(ख) 'ता' प्रत्यय लगाकर दो नए शब्द बनाइए।", "marks": 2, "answer": "(क) अ + ज्ञान = अज्ञान, अ + मर = अमर (अन्य सही उदाहरण: अधर्म, अशुद्ध) (1 अंक)\\n(ख) सुंदर + ता = सुंदरता, मित्र + ता = मित्रता (अन्य सही उदाहरण: मानवता, सरलता) (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "व्याकरण: काल", "q": "निम्नलिखित वाक्यों में काल पहचानकर लिखिए:\\n(क) राम कल दिल्ली जाएगा।\\n(ख) सीता ने मधुर गीत गाया।", "marks": 2, "answer": "(क) भविष्यत् काल - 'जाएगा' क्रिया आने वाले समय को बताती है। (1 अंक)\\n(ख) भूतकाल - 'गाया' क्रिया बीते हुए समय को बताती है। (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "लेखन: औपचारिक पत्र (प्रार्थना-पत्र)", "q": "अपने विद्यालय के प्रधानाचार्य को बीमारी के कारण तीन दिन का अवकाश माँगते हुए एक प्रार्थना-पत्र लिखिए।", "marks": 5, "answer": "अंक-विभाजन:\\n1. प्रारूप: 'सेवा में', प्रधानाचार्य, विद्यालय का नाम-पता, दिनांक (1 अंक)\\n2. विषय: तीन दिन के अवकाश हेतु प्रार्थना-पत्र (1 अंक)\\n3. संबोधन 'महोदय/महोदया' तथा विषय-वस्तु: बीमारी (जैसे बुखार) का उल्लेख, डॉक्टर की सलाह, अवकाश की तिथियाँ (2 अंक)\\n4. समापन: 'धन्यवाद', 'आपका आज्ञाकारी शिष्य/आपकी आज्ञाकारी शिष्या', नाम, कक्षा, अनुक्रमांक (1 अंक)"}, {"n": 10, "type": "Case-based", "topic": "अपठित गद्यांश", "q": "गद्यांश पढ़कर प्रश्नों के उत्तर दीजिए:\\nपेड़ हमारे सच्चे मित्र हैं। वे हमें फल, छाया, लकड़ी और शुद्ध वायु देते हैं। पेड़ वर्षा लाने में सहायता करते हैं और मिट्टी को बहने से रोकते हैं। अनेक पक्षी पेड़ों पर घोंसले बनाते हैं। आज मनुष्य अपने स्वार्थ के लिए पेड़ों को काट रहा है, जिससे प्रदूषण बढ़ रहा है। हमें हर वर्ष कम से कम एक पेड़ अवश्य लगाना चाहिए और उसकी देखभाल करनी चाहिए।\\n(क) पेड़ हमें क्या-क्या देते हैं? (कोई दो)\\n(ख) पेड़ मिट्टी की रक्षा कैसे करते हैं?\\n(ग) पेड़ काटने से क्या हानि हो रही है?\\n(घ) 'मित्र' शब्द का विलोम शब्द लिखिए।", "marks": 4, "answer": "(क) फल, छाया, लकड़ी, शुद्ध वायु (कोई दो) (1 अंक)\\n(ख) पेड़ मिट्टी को बहने से रोकते हैं। (1 अंक)\\n(ग) पेड़ काटने से प्रदूषण बढ़ रहा है। (1 अंक)\\n(घ) शत्रु (1 अंक)"}]}, "Maths": {"book": "Ganita Prakash (Parts 1 & 2)", "questions": [{"n": 1, "type": "MCQ", "topic": "Integers", "q": "Find the value of (-8) + 5 - (-3).\\n(a) -6 (b) 0 (c) 6 (d) -16", "marks": 1, "answer": "(b) 0. Working: (-8) + 5 = -3; -3 - (-3) = -3 + 3 = 0."}, {"n": 2, "type": "Fill in the blank", "topic": "Fractions: multiplication", "q": "Fill in the blank (in lowest terms): 3/4 x 2/9 = ______", "marks": 1, "answer": "1/6. Working: (3 x 2)/(4 x 9) = 6/36 = 1/6."}, {"n": 3, "type": "True/False", "topic": "Integers: multiplication", "q": "State True or False: The product of two negative integers is always negative.", "marks": 1, "answer": "False. The product of two negative integers is positive, e.g., (-3) x (-4) = 12."}, {"n": 4, "type": "MCQ", "topic": "Lines and angles", "q": "What is the supplement of an angle of 65 degrees?\\n(a) 25 degrees (b) 115 degrees (c) 125 degrees (d) 295 degrees", "marks": 1, "answer": "(b) 115 degrees, since supplementary angles add up to 180 degrees (180 - 65 = 115)."}, {"n": 5, "type": "Assertion-Reason", "topic": "Decimals: multiplication", "q": "Assertion (A): 0.5 x 0.4 = 0.2\\nReason (R): In a product of decimals, the number of decimal places equals the sum of the decimal places in the numbers multiplied.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A. (5 x 4 = 20; two decimal places give 0.20 = 0.2.)"}, {"n": 6, "type": "Short answer", "topic": "Algebraic expressions", "q": "Simplify 3x + 5y - x + 2y. Then find its value when x = 2 and y = 1.", "marks": 2, "answer": "Simplified: (3x - x) + (5y + 2y) = 2x + 7y (1 mark)\\nValue: 2(2) + 7(1) = 4 + 7 = 11 (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Ratio and proportion", "q": "Divide Rs 720 between Anu and Bina in the ratio 5 : 3.", "marks": 2, "answer": "Total parts = 5 + 3 = 8; one part = 720 / 8 = Rs 90 (1 mark)\\nAnu = 5 x 90 = Rs 450; Bina = 3 x 90 = Rs 270 (Check: 450 + 270 = 720) (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Triangles: angle sum property", "q": "Two angles of a triangle measure 48 degrees and 67 degrees. Find the third angle and state whether the triangle is acute, right or obtuse.", "marks": 2, "answer": "Third angle = 180 - (48 + 67) = 180 - 115 = 65 degrees (1 mark)\\nAll three angles (48, 67, 65) are less than 90 degrees, so it is an acute-angled triangle. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Fractions and integers: word problems", "q": "(a) Riya had Rs 500. She spent 2/5 of it on books and then 1/4 of the remaining money on stationery. How much money was spent on stationery, and how much is left with her?\\n(b) The temperature at 7 a.m. in a hill town was -4 degrees C. It rose by 3 degrees C every hour. What was the temperature at 11 a.m.?", "marks": 5, "answer": "(a) Books = 2/5 x 500 = Rs 200 (1 mark)\\nRemaining = 500 - 200 = Rs 300; stationery = 1/4 x 300 = Rs 75 (1 mark)\\nMoney left = 300 - 75 = Rs 225 (1 mark)\\n(b) From 7 a.m. to 11 a.m. = 4 hours; rise = 4 x 3 = 12 degrees C (1 mark)\\nTemperature at 11 a.m. = -4 + 12 = 8 degrees C (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Algebra: patterns and expressions", "q": "Squares are made in a single row using matchsticks. One square needs 4 sticks; each new square joined to the row needs 3 more sticks.\\n(a) How many sticks are needed for 2 squares and for 3 squares?\\n(b) Write an expression for the number of sticks needed for n squares.\\n(c) How many sticks are needed for 10 squares?\\n(d) How many squares can be made with 61 sticks?", "marks": 4, "answer": "(a) 2 squares: 7 sticks; 3 squares: 10 sticks (1)\\n(b) 3n + 1 (1)\\n(c) 3(10) + 1 = 31 sticks (1)\\n(d) 3n + 1 = 61, so 3n = 60, n = 20 squares (1)"}]}, "Science": {"book": "Curiosity", "questions": [{"n": 1, "type": "MCQ", "topic": "Electricity: conductors and insulators", "q": "Which of the following is a good conductor of electricity?\\n(a) Wood (b) Plastic (c) Copper (d) Rubber", "marks": 1, "answer": "(c) Copper"}, {"n": 2, "type": "Fill in the blank", "topic": "Acids, bases and salts: indicators", "q": "Turmeric paste turns ______ in colour when soap solution (a base) is added to it.", "marks": 1, "answer": "red (reddish-brown)"}, {"n": 3, "type": "True/False", "topic": "Nutrition in plants", "q": "State True or False: Photosynthesis takes place mainly in the leaves of a plant.", "marks": 1, "answer": "True. Leaves contain the most chlorophyll and have stomata for gas exchange."}, {"n": 4, "type": "MCQ", "topic": "Heat and temperature", "q": "The normal temperature of the human body is about:\\n(a) 27 degrees C (b) 37 degrees C (c) 47 degrees C (d) 100 degrees C", "marks": 1, "answer": "(b) 37 degrees C"}, {"n": 5, "type": "Assertion-Reason", "topic": "Heat: conduction", "q": "Assertion (A): A steel spoon kept in a cup of hot tea becomes hot at its outer end.\\nReason (R): Metals are good conductors of heat.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A. Heat travels along the spoon by conduction."}, {"n": 6, "type": "Short answer", "topic": "Acids and bases", "q": "Give two differences between acids and bases.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Acids taste sour; bases taste bitter and feel soapy.\\n2. Acids turn blue litmus red; bases turn red litmus blue.\\n3. Examples: acids - lemon juice, vinegar; bases - soap solution, baking soda solution."}, {"n": 7, "type": "Short answer", "topic": "Respiration in organisms", "q": "Distinguish between aerobic and anaerobic respiration by writing the word equation for each.", "marks": 2, "answer": "Aerobic respiration (uses oxygen): Glucose + Oxygen -> Carbon dioxide + Water + Energy (1 mark)\\nAnaerobic respiration (without oxygen, e.g., in yeast): Glucose -> Alcohol + Carbon dioxide + Energy. (In muscles during heavy exercise: Glucose -> Lactic acid + Energy.) (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Heat: convection / sea breeze", "q": "Why does a cool breeze blow from the sea towards the land during the daytime in coastal areas?", "marks": 2, "answer": "During the day, land heats up faster than sea water, so the air above the land becomes warm, light and rises. (1 mark)\\nCooler air from above the sea moves in to take its place, creating a sea breeze (a convection current). (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Nutrition in plants: photosynthesis", "q": "Explain the process of photosynthesis. Mention the raw materials, the conditions needed, the products formed, the word equation and its importance for living beings.", "marks": 5, "answer": "Marking points:\\n1. Definition: Green plants make their own food (glucose/carbohydrate) using sunlight (1 mark)\\n2. Raw materials: carbon dioxide from air (through stomata) and water from soil (through roots) (1 mark)\\n3. Conditions: sunlight and chlorophyll (green pigment in leaves) (1 mark)\\n4. Word equation: Carbon dioxide + Water -> (sunlight, chlorophyll) -> Glucose + Oxygen; starch is stored (1 mark)\\n5. Importance: provides food for all living beings directly or indirectly and releases oxygen needed for respiration (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Acids, bases and salts: neutralisation", "q": "Aarav was bitten by an ant while playing in the garden and felt a burning pain. His mother rubbed a paste of baking soda on the spot, and the pain reduced.\\n(a) Which acid is injected by an ant bite?\\n(b) Why was baking soda used?\\n(c) Name the reaction that took place.\\n(d) What are the products of such a reaction?", "marks": 4, "answer": "(a) Formic acid (1)\\n(b) Baking soda (sodium hydrogen carbonate) is a base; it cancels the effect of the acid. (1)\\n(c) Neutralisation (1)\\n(d) A salt and water (heat is also released) (1)"}]}, "Social Science": {"book": "Exploring Society: India and Beyond (Parts 1 & 2)", "questions": [{"n": 1, "type": "MCQ", "topic": "Geography: physical features of India", "q": "Which mountain range lies along the northern boundary of India?\\n(a) Western Ghats (b) Aravalli (c) Himalayas (d) Vindhya", "marks": 1, "answer": "(c) Himalayas"}, {"n": 2, "type": "Fill in the blank", "topic": "History: the Mauryan Empire", "q": "The founder of the Mauryan Empire was ______.", "marks": 1, "answer": "Chandragupta Maurya"}, {"n": 3, "type": "True/False", "topic": "Democracy and government", "q": "State True or False: In a democracy, citizens elect their representatives through voting.", "marks": 1, "answer": "True"}, {"n": 4, "type": "Match the following", "topic": "History: early empires and their achievements", "q": "Match the following:\\n(i) Ashoka (ii) Samudragupta (iii) Kalidasa (iv) Aryabhata\\n(a) Astronomer and mathematician (b) Kalinga war (c) Prayaga prashasti (Allahabad pillar inscription) (d) Abhijnanashakuntalam", "marks": 1, "answer": "(i)-(b), (ii)-(c), (iii)-(d), (iv)-(a)"}, {"n": 5, "type": "Assertion-Reason", "topic": "Economics: from barter to money", "q": "Assertion (A): Money replaced the barter system in most exchanges.\\nReason (R): Barter needs a double coincidence of wants, which is difficult to find.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Geography: weather and climate", "q": "Give two differences between weather and climate.", "marks": 2, "answer": "1. Weather is the day-to-day condition of the atmosphere at a place; climate is the average weather of a place over a long period (about 30 years or more). (1 mark)\\n2. Weather can change within hours or days; climate remains fairly stable over long periods. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Democracy: universal adult franchise", "q": "What is meant by universal adult franchise? Why is it important in a democracy?", "marks": 2, "answer": "Meaning: Every citizen aged 18 years or above has the right to vote, regardless of religion, caste, gender, wealth or education. (1 mark)\\nImportance: It ensures equality and allows all citizens to take part in choosing the government. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "History: Ashoka and Dhamma", "q": "Why did Ashoka give up war after the Kalinga war? Mention any one teaching of his Dhamma.", "marks": 2, "answer": "He was deeply saddened by the large-scale killing and suffering caused by the Kalinga war, so he decided to give up war. (1 mark)\\nAny one teaching: respect for elders, kindness to animals and all living beings, respect for all religions, generosity to the poor, non-violence. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Geography: geographical diversity of India", "q": "India is a land of great geographical diversity. Describe any five major physical divisions of India.", "marks": 5, "answer": "Any five, 1 mark each:\\n1. The Himalayas - young, high fold mountains in the north; source of many perennial rivers.\\n2. The Northern Plains - flat, fertile plains formed by Ganga, Indus and Brahmaputra; densely populated and good for farming.\\n3. The Peninsular Plateau - old, hard rocks, rich in minerals; bordered by Western and Eastern Ghats.\\n4. The Thar Desert - dry, sandy region in the west (mainly Rajasthan) with little rainfall.\\n5. The Coastal Plains - narrow Western coastal plain and wider Eastern coastal plain with river deltas.\\n6. The Islands - Andaman and Nicobar Islands in the Bay of Bengal and Lakshadweep in the Arabian Sea."}, {"n": 10, "type": "Case-based", "topic": "Geography: the monsoon", "q": "Read the case and answer.\\nIn most parts of India, farmers wait eagerly for the south-west monsoon, which usually arrives in Kerala in early June and covers the country by July, and it retreats by the end of September. It brings most of India's annual rainfall. Crops like rice are sown with the first rains. When the monsoon is delayed or weak, crops fail; when rainfall is very heavy, rivers overflow.\\n(a) Which months make up the south-west monsoon season?\\n(b) Why is the monsoon important for Indian farmers?\\n(c) Name one crop sown with the monsoon rains.\\n(d) State one problem caused by very heavy rainfall.", "marks": 4, "answer": "(a) June to September (1)\\n(b) It provides most of the water needed for crops; many farmers depend on rain for irrigation. (1)\\n(c) Rice (paddy); also accept cotton, maize, jowar, bajra (kharif crops) (1)\\n(d) Floods / damage to crops, homes and roads / soil erosion (1)"}]}, "Sanskrit": {"book": "दीपकम्", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्दरूपाणि (अकारान्त-पुंलिङ्गम्)", "q": "'बालकः' इति शब्दस्य प्रथमाविभक्तौ बहुवचनरूपं किम्?\\n(क) बालकौ (ख) बालकाः (ग) बालकम् (घ) बालकेन", "marks": 1, "answer": "(ख) बालकाः"}, {"n": 2, "type": "Fill in the blank", "topic": "धातुरूपाणि (लट्लकारः)", "q": "रिक्तस्थानं पूरयत: 'गम्' धातोः लट्लकारे प्रथमपुरुषे एकवचने रूपम् ______ भवति।", "marks": 1, "answer": "गच्छति"}, {"n": 3, "type": "True/False", "topic": "लिङ्गज्ञानम्", "q": "सत्यम् अथवा असत्यम् इति लिखत: 'लता' इति शब्दः स्त्रीलिङ्गः अस्ति।", "marks": 1, "answer": "सत्यम्। 'लता' आकारान्तः स्त्रीलिङ्गशब्दः अस्ति।"}, {"n": 4, "type": "Match the following", "topic": "सङ्ख्याज्ञानम्", "q": "सङ्ख्यापदानि अङ्कैः सह मेलयत:\\n(i) पञ्च (ii) सप्त (iii) दश (iv) त्रयः\\n(क) ७ (ख) ३ (ग) ५ (घ) १०", "marks": 1, "answer": "(i)-(ग) ५, (ii)-(क) ७, (iii)-(घ) १०, (iv)-(ख) ३"}, {"n": 5, "type": "Assertion-Reason", "topic": "पुरुष-वचन-सामञ्जस्यम्", "q": "अभिकथनम् (A): 'अहं पठामि' इति वाक्यं शुद्धम् अस्ति।\\nकारणम् (R): 'अस्मद्' (अहम्) शब्देन सह उत्तमपुरुषस्य क्रियापदं प्रयुज्यते।\\n(क) A R च उभौ सत्यौ, R A इत्यस्य सम्यक् व्याख्या अस्ति। (ख) A R च उभौ सत्यौ, परं R A इत्यस्य सम्यक् व्याख्या नास्ति। (ग) A सत्यम्, R असत्यम्। (घ) A असत्यम्, R सत्यम्।", "marks": 1, "answer": "(क) A R च उभौ सत्यौ, R A इत्यस्य सम्यक् व्याख्या अस्ति।"}, {"n": 6, "type": "Short answer", "topic": "अनुवादः (हिन्दी से संस्कृत)", "q": "संस्कृतभाषायाम् अनुवादं कुरुत:\\n(क) राम पढ़ता है।\\n(ख) हम खेलते हैं।", "marks": 2, "answer": "(क) रामः पठति। (1 अङ्कः)\\n(ख) वयं क्रीडामः। (1 अङ्कः)"}, {"n": 7, "type": "Short answer", "topic": "विभक्तिज्ञानम्", "q": "अधोलिखितपदेषु विभक्तिं वचनं च लिखत:\\n(क) वृक्षात्\\n(ख) रामाय", "marks": 2, "answer": "(क) वृक्षात् - पञ्चमी विभक्तिः, एकवचनम् (1 अङ्कः)\\n(ख) रामाय - चतुर्थी विभक्तिः, एकवचनम् (1 अङ्कः)"}, {"n": 8, "type": "Short answer", "topic": "प्रश्ननिर्माणम्", "q": "कोष्ठके दत्तं पदम् आधृत्य प्रश्ननिर्माणं कुरुत:\\n(क) बालकः उद्याने क्रीडति। (उद्याने)\\n(ख) सीता फलं खादति। (सीता)", "marks": 2, "answer": "(क) बालकः कुत्र क्रीडति? (1 अङ्कः)\\n(ख) का फलं खादति? (1 अङ्कः)"}, {"n": 9, "type": "Long answer", "topic": "रचनात्मकलेखनम् (अनुच्छेदः)", "q": "'मम विद्यालयः' इति विषये संस्कृतभाषायां पञ्च वाक्यानि लिखत।", "marks": 5, "answer": "प्रत्येकं शुद्धवाक्याय 1 अङ्कः। आदर्श-उत्तरम्:\\n1. मम विद्यालयस्य नाम सर्वोदयविद्यालयः अस्ति।\\n2. मम विद्यालयः विशालः सुन्दरः च अस्ति।\\n3. अत्र अनेके शिक्षकाः छात्राः च सन्ति।\\n4. विद्यालये एकः पुस्तकालयः क्रीडाक्षेत्रं च स्तः।\\n5. अहं मम विद्यालयं बहु स्निह्यामि।\\n(अन्यानि शुद्धवाक्यानि अपि स्वीकार्याणि।)"}, {"n": 10, "type": "Case-based", "topic": "अपठितगद्यांशः", "q": "गद्यांशं पठित्वा प्रश्नान् उत्तरत:\\nएकः कृषकः ग्रामे वसति। सः प्रतिदिनं क्षेत्रं गच्छति। तस्य क्षेत्रे बहूनि फलानि भवन्ति। कृषकः परिश्रमी अस्ति। सः फलानि विक्रीय धनं प्राप्नोति। ग्रामजनाः तं सम्मानयन्ति।\\n(क) कृषकः कुत्र वसति?\\n(ख) सः प्रतिदिनं कुत्र गच्छति?\\n(ग) कृषकः कीदृशः अस्ति?\\n(घ) 'वसति' इति क्रियापदस्य कर्तृपदं किम्?", "marks": 4, "answer": "(क) ग्रामे (1)\\n(ख) क्षेत्रम् (1)\\n(ग) परिश्रमी (1)\\n(घ) कृषकः (1)"}]}, "Arts": {"book": "Kriti", "questions": [{"n": 1, "type": "MCQ", "topic": "Visual arts: colour theory", "q": "Which of the following is NOT a primary colour?\\n(a) Red (b) Blue (c) Yellow (d) Green", "marks": 1, "answer": "(d) Green. It is a secondary colour made by mixing blue and yellow."}, {"n": 2, "type": "Fill in the blank", "topic": "Visual arts: colour mixing", "q": "Mixing red and yellow paint gives the colour ______.", "marks": 1, "answer": "orange"}, {"n": 3, "type": "True/False", "topic": "Folk art of India", "q": "State True or False: Madhubani painting is a traditional folk art of Bihar.", "marks": 1, "answer": "True. It comes from the Mithila region of Bihar."}, {"n": 4, "type": "Match the following", "topic": "Dance: classical dance forms", "q": "Match the classical dance with its state of origin:\\n(i) Bharatanatyam (ii) Kathakali (iii) Kuchipudi (iv) Odissi\\n(a) Kerala (b) Odisha (c) Tamil Nadu (d) Andhra Pradesh", "marks": 1, "answer": "(i)-(c) Tamil Nadu, (ii)-(a) Kerala, (iii)-(d) Andhra Pradesh, (iv)-(b) Odisha"}, {"n": 5, "type": "MCQ", "topic": "Music: swaras", "q": "How many basic (shuddha) swaras are there in Indian classical music (Sa Re Ga Ma Pa Dha Ni)?\\n(a) 5 (b) 6 (c) 7 (d) 8", "marks": 1, "answer": "(c) 7"}, {"n": 6, "type": "Short answer", "topic": "Visual arts: warm and cool colours", "q": "What are warm and cool colours? Give two examples of each.", "marks": 2, "answer": "Warm colours give a feeling of heat, energy or excitement, e.g., red, orange, yellow (any two). (1 mark)\\nCool colours give a feeling of calm and coolness, e.g., blue, green, violet (any two). (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Folk and classical art forms", "q": "Write two differences between folk art and classical art.", "marks": 2, "answer": "1. Folk art is created by ordinary people of a community and passed down informally through generations; classical art follows strict rules and texts and is learnt through long formal training (guru-shishya). (1 mark)\\n2. Folk art uses simple, local materials and everyday themes (festivals, nature, village life); classical art is more elaborate and refined, often with religious or mythological themes. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Visual arts: still life drawing", "q": "What is a 'still life' drawing? Give two tips for drawing one well.", "marks": 2, "answer": "A still life is a drawing or painting of non-living objects arranged together, such as fruits, pots, bottles or flowers. (1 mark)\\nTips (any two, 1 mark): observe carefully from one position; start with light basic shapes; show light and shade; keep objects in correct proportion; draw overlapping objects properly."}, {"n": 9, "type": "Long answer", "topic": "Theatre: planning a skit", "q": "Your class has to perform a 5-minute skit on 'Keeping Our Surroundings Clean'. Explain how you would plan it, covering the theme, characters, dialogues, costumes/props and staging.", "marks": 5, "answer": "Marking points (1 mark each):\\n1. Theme/story: a clear storyline, e.g., a littered park cleaned up by children, with a message.\\n2. Characters: names and roles, e.g., children, a shopkeeper, a sanitation worker, a narrator.\\n3. Dialogues: short, clear, loud dialogues; possibly a slogan or song.\\n4. Costumes and props: simple items such as brooms, dustbins, placards, masks made from waste material.\\n5. Staging and teamwork: entry-exit plan, use of space, rehearsals, facing the audience, ending with a strong message."}, {"n": 10, "type": "Activity", "topic": "Folk art: Warli painting", "q": "Activity: Make a Warli-style painting showing a village festival.\\n(a) Which state does Warli art come from?\\n(b) Name the three basic shapes used in Warli art.\\n(c) What colour is traditionally used to paint the figures, and on what background?\\n(d) Name any two themes commonly shown in Warli paintings.", "marks": 4, "answer": "(a) Maharashtra (1)\\n(b) Circle, triangle and square (and lines) (1)\\n(c) White (rice paste) on a mud/red-brown or earthy background (1)\\n(d) Any two: farming, dancing (tarpa dance), festivals, hunting, daily village life, nature (1)"}]}, "Physical Education": {"book": "Khel Yatra", "questions": [{"n": 1, "type": "MCQ", "topic": "Traditional games: Kho-Kho", "q": "How many players of a Kho-Kho team take the field at a time?\\n(a) 7 (b) 9 (c) 11 (d) 12", "marks": 1, "answer": "(b) 9 (8 chasers sitting in the lane and 1 active chaser)"}, {"n": 2, "type": "Fill in the blank", "topic": "Warm-up and cool-down", "q": "Doing warm-up exercises before a game helps to prevent ______.", "marks": 1, "answer": "injuries (such as muscle pulls and sprains)"}, {"n": 3, "type": "True/False", "topic": "Yoga: asanas", "q": "State True or False: Tadasana is performed in a standing position.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Olympic movement", "q": "How many interlinked rings are there on the Olympic flag?\\n(a) 3 (b) 4 (c) 5 (d) 6", "marks": 1, "answer": "(c) 5, representing the five inhabited continents united by sport."}, {"n": 5, "type": "Assertion-Reason", "topic": "Health and hydration", "q": "Assertion (A): We should drink water before, during and after exercise.\\nReason (R): The body loses water through sweat while exercising.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Components of physical fitness", "q": "Name any four components of physical fitness.", "marks": 2, "answer": "Any four (half mark each): strength, speed, endurance (stamina), flexibility, agility, coordination, balance."}, {"n": 7, "type": "Short answer", "topic": "Safety and first aid", "q": "A player sprains her ankle during a match. What does the first-aid method RICE stand for?", "marks": 2, "answer": "R - Rest (stop playing, do not put weight on the ankle)\\nI - Ice (apply an ice pack wrapped in cloth)\\nC - Compression (wrap with a crepe bandage)\\nE - Elevation (raise the ankle above heart level)\\n(Half mark each)"}, {"n": 8, "type": "Short answer", "topic": "Warm-up and cool-down", "q": "Write two differences between warm-up and cool-down.", "marks": 2, "answer": "1. Warm-up is done before physical activity; cool-down is done after it. (1 mark)\\n2. Warm-up gradually raises heart rate and body temperature and prepares muscles; cool-down gradually brings heart rate and breathing back to normal and reduces stiffness (gentle stretching). (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Yoga for health", "q": "Describe any four benefits of practising yoga regularly and name any two yoga asanas suitable for students.", "marks": 5, "answer": "Benefits (any four, 1 mark each = 4 marks): improves flexibility; strengthens muscles; improves posture; improves concentration and memory; reduces stress and brings calmness; improves breathing and blood circulation; builds discipline.\\nAsanas (1 mark for any two): Tadasana, Vrikshasana, Bhujangasana, Padmasana, Vajrasana, Trikonasana, Shavasana."}, {"n": 10, "type": "Case-based", "topic": "Health and safety in sports", "q": "On Sports Day, Rohan ran the 400 m race at noon in hot sun. He had not drunk water since morning. After the race he felt dizzy, tired and very thirsty.\\n(a) What is the likely cause of Rohan's condition?\\n(b) Give one first-aid step for him.\\n(c) Suggest one way to prevent this in future.\\n(d) Rohan's friend helped him even though they were rivals. Which value does this show?", "marks": 4, "answer": "(a) Dehydration / heat exhaustion due to heat and not drinking water (1)\\n(b) Move him to a shady, cool place and give him water or ORS / lemon water in sips; loosen tight clothing (any one) (1)\\n(c) Drink enough water before and during events; wear a cap; avoid running in peak heat (any one) (1)\\n(d) Sportsmanship / helpfulness / empathy (1)"}]}, "Vocational Education": {"book": "Kaushal Bodh", "questions": [{"n": 1, "type": "MCQ", "topic": "Gardening: tools", "q": "Which tool is commonly used to loosen soil and remove weeds in a kitchen garden?\\n(a) Hammer (b) Khurpi (hand hoe) (c) Scissors (d) Spanner", "marks": 1, "answer": "(b) Khurpi (hand hoe)"}, {"n": 2, "type": "Fill in the blank", "topic": "Waste management: composting", "q": "The process of turning kitchen and garden waste into manure is called ______.", "marks": 1, "answer": "composting"}, {"n": 3, "type": "True/False", "topic": "Safety at work", "q": "State True or False: An electrical appliance should be switched off and unplugged before it is cleaned.", "marks": 1, "answer": "True. This prevents electric shock."}, {"n": 4, "type": "Match the following", "topic": "Tools and their uses", "q": "Match the tool with its use:\\n(i) Screwdriver (ii) Pliers (iii) Measuring tape (iv) Watering can\\n(a) Measure length (b) Water plants (c) Tighten or loosen screws (d) Grip and cut wires", "marks": 1, "answer": "(i)-(c), (ii)-(d), (iii)-(a), (iv)-(b)"}, {"n": 5, "type": "Assertion-Reason", "topic": "Agriculture: water conservation", "q": "Assertion (A): Drip irrigation saves water.\\nReason (R): In drip irrigation, water is delivered drop by drop directly to the roots of plants.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Food processing: preservation", "q": "Name any two methods of food preservation and give one example of a food preserved by each method.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Drying / sun-drying - papad, raisins, dried chillies\\n2. Salting / using oil - pickles\\n3. Using sugar - jam, murabba\\n4. Refrigeration / freezing - milk, vegetables\\n5. Boiling / pasteurisation - milk"}, {"n": 7, "type": "Short answer", "topic": "Waste management: compost pit", "q": "Write four steps to prepare compost at home or school.", "marks": 2, "answer": "Half mark each (any four):\\n1. Dig a pit or take a compost bin in a shady place.\\n2. Put a layer of dry leaves or soil at the bottom.\\n3. Add kitchen waste (vegetable peels, fruit waste) and green waste in layers; avoid plastic, metal and glass.\\n4. Cover each layer with soil or dry leaves and sprinkle water to keep it moist.\\n5. Turn the mixture every week or two for air; compost is ready in about 2-3 months (dark, crumbly and earthy-smelling)."}, {"n": 8, "type": "Short answer", "topic": "Financial literacy: budgeting and saving", "q": "Kavya gets Rs 200 as pocket money in a month. She spends Rs 75 on stationery and Rs 60 on snacks. How much does she save? Give one tip to save more.", "marks": 2, "answer": "Total spent = 75 + 60 = Rs 135; savings = 200 - 135 = Rs 65 (1 mark)\\nTip (any one): make a budget and record expenses; reduce spending on snacks; carry a lunch box; keep savings in a piggy bank/bank account (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Work with life forms: kitchen garden", "q": "Your class plans to set up a small kitchen garden in the school. Explain five important steps you would follow, from choosing the site to harvesting.", "marks": 5, "answer": "1 mark each:\\n1. Site selection: an open place getting 5-6 hours of sunlight with a water source nearby.\\n2. Soil preparation: remove stones and weeds, loosen soil and mix compost/organic manure.\\n3. Choice of seeds: seasonal vegetables and herbs, e.g., spinach, coriander, tomato, radish, beans; sow at proper depth and spacing.\\n4. Care: water regularly (preferably morning/evening), remove weeds, use organic pest control such as neem spray.\\n5. Harvesting and record keeping: harvest at the right time, maintain a diary of sowing dates, growth and yield; share produce."}, {"n": 10, "type": "Case-based", "topic": "Entrepreneurship: running a stall", "q": "At the school fair, a group of Class 7 students set up a lemonade stall. They spent Rs 150 on lemons, sugar, cups and water. They sold 40 glasses at Rs 10 each.\\n(a) What was their total income (sales)?\\n(b) What was their profit?\\n(c) Name two skills the students learnt from this activity.\\n(d) Write one hygiene practice they should follow while serving.", "marks": 4, "answer": "(a) 40 x 10 = Rs 400 (1)\\n(b) Profit = 400 - 150 = Rs 250 (1)\\n(c) Any two: teamwork, money handling/accounting, communication, planning, customer service (1)\\n(d) Any one: wash hands, use clean drinking water, cover the lemonade, use clean or disposable cups, wear gloves/cap (1)"}]}}, "8": {"English": {"book": "Poorvi", "questions": [{"n": 1, "type": "MCQ", "topic": "Vocabulary: Synonyms", "q": "Choose the word closest in meaning to 'diligent'.\\n(a) lazy (b) hardworking (c) careless (d) rude", "marks": 1, "answer": "(b) hardworking"}, {"n": 2, "type": "Fill in the blank", "topic": "Grammar: Prepositions of time", "q": "Fill in the blank with a suitable preposition: My uncle has been living in Pune ______ 2019.", "marks": 1, "answer": "since (used with a point of time in the perfect continuous tense)"}, {"n": 3, "type": "True/False", "topic": "Grammar: Reported speech", "q": "State True or False: The sentence 'He said that he was tired.' is in indirect (reported) speech.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Grammar: Active and passive voice", "q": "Choose the correct active voice form of: 'The letter was written by Riya.'\\n(a) Riya writes the letter. (b) Riya has written the letter. (c) Riya wrote the letter. (d) Riya was writing the letter.", "marks": 1, "answer": "(c) Riya wrote the letter."}, {"n": 5, "type": "MCQ", "topic": "Poetic devices: Figures of speech", "q": "Identify the figure of speech in: 'The wind whispered secrets through the trees.'\\n(a) Simile (b) Personification (c) Alliteration (d) Hyperbole", "marks": 1, "answer": "(b) Personification - the wind is given the human quality of whispering."}, {"n": 6, "type": "Short answer", "topic": "Grammar: Direct and indirect speech", "q": "Change into indirect speech:\\n(i) Mother said to me, 'Close the door.'\\n(ii) Arjun said, 'I am reading a novel.'", "marks": 2, "answer": "(i) Mother told (asked) me to close the door. (1)\\n(ii) Arjun said that he was reading a novel. (1)"}, {"n": 7, "type": "Short answer", "topic": "Vocabulary: Idioms", "q": "Give the meaning of each idiom and use it in a sentence of your own:\\n(i) break the ice (ii) a piece of cake", "marks": 2, "answer": "(i) break the ice - to start a conversation and make people feel relaxed. E.g. The teacher told a joke to break the ice on the first day. (1)\\n(ii) a piece of cake - something very easy. E.g. The maths test was a piece of cake for Meena. (1)\\n(Accept any correct sentence showing the meaning.)"}, {"n": 8, "type": "Short answer", "topic": "Grammar: Relative clauses", "q": "Combine each pair of sentences using a suitable relative pronoun (who, which, whose):\\n(i) This is the boy. He won the chess prize.\\n(ii) I lost the pen. My father gave it to me.", "marks": 2, "answer": "(i) This is the boy who won the chess prize. (1)\\n(ii) I lost the pen which (that) my father had given me. (1)"}, {"n": 9, "type": "Long answer", "topic": "Writing: Letter to the editor", "q": "Write a letter to the editor of a local newspaper (120-150 words) expressing concern about the growing use of single-use plastic in your locality and suggesting ways to reduce it. You are Kavya/Karan of 12, Green Park, Jaipur.", "marks": 5, "answer": "Marking points:\\n- Format (1): sender's address, date, receiver (The Editor, name of newspaper, city), subject line, salutation (Sir/Madam), closing (Yours faithfully), name.\\n- Content (3): describe the problem (plastic bags and bottles littering streets, clogging drains, harming cattle, polluting soil and water); suggestions (cloth/jute bags, fines on shopkeepers, awareness drives by schools and RWAs, separate waste collection, recycling); request the paper to publish the letter to spread awareness.\\n- Expression (1): formal tone, accuracy, coherence, within word limit."}, {"n": 10, "type": "Case-based", "topic": "Reading: Unseen passage", "q": "Read the passage and answer the questions.\\nIn a small village in Odisha, twelve-year-old Lipi noticed that children had no books to read after school. She collected old books from neighbours and arranged them on a wooden shelf under the big banyan tree. Every evening, children gathered there to read and share stories. Soon, elders too started coming to learn the alphabet. Within a year, Lipi's 'Tree Library' had over three hundred books, and the village panchayat gave her a small room to keep them safe from the rain.\\n(i) Why did Lipi start the library?\\n(ii) Where were the books first kept?\\n(iii) How did the panchayat help her?\\n(iv) Find a word in the passage that means 'assembled'.", "marks": 4, "answer": "(i) Because the children in her village had no books to read after school. (1)\\n(ii) On a wooden shelf under the big banyan tree. (1)\\n(iii) It gave her a small room to keep the books safe from rain. (1)\\n(iv) gathered (1)"}]}, "Hindi": {"book": "Malhar", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्द-भंडार: पर्यायवाची शब्द", "q": "'जल' का पर्यायवाची शब्द चुनिए।\\n(क) अनल (ख) नीर (ग) पवन (घ) अंबर", "marks": 1, "answer": "(ख) नीर"}, {"n": 2, "type": "Fill in the blank", "topic": "व्याकरण: संधि", "q": "रिक्त स्थान भरिए: 'विद्यालय' शब्द का संधि-विच्छेद है - विद्या + ______।", "marks": 1, "answer": "आलय (विद्या + आलय = विद्यालय, दीर्घ संधि)"}, {"n": 3, "type": "True/False", "topic": "व्याकरण: समास", "q": "सत्य या असत्य लिखिए: 'नीलकंठ' (नीला है कंठ जिसका अर्थात् शिव) में बहुव्रीहि समास है।", "marks": 1, "answer": "सत्य"}, {"n": 4, "type": "MCQ", "topic": "शब्द-भंडार: विलोम शब्द", "q": "'ईमानदार' का विलोम शब्द है -\\n(क) सच्चा (ख) बेईमान (ग) ईमान (घ) वफ़ादार", "marks": 1, "answer": "(ख) बेईमान"}, {"n": 5, "type": "MCQ", "topic": "व्याकरण: मुहावरे", "q": "'आँखों का तारा' मुहावरे का अर्थ है -\\n(क) बहुत प्यारा (ख) बहुत चालाक (ग) अंधा होना (घ) आकाश का तारा", "marks": 1, "answer": "(क) बहुत प्यारा"}, {"n": 6, "type": "Short answer", "topic": "व्याकरण: रचना के आधार पर वाक्य भेद", "q": "रचना के आधार पर वाक्य-भेद पहचानिए:\\n(i) वर्षा हुई और मौसम सुहावना हो गया।\\n(ii) जो परिश्रम करता है, वह सफल होता है।", "marks": 2, "answer": "(i) संयुक्त वाक्य (दो स्वतंत्र उपवाक्य 'और' से जुड़े हैं) (1)\\n(ii) मिश्र वाक्य (प्रधान उपवाक्य 'वह सफल होता है' और आश्रित उपवाक्य 'जो परिश्रम करता है') (1)"}, {"n": 7, "type": "Short answer", "topic": "व्याकरण: उपसर्ग और प्रत्यय", "q": "निम्नलिखित शब्दों में से उपसर्ग/प्रत्यय और मूल शब्द अलग कीजिए:\\n(i) अनुशासन (ii) प्रतिदिन (iii) मिठास (iv) सुंदरता", "marks": 2, "answer": "(i) अनु (उपसर्ग) + शासन (ii) प्रति (उपसर्ग) + दिन (iii) मीठा + आस (प्रत्यय) (iv) सुंदर + ता (प्रत्यय)\\n(प्रत्येक सही उत्तर के लिए 1/2 अंक)"}, {"n": 8, "type": "Short answer", "topic": "व्याकरण: मुहावरों का वाक्य-प्रयोग", "q": "निम्नलिखित मुहावरों का अर्थ लिखकर वाक्य में प्रयोग कीजिए:\\n(i) नौ दो ग्यारह होना (ii) हाथ बँटाना", "marks": 2, "answer": "(i) नौ दो ग्यारह होना - भाग जाना। वाक्य: पुलिस को देखते ही चोर नौ दो ग्यारह हो गया। (1)\\n(ii) हाथ बँटाना - सहायता करना। वाक्य: रीना घर के कामों में माँ का हाथ बँटाती है। (1)\\n(कोई भी उचित वाक्य स्वीकार्य)"}, {"n": 9, "type": "Long answer", "topic": "लेखन: अनुच्छेद लेखन", "q": "'मोबाइल फ़ोन: वरदान या अभिशाप' विषय पर 120-150 शब्दों में एक अनुच्छेद लिखिए।", "marks": 5, "answer": "मूल्यांकन बिंदु:\\n- भूमिका (1): आज मोबाइल फ़ोन जीवन का अभिन्न अंग बन गया है।\\n- लाभ (1.5): दूर बैठे लोगों से बातचीत, ऑनलाइन पढ़ाई, डिजिटल भुगतान, आपात स्थिति में सहायता, जानकारी तुरंत उपलब्ध।\\n- हानियाँ (1.5): अधिक प्रयोग से आँखों व नींद पर बुरा प्रभाव, पढ़ाई से ध्यान भटकना, परिवार से दूरी, साइबर धोखाधड़ी।\\n- निष्कर्ष (1): मोबाइल अपने आप में न वरदान है न अभिशाप; उसका संतुलित और सावधानीपूर्ण उपयोग ही उसे वरदान बनाता है।\\n(भाषा की शुद्धता और क्रमबद्धता पर ध्यान दें।)"}, {"n": 10, "type": "Case-based", "topic": "पठन: अपठित गद्यांश", "q": "गद्यांश पढ़कर प्रश्नों के उत्तर दीजिए:\\nहमारे गाँव के पास एक पुराना तालाब था, जो वर्षों से कूड़े से भरा पड़ा था। गर्मियों में गाँव में पानी की भारी कमी हो जाती थी। एक दिन गाँव के युवाओं ने मिलकर तालाब की सफ़ाई का निश्चय किया। बच्चों, बुज़ुर्गों और महिलाओं ने भी श्रमदान किया। वर्षा ऋतु में तालाब पानी से भर गया। अब पशुओं को पीने का पानी मिलता है और आसपास के कुओं का जलस्तर भी बढ़ गया है। सच है, एकता में बड़ी शक्ति होती है।\\n(i) गाँव में गर्मियों में कौन-सी समस्या होती थी?\\n(ii) तालाब की सफ़ाई का निश्चय किसने किया?\\n(iii) तालाब भरने से कौन-से दो लाभ हुए?\\n(iv) 'श्रमदान' शब्द का अर्थ लिखिए।", "marks": 4, "answer": "(i) पानी की भारी कमी। (1)\\n(ii) गाँव के युवाओं ने। (1)\\n(iii) पशुओं को पीने का पानी मिलने लगा और आसपास के कुओं का जलस्तर बढ़ गया। (1)\\n(iv) श्रमदान - बिना पारिश्रमिक लिए सबके हित के लिए अपना परिश्रम देना। (1)"}]}, "Maths": {"book": "Ganita Prakash (Parts 1 & 2)", "questions": [{"n": 1, "type": "MCQ", "topic": "Squares and square roots", "q": "Which of the following is a perfect square?\\n(a) 1057 (b) 2352 (c) 1024 (d) 7928", "marks": 1, "answer": "(c) 1024, since 32 x 32 = 1024. (1057 and 7928 end in 7 and 8, and 2352 = 2^4 x 3 x 7^2 is not a perfect square.)"}, {"n": 2, "type": "Fill in the blank", "topic": "Exponents and powers", "q": "Fill in the blank: 2^5 x 2^(-3) = ______", "marks": 1, "answer": "4 (2^(5-3) = 2^2 = 4)"}, {"n": 3, "type": "True/False", "topic": "Cubes and cube roots", "q": "State True or False: The cube root of 2744 is 14.", "marks": 1, "answer": "True, since 14 x 14 x 14 = 196 x 14 = 2744."}, {"n": 4, "type": "MCQ", "topic": "Algebraic identities", "q": "Using the identity (a + b)^2 = a^2 + 2ab + b^2, the value of 103^2 is:\\n(a) 10609 (b) 10906 (c) 10069 (d) 10600", "marks": 1, "answer": "(a) 10609, since (100 + 3)^2 = 10000 + 600 + 9 = 10609."}, {"n": 5, "type": "Assertion-Reason", "topic": "Quadrilaterals", "q": "Assertion (A): The sum of the interior angles of any quadrilateral is 360 degrees.\\nReason (R): A diagonal divides a quadrilateral into two triangles.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A (2 x 180 = 360 degrees)."}, {"n": 6, "type": "Short answer", "topic": "Linear equations in one variable", "q": "Solve and verify: (2x - 3)/4 + 5 = x", "marks": 2, "answer": "Multiply both sides by 4: 2x - 3 + 20 = 4x, so 2x + 17 = 4x, so 2x = 17, x = 17/2 = 8.5. (1.5)\\nCheck: (17 - 3)/4 + 5 = 3.5 + 5 = 8.5 = x. (0.5)"}, {"n": 7, "type": "Short answer", "topic": "Cubes and cube roots", "q": "Find the smallest number by which 1350 must be multiplied so that the product is a perfect cube. Also find the cube root of the product.", "marks": 2, "answer": "1350 = 2 x 3 x 3 x 3 x 5 x 5 = 2 x 3^3 x 5^2. To complete triplets we need 2 x 2 and one more 5, i.e. multiply by 2^2 x 5 = 20. (1)\\nProduct = 1350 x 20 = 27000 = 2^3 x 3^3 x 5^3, cube root = 2 x 3 x 5 = 30. (1)"}, {"n": 8, "type": "Short answer", "topic": "Proportional reasoning (inverse proportion)", "q": "12 workers can build a wall in 15 days. Working at the same rate, how many days will 20 workers take to build the same wall?", "marks": 2, "answer": "Number of workers and days are in inverse proportion, so 12 x 15 = 20 x d. (1)\\nd = 180/20 = 9 days. (1)"}, {"n": 9, "type": "Long answer", "topic": "Algebraic expressions and identities", "q": "(a) Using a suitable identity, find 998^2.\\n(b) Simplify: (3x + 2y)^2 - (3x - 2y)^2\\n(c) Factorise: 49a^2 - 25b^2", "marks": 5, "answer": "(a) 998^2 = (1000 - 2)^2 = 1000000 - 2 x 1000 x 2 + 4 = 1000000 - 4000 + 4 = 996004. (2)\\n(b) (9x^2 + 12xy + 4y^2) - (9x^2 - 12xy + 4y^2) = 24xy. (2)\\n(c) (7a)^2 - (5b)^2 = (7a - 5b)(7a + 5b). (1)"}, {"n": 10, "type": "Case-based", "topic": "Data handling: pie charts and chance", "q": "In a survey of 30 students of Class 8 about their favourite sport: Cricket 12, Football 6, Badminton 9, Kabaddi 3. The class wants to draw a pie chart.\\n(i) Find the central angle for Cricket.\\n(ii) What percentage of students chose Football?\\n(iii) Write the ratio of Badminton to Kabaddi lovers in simplest form.\\n(iv) If one student is chosen at random, what is the probability that he/she likes Badminton?", "marks": 4, "answer": "(i) (12/30) x 360 = 144 degrees. (1)\\n(ii) (6/30) x 100 = 20%. (1)\\n(iii) 9 : 3 = 3 : 1. (1)\\n(iv) 9/30 = 3/10. (1)"}]}, "Science": {"book": "Curiosity", "questions": [{"n": 1, "type": "MCQ", "topic": "Microorganisms", "q": "Malaria is caused by which microorganism?\\n(a) Bacterium (b) Virus (c) Protozoan (Plasmodium) (d) Fungus", "marks": 1, "answer": "(c) Protozoan (Plasmodium), spread by the female Anopheles mosquito."}, {"n": 2, "type": "Fill in the blank", "topic": "Force and pressure", "q": "Fill in the blank: Pressure = Force / ______ . Its SI unit is the pascal.", "marks": 1, "answer": "Area (the area on which the force acts)"}, {"n": 3, "type": "True/False", "topic": "Sound", "q": "State True or False: Sound can travel through a vacuum.", "marks": 1, "answer": "False. Sound needs a medium (solid, liquid or gas) to travel."}, {"n": 4, "type": "MCQ", "topic": "Cell structure and function", "q": "Which cell organelle is known as the 'powerhouse of the cell'?\\n(a) Nucleus (b) Mitochondria (c) Ribosome (d) Vacuole", "marks": 1, "answer": "(b) Mitochondria"}, {"n": 5, "type": "Assertion-Reason", "topic": "Chemical effects of electric current", "q": "Assertion (A): Lemon juice conducts electricity.\\nReason (R): Lemon juice is acidic and contains ions that can carry charge.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Force: contact and non-contact forces", "q": "Differentiate between contact and non-contact forces. Give one example of each.", "marks": 2, "answer": "Contact force acts only when objects are in physical contact, e.g. muscular force or friction. (1)\\nNon-contact force acts without physical contact, e.g. magnetic force, gravitational force or electrostatic force. (1)"}, {"n": 7, "type": "Short answer", "topic": "Light: reflection", "q": "State the two laws of reflection of light.", "marks": 2, "answer": "(i) The angle of incidence is equal to the angle of reflection. (1)\\n(ii) The incident ray, the reflected ray and the normal at the point of incidence all lie in the same plane. (1)"}, {"n": 8, "type": "Short answer", "topic": "Force and pressure: numerical", "q": "A box weighing 600 N rests on the floor. Find the pressure it exerts when (i) its face of area 0.5 m^2 is on the floor, (ii) its face of area 0.2 m^2 is on the floor. Which gives more pressure?", "marks": 2, "answer": "(i) P = 600/0.5 = 1200 Pa. (0.5)\\n(ii) P = 600/0.2 = 3000 Pa. (0.5)\\nThe smaller area (0.2 m^2) gives more pressure, because pressure is inversely proportional to area for the same force. (1)"}, {"n": 9, "type": "Long answer", "topic": "Chemical effects of current: electroplating", "q": "What is electroplating? Describe how a copper plate can be used to deposit copper on an iron key. Mention any two uses of electroplating.", "marks": 5, "answer": "Marking points:\\n- Definition (1): depositing a thin layer of a desired metal on another metal using electricity.\\n- Set-up (2): take copper sulphate solution in a beaker (electrolyte); connect the copper plate to the positive terminal (anode) and the iron key to the negative terminal (cathode) of a battery; dip both in the solution.\\n- Process (1): on passing current, copper sulphate dissociates; copper from the solution deposits on the key, and copper from the plate dissolves into the solution, so the concentration stays the same.\\n- Uses (1, any two): chromium plating on taps and cycle parts for shine and rust-proofing; tin coating on iron cans for food; gold/silver plating on jewellery; zinc coating (galvanising) of iron."}, {"n": 10, "type": "Case-based", "topic": "Sound: frequency and audible range", "q": "Rohan clamps one end of a thin steel strip to a table and sets the free end vibrating. He counts 40 vibrations in 4 seconds.\\n(i) Find the frequency of vibration.\\n(ii) Find the time period.\\n(iii) Can a human hear this sound? Give a reason.\\n(iv) What happens to the pitch if he shortens the vibrating part of the strip?", "marks": 4, "answer": "(i) Frequency = 40/4 = 10 Hz. (1)\\n(ii) Time period = 1/10 = 0.1 s. (1)\\n(iii) No. The human audible range is about 20 Hz to 20,000 Hz; 10 Hz is below it (infrasonic). (1)\\n(iv) The frequency increases, so the pitch becomes higher. (1)"}]}, "Social Science": {"book": "Exploring Society: India and Beyond (Parts 1 & 2)", "questions": [{"n": 1, "type": "MCQ", "topic": "Colonial India: rise of the East India Company", "q": "The Battle of Plassey, which helped the East India Company gain control of Bengal, was fought in:\\n(a) 1757 (b) 1764 (c) 1857 (d) 1799", "marks": 1, "answer": "(a) 1757"}, {"n": 2, "type": "Fill in the blank", "topic": "The Constitution of India", "q": "Fill in the blank: The Constitution of India came into effect on 26 January ______.", "marks": 1, "answer": "1950"}, {"n": 3, "type": "True/False", "topic": "Parliament", "q": "State True or False: Members of the Rajya Sabha are directly elected by the people.", "marks": 1, "answer": "False. Most members are elected by the elected members of the State Legislative Assemblies, and 12 are nominated by the President."}, {"n": 4, "type": "MCQ", "topic": "Resources", "q": "Which of the following is a renewable resource?\\n(a) Coal (b) Petroleum (c) Solar energy (d) Natural gas", "marks": 1, "answer": "(c) Solar energy"}, {"n": 5, "type": "Assertion-Reason", "topic": "Judiciary", "q": "Assertion (A): The Supreme Court is called the guardian of the Constitution.\\nReason (R): It can declare a law invalid if it violates the Constitution (judicial review).\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Resources: renewable and non-renewable", "q": "Give two differences between renewable and non-renewable resources.", "marks": 2, "answer": "(i) Renewable resources are replenished naturally in a short time (solar, wind, water); non-renewable resources take millions of years to form and have limited stock (coal, petroleum). (1)\\n(ii) Renewable resources are generally less polluting and will not run out with sensible use; non-renewable resources get exhausted with use and usually cause more pollution. (1)"}, {"n": 7, "type": "Short answer", "topic": "Colonial India: expansion of British power", "q": "What was the Doctrine of Lapse? Name two states annexed under it.", "marks": 2, "answer": "A policy of Governor-General Lord Dalhousie under which, if an Indian ruler died without a natural male heir, his kingdom would 'lapse' and become part of Company territory; adopted sons were not recognised. (1)\\nStates annexed (any two): Satara, Jhansi, Nagpur, Sambalpur, Udaipur (Chhattisgarh). (1)"}, {"n": 8, "type": "Short answer", "topic": "Parliament: functions", "q": "Mention any two functions of the Indian Parliament.", "marks": 2, "answer": "Any two (1 each): makes laws for the country; controls and questions the government (question hour, no-confidence motion); approves the budget and controls public money; elects the Vice-President and, together with the elected members of the State Legislative Assemblies, the President; can amend the Constitution."}, {"n": 9, "type": "Long answer", "topic": "Colonial India: impact on the economy", "q": "Explain any five ways in which British colonial rule affected the Indian economy.", "marks": 5, "answer": "Any five (1 each):\\n1. Drain of wealth - revenue and profits were sent to Britain.\\n2. Decline of handicrafts and textiles - cheap machine-made British cloth ruined Indian weavers (deindustrialisation).\\n3. Heavy land revenue systems such as the Permanent Settlement made peasants poor and indebted to moneylenders.\\n4. Forced cultivation of commercial crops like indigo, reducing food crops (e.g. Champaran, Bengal indigo revolt).\\n5. Frequent famines due to food shortages and high taxes.\\n6. Railways and ports built mainly to carry raw materials out and British goods in."}, {"n": 10, "type": "Case-based", "topic": "The Constitution: Fundamental Rights", "q": "Read the case and answer.\\nTwelve-year-old Ramesh works fourteen hours a day at a firecracker unit near his village. He has never been to school. A social worker learns about him and wants to help him use the rights given by the Constitution.\\n(i) Which Fundamental Right is being violated in Ramesh's case?\\n(ii) Which right guarantees his free and compulsory education?\\n(iii) Where can the social worker go if this right is not protected?\\n(iv) Suggest one thing citizens can do to stop such practices.", "marks": 4, "answer": "(i) Right against Exploitation (Article 24 prohibits employing children below 14 in factories, mines and hazardous work). (1)\\n(ii) Right to Education (Article 21A: free and compulsory education for children aged 6-14). (1)\\n(iii) To the High Court or Supreme Court under the Right to Constitutional Remedies (Article 32/226); a complaint can also go to the police or child helpline 1098. (1)\\n(iv) Any one: report child labour to authorities, refuse to buy goods made by children, spread awareness, help children enrol in school. (1)"}]}, "Sanskrit": {"book": "Deepakam", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्दरूपाणि (अकारान्त पुंलिङ्ग)", "q": "'बालक' शब्दस्य षष्ठी-विभक्तेः बहुवचनरूपं किम्?\\n(क) बालकाः (ख) बालकेन (ग) बालकानाम् (घ) बालकेषु", "marks": 1, "answer": "(ग) बालकानाम्"}, {"n": 2, "type": "Fill in the blank", "topic": "धातुरूपाणि (लट्लकारः)", "q": "रिक्तस्थानं पूरयत: 'पठ्' धातोः लट्लकारे प्रथमपुरुषे बहुवचने रूपम् ______ भवति।", "marks": 1, "answer": "पठन्ति"}, {"n": 3, "type": "True/False", "topic": "सन्धिः (दीर्घसन्धिः)", "q": "सत्यम् असत्यं वा लिखत: 'विद्यालयः' = विद्या + आलयः इति दीर्घसन्धेः उदाहरणम् अस्ति।", "marks": 1, "answer": "सत्यम्"}, {"n": 4, "type": "MCQ", "topic": "प्रत्ययाः (क्त्वा, ल्यप्, तुमुन्)", "q": "'गत्वा' इति पदे कः प्रत्ययः अस्ति?\\n(क) तुमुन् (ख) क्त्वा (ग) ल्यप् (घ) क्त", "marks": 1, "answer": "(ख) क्त्वा (गम् + क्त्वा = गत्वा)"}, {"n": 5, "type": "MCQ", "topic": "संख्यावाचकाः शब्दाः", "q": "'पञ्चदश' इति संख्या अङ्केषु का?\\n(क) 5 (ख) 25 (ग) 15 (घ) 50", "marks": 1, "answer": "(ग) 15"}, {"n": 6, "type": "Short answer", "topic": "उपपदविभक्तयः", "q": "कोष्ठके दत्तशब्दस्य उचितविभक्तिरूपेण रिक्तस्थानानि पूरयत:\\n(i) रामः ______ (लक्ष्मण) सह वनं गच्छति।\\n(ii) ______ (शिक्षक) नमः।\\n(iii) ______ (ग्राम) बहिः उद्यानम् अस्ति।\\n(iv) ______ (विद्यालय) उभयतः वृक्षाः सन्ति।", "marks": 2, "answer": "(i) लक्ष्मणेन (सह-योगे तृतीया) (ii) शिक्षकाय (नमः-योगे चतुर्थी) (iii) ग्रामात् (बहिः-योगे पञ्चमी) (iv) विद्यालयम् (उभयतः-योगे द्वितीया)\\n(प्रत्येकं 1/2 अङ्कः)"}, {"n": 7, "type": "Short answer", "topic": "लकाराः (लृट्लकारः)", "q": "अधोलिखितवाक्यानि लृट्लकारे (भविष्यत्काले) परिवर्तयत:\\n(i) सः पाठं पठति।\\n(ii) वयं विद्यालयं गच्छामः।", "marks": 2, "answer": "(i) सः पाठं पठिष्यति। (1)\\n(ii) वयं विद्यालयं गमिष्यामः। (1)"}, {"n": 8, "type": "Short answer", "topic": "सन्धिविच्छेदः", "q": "सन्धिविच्छेदं कुरुत:\\n(i) हिमालयः (ii) सूर्योदयः (iii) इत्यादिः (iv) जगदीशः", "marks": 2, "answer": "(i) हिम + आलयः (ii) सूर्य + उदयः (iii) इति + आदिः (iv) जगत् + ईशः\\n(प्रत्येकं 1/2 अङ्कः)"}, {"n": 9, "type": "Long answer", "topic": "अनुवादः (हिन्दी से संस्कृत)", "q": "निम्नलिखित वाक्यों का संस्कृत में अनुवाद कीजिए:\\n1. राम पुस्तक पढ़ता है।\\n2. हम सब विद्यालय जाते हैं।\\n3. वृक्ष से पत्ते गिरते हैं।\\n4. माता भोजन पकाती है।\\n5. तुम कल कहाँ जाओगे?", "marks": 5, "answer": "1. रामः पुस्तकं पठति।\\n2. वयं विद्यालयं गच्छामः।\\n3. वृक्षात् पत्राणि पतन्ति।\\n4. माता भोजनं पचति।\\n5. त्वं श्वः कुत्र गमिष्यसि?\\n(प्रत्येकं वाक्यं 1 अङ्कः; विभक्तिः क्रियापदं च शुद्धं भवेत्।)"}, {"n": 10, "type": "Case-based", "topic": "अपठितगद्यांशः", "q": "गद्यांशं पठित्वा प्रश्नानाम् उत्तराणि संस्कृतेन लिखत:\\nएकस्मिन् ग्रामे मोहनः नाम कृषकः वसति स्म। सः प्रतिदिनं प्रातः उत्थाय क्षेत्रं गच्छति स्म। तस्य क्षेत्रे एकः विशालः आम्रवृक्षः आसीत्। ग्रीष्मकाले पथिकाः तस्य वृक्षस्य छायायां विश्रामं कुर्वन्ति स्म। मोहनः तेभ्यः शीतलं जलं ददाति स्म। अतः सर्वे जनाः तं सज्जनं मन्यन्ते स्म।\\n(i) कृषकस्य नाम किम्?\\n(ii) क्षेत्रे कः वृक्षः आसीत्?\\n(iii) पथिकाः कुत्र विश्रामं कुर्वन्ति स्म?\\n(iv) 'ददाति' इति क्रियापदस्य कर्तृपदं किम्?", "marks": 4, "answer": "(i) कृषकस्य नाम मोहनः। (1)\\n(ii) क्षेत्रे एकः विशालः आम्रवृक्षः आसीत्। (1)\\n(iii) पथिकाः आम्रवृक्षस्य छायायां विश्रामं कुर्वन्ति स्म। (1)\\n(iv) मोहनः। (1)"}]}, "Arts": {"book": "Kriti", "questions": [{"n": 1, "type": "MCQ", "topic": "Visual arts: colour theory", "q": "Which of the following is a secondary colour?\\n(a) Red (b) Blue (c) Yellow (d) Green", "marks": 1, "answer": "(d) Green (made by mixing the primary colours blue and yellow)."}, {"n": 2, "type": "Fill in the blank", "topic": "Visual arts: folk and tribal art of India", "q": "Fill in the blank: Warli painting, which uses simple circles, triangles and lines in white on a mud-coloured background, is a tribal art form of ______.", "marks": 1, "answer": "Maharashtra"}, {"n": 3, "type": "True/False", "topic": "Dance: classical dance forms", "q": "State True or False: Kathakali is a classical dance-drama of Kerala.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Music: swaras", "q": "How many basic (shuddha) swaras are there in Indian classical music (Sa Re Ga Ma Pa Dha Ni)?\\n(a) 5 (b) 7 (c) 8 (d) 12", "marks": 1, "answer": "(b) 7"}, {"n": 5, "type": "Assertion-Reason", "topic": "Visual arts: colour wheel", "q": "Assertion (A): Placing complementary colours side by side creates strong contrast.\\nReason (R): Complementary colours lie opposite each other on the colour wheel.\\n(a) Both A and R are true and R is the correct explanation of A. (b) Both A and R are true but R is not the correct explanation of A. (c) A is true but R is false. (d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Visual arts: warm and cool colours", "q": "What are warm and cool colours? Give two examples of each and the feeling each group creates.", "marks": 2, "answer": "Warm colours - red, orange, yellow; they suggest heat, energy, excitement and seem to come forward. (1)\\nCool colours - blue, green, violet; they suggest calm, peace, coolness and seem to move back. (1)"}, {"n": 7, "type": "Short answer", "topic": "Theatre and dance: rasa and bhava", "q": "What is meant by 'rasa' in Indian performing arts? Name any four of the nine rasas (navarasa).", "marks": 2, "answer": "Rasa is the emotional flavour or feeling that a performance creates in the audience (from Bharata's Natyashastra). (1)\\nAny four: shringara (love), hasya (laughter), karuna (sorrow), raudra (anger), veera (courage), bhayanaka (fear), bibhatsa (disgust), adbhuta (wonder), shanta (peace). (1)"}, {"n": 8, "type": "Short answer", "topic": "Theatre: elements of a performance", "q": "Explain the role of (i) props and (ii) costumes in a stage play.", "marks": 2, "answer": "(i) Props are objects used by actors (a stick, a basket, a phone); they make actions believable and help show the setting or story. (1)\\n(ii) Costumes are the clothes and make-up of actors; they show the character's age, profession, period and mood, and help the audience identify characters. (1)"}, {"n": 9, "type": "Long answer", "topic": "Visual arts: poster design using folk art", "q": "Describe the steps you would follow to make a Warli-inspired poster on the theme 'Save Water'. Mention materials, design elements and the message.", "marks": 5, "answer": "Marking points (1 each):\\n1. Materials: brown/ochre chart paper or paper coated with geru; white poster colour; thin brush; pencil.\\n2. Planning: rough sketch with a central idea, e.g. a well or river with people carrying water pots.\\n3. Warli elements: human figures made of two triangles joined at the tip, circle for the head, line limbs; circles for sun/moon, triangles for trees/mountains; repeated patterns and borders.\\n4. Composition: balanced layout, main scene in centre, a bold slogan such as 'Every Drop Counts' in clear lettering.\\n5. Finishing and message: neat outlines, uniform white paint, check readability; poster clearly conveys saving water through the traditional art style."}, {"n": 10, "type": "Activity", "topic": "Theatre: street play (nukkad natak)", "q": "Your class has to perform a 3-minute street play on 'Clean Surroundings' in the school corridor. Plan it by writing: (i) a catchy title, (ii) three characters, (iii) one way to attract the audience's attention, (iv) the closing message.", "marks": 4, "answer": "Sample answer (accept any creative, relevant plan; 1 mark each):\\n(i) Title: 'Kachra Nahin, Khazana!' or 'My Street, My Pride'.\\n(ii) Characters: a careless shopkeeper, a school child, a sanitation worker (or a talking dustbin).\\n(iii) Attract attention: begin with a loud dhol beat, a song or a chant in a circle; use loud clear voice, big gestures and a slogan.\\n(iv) Closing message: segregate wet and dry waste, use dustbins, keep public places clean; end with the audience repeating the slogan."}]}, "Physical Education": {"book": "Khel Yatra", "questions": [{"n": 1, "type": "MCQ", "topic": "Games: Kabaddi", "q": "How many players of a team are on the court at a time in a Kabaddi match?\\n(a) 5 (b) 7 (c) 9 (d) 11", "marks": 1, "answer": "(b) 7"}, {"n": 2, "type": "Fill in the blank", "topic": "Yoga: asanas", "q": "Fill in the blank: Tadasana is also called the ______ pose.", "marks": 1, "answer": "Mountain (palm-tree pose is also accepted)"}, {"n": 3, "type": "True/False", "topic": "Warm-up and cool-down", "q": "State True or False: Warm-up exercises should be done after the main physical activity.", "marks": 1, "answer": "False. Warm-up is done before the activity; cool-down is done after it."}, {"n": 4, "type": "MCQ", "topic": "Physical fitness components", "q": "Which of these is a health-related component of physical fitness?\\n(a) Agility (b) Reaction time (c) Cardiovascular endurance (d) Coordination", "marks": 1, "answer": "(c) Cardiovascular endurance (the others are skill-related components)."}, {"n": 5, "type": "MCQ", "topic": "Games: Kho-Kho", "q": "In Kho-Kho, how many players of the chasing team take the field at a time?\\n(a) 7 (b) 8 (c) 9 (d) 12", "marks": 1, "answer": "(c) 9 (8 sitting chasers and 1 active chaser)."}, {"n": 6, "type": "Short answer", "topic": "Warm-up and cool-down", "q": "Give one benefit of warming up and one benefit of cooling down.", "marks": 2, "answer": "Warm-up: raises body temperature and heart rate, makes muscles flexible, reduces risk of injury. (1)\\nCool-down: brings heart rate and breathing back to normal slowly, reduces muscle stiffness and soreness, prevents dizziness. (1)"}, {"n": 7, "type": "Short answer", "topic": "Sports injuries and first aid", "q": "What does RICE stand for in the first aid of a sprain? Why is ice applied?", "marks": 2, "answer": "R - Rest, I - Ice, C - Compression, E - Elevation. (1)\\nIce reduces swelling, pain and internal bleeding by narrowing blood vessels (apply wrapped in cloth for 15-20 minutes). (1)"}, {"n": 8, "type": "Short answer", "topic": "Nutrition for sports", "q": "Why do young athletes need (i) carbohydrates and (ii) proteins in their diet? Give one food source of each.", "marks": 2, "answer": "(i) Carbohydrates are the main source of energy for activity; sources: rice, chapati, potatoes, bananas. (1)\\n(ii) Proteins build and repair muscles and tissues; sources: dal, milk, paneer, eggs, soybean. (1)"}, {"n": 9, "type": "Long answer", "topic": "Yoga and healthy lifestyle", "q": "Explain any five benefits of practising yoga and regular physical activity for adolescents.", "marks": 5, "answer": "Any five (1 each):\\n1. Improves flexibility, strength and posture.\\n2. Strengthens heart and lungs; improves stamina.\\n3. Reduces stress and anxiety; improves concentration and memory (pranayama, meditation).\\n4. Helps maintain healthy body weight and prevents lifestyle diseases like obesity and diabetes.\\n5. Improves sleep quality and immunity.\\n6. Builds discipline, self-confidence, teamwork and a positive attitude."}, {"n": 10, "type": "Case-based", "topic": "Safety, hydration and first aid in sports", "q": "On Sports Day (temperature 38 degrees C), Aman ran the 800 m race without drinking water. After finishing he felt dizzy and had cramps in his calf.\\n(i) What is the likely cause of his condition?\\n(ii) Give two immediate first-aid steps.\\n(iii) What drink would help him recover best?\\n(iv) Suggest one precaution for the next event.", "marks": 4, "answer": "(i) Dehydration / heat exhaustion due to loss of water and salts through sweat. (1)\\n(ii) Move him to a cool shaded place, make him lie down with legs raised, loosen tight clothing, gently stretch and massage the calf. (any two, 1)\\n(iii) ORS, lemon water with salt and sugar, or coconut water (to replace water and salts). (1)\\n(iv) Drink water before, during and after the event; warm up properly; wear light clothing and a cap. (1)"}]}, "Vocational Education": {"book": "Kaushal Bodh", "questions": [{"n": 1, "type": "MCQ", "topic": "Work with life forms: soil and manure", "q": "Which of the following is an organic manure?\\n(a) Urea (b) Vermicompost (c) DAP (d) Potash", "marks": 1, "answer": "(b) Vermicompost"}, {"n": 2, "type": "Fill in the blank", "topic": "Work with life forms: composting", "q": "Fill in the blank: Making compost from kitchen and garden waste with the help of earthworms is called ______.", "marks": 1, "answer": "vermicomposting"}, {"n": 3, "type": "True/False", "topic": "Work with life forms: kitchen garden", "q": "State True or False: Most vegetables in a kitchen garden need at least 4-6 hours of direct sunlight daily.", "marks": 1, "answer": "True"}, {"n": 4, "type": "MCQ", "topic": "Work with machines and materials: electrical safety", "q": "Which device protects a household circuit by breaking it when excess current flows?\\n(a) Switch (b) Fuse / MCB (c) Bulb (d) Socket", "marks": 1, "answer": "(b) Fuse / MCB (miniature circuit breaker)"}, {"n": 5, "type": "MCQ", "topic": "Work in human services: communication skills", "q": "Which skill is most important when helping a customer at a school stall or help desk?\\n(a) Interrupting quickly (b) Active listening (c) Ignoring questions (d) Speaking loudly", "marks": 1, "answer": "(b) Active listening"}, {"n": 6, "type": "Short answer", "topic": "Work with machines and materials: tool safety", "q": "Write any two safety precautions to follow while working with electrical appliances or hand tools.", "marks": 2, "answer": "Any two (1 each): do not touch switches with wet hands; switch off the mains before repairing; use insulated tools and rubber footwear; wear gloves/goggles; keep tools in their place; never use damaged wires or plugs; work under adult supervision."}, {"n": 7, "type": "Short answer", "topic": "Human services: basic business maths", "q": "A student group spends Rs 500 to make greeting cards and sells them all for Rs 650. Find the profit and the profit percentage.", "marks": 2, "answer": "Profit = 650 - 500 = Rs 150. (1)\\nProfit % = (150/500) x 100 = 30%. (1)"}, {"n": 8, "type": "Short answer", "topic": "Work with life forms: fertilisers vs manure", "q": "Give two differences between chemical fertilisers and organic manure.", "marks": 2, "answer": "(i) Manure is natural, made from decomposed plant and animal waste; fertilisers are man-made chemicals produced in factories. (1)\\n(ii) Manure adds humus and improves soil texture and water-holding capacity; fertilisers supply specific nutrients (N, P, K) but overuse harms soil health and pollutes water. (1)"}, {"n": 9, "type": "Long answer", "topic": "Work with life forms: vermicompost project", "q": "Describe the steps to set up a vermicompost bin at school. Mention how you would know the compost is ready.", "marks": 5, "answer": "Marking points (1 each):\\n1. Choose a shaded, cool place; take a bin/pit with small drainage holes.\\n2. Make a base layer of sand/pebbles and a bedding of dry leaves, straw or shredded paper, sprinkle water.\\n3. Add partly decomposed cow dung and release earthworms (e.g. red wigglers / Eisenia fetida).\\n4. Add layers of biodegradable waste (vegetable peels, leaves; no plastic, oil, meat); keep moist (not soggy), cover with jute bag, turn gently occasionally.\\n5. Ready in about 6-8 weeks when it becomes dark brown, crumbly, soil-like and smells earthy; separate worms and use compost in the garden."}, {"n": 10, "type": "Case-based", "topic": "Human services: running a school stall", "q": "At the school fair, Class 8 sold 40 glasses of lemonade at Rs 15 each. They spent Rs 360 on lemons, sugar and water, and Rs 40 on paper cups.\\n(i) Find the total sales (revenue).\\n(ii) Find the total cost and the profit.\\n(iii) Find the profit percentage.\\n(iv) Suggest one eco-friendly change for their stall next year.", "marks": 4, "answer": "(i) Revenue = 40 x 15 = Rs 600. (1)\\n(ii) Cost = 360 + 40 = Rs 400; Profit = 600 - 400 = Rs 200. (1)\\n(iii) Profit % = (200/400) x 100 = 50%. (1)\\n(iv) Use washable steel glasses or kulhads instead of paper cups, compost lemon peels, keep a dustbin at the stall (any one reasonable idea). (1)"}]}}, "9": {"Maths": {"book": "Ganita Manjari", "questions": [{"n": 1, "type": "MCQ", "topic": "Number Systems", "q": "Which of the following is an irrational number?\\n(a) √16 (b) 0.333... (c) √7 (d) 22/7", "marks": 1, "answer": "(c) √7 — it cannot be written as p/q; √16 = 4, 0.333... = 1/3 and 22/7 are rational."}, {"n": 2, "type": "MCQ", "topic": "Polynomials", "q": "The degree of the polynomial 5x³ − 4x² + 7x⁴ − 2 is:\\n(a) 3 (b) 4 (c) 5 (d) 7", "marks": 1, "answer": "(b) 4 — the highest power of x is x⁴."}, {"n": 3, "type": "Fill in the blank", "topic": "Coordinate Geometry", "q": "The point (−3, 5) lies in the ________ quadrant.", "marks": 1, "answer": "Second quadrant (x negative, y positive)."}, {"n": 4, "type": "True/False", "topic": "Linear Equations in Two Variables", "q": "The linear equation 2x + 3y = 6 has only one solution.", "marks": 1, "answer": "False — a linear equation in two variables has infinitely many solutions, e.g. (3, 0), (0, 2), (6, −2)."}, {"n": 5, "type": "Assertion-Reason", "topic": "Number Systems", "q": "Assertion (A): 3 + √2 is an irrational number.\\nReason (R): The sum of a rational number and an irrational number is irrational.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Polynomials", "q": "Using the Remainder Theorem, find the remainder when p(x) = x³ + 3x² + 3x + 1 is divided by (x + 1). What can you conclude about (x + 1)?", "marks": 2, "answer": "Zero of x + 1 is x = −1.\\np(−1) = (−1)³ + 3(−1)² + 3(−1) + 1 = −1 + 3 − 3 + 1 = 0. (1 mark)\\nRemainder = 0, so (x + 1) is a factor of p(x) (Factor Theorem). (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Areas — Heron's Formula", "q": "Find the area of a triangle whose sides are 13 cm, 14 cm and 15 cm using Heron's formula.", "marks": 2, "answer": "s = (13 + 14 + 15)/2 = 21 cm. (½ mark)\\nArea = √[s(s−a)(s−b)(s−c)] = √(21 × 8 × 7 × 6) (½ mark)\\n= √7056 = 84 cm². (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Number Systems", "q": "Rationalise the denominator of 1/(√5 + √2).", "marks": 2, "answer": "Multiply numerator and denominator by (√5 − √2): (1 mark)\\n(√5 − √2)/[(√5)² − (√2)²] = (√5 − √2)/(5 − 2) = (√5 − √2)/3. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Surface Areas and Volumes", "q": "A right circular cone has height 24 cm and base radius 7 cm. Find (i) its slant height, (ii) curved surface area, (iii) total surface area and (iv) volume. (Take π = 22/7)", "marks": 5, "answer": "(i) l = √(h² + r²) = √(576 + 49) = √625 = 25 cm. (1 mark)\\n(ii) CSA = πrl = (22/7) × 7 × 25 = 550 cm². (1 mark)\\n(iii) TSA = πr(l + r) = (22/7) × 7 × (25 + 7) = 22 × 32 = 704 cm². (1½ marks)\\n(iv) Volume = (1/3)πr²h = (1/3) × (22/7) × 49 × 24 = (1/3) × 22 × 7 × 24 = 1232 cm³. (1½ marks)"}, {"n": 10, "type": "Case-based", "topic": "Statistics", "q": "A teacher recorded the marks (out of 25) scored by 10 students in a class test:\\n12, 15, 18, 15, 20, 14, 15, 17, 19, 15\\nShe wants to use these to understand the performance of the class.\\n(i) Find the mean marks. (1)\\n(ii) Find the median marks. (1)\\n(iii) Find the mode. (1)\\n(iv) Find the range of the data. (1)", "marks": 4, "answer": "(i) Sum = 160; Mean = 160/10 = 16.\\n(ii) Arranged: 12, 14, 15, 15, 15, 15, 17, 18, 19, 20. n = 10 (even), median = (5th + 6th)/2 = (15 + 15)/2 = 15.\\n(iii) Mode = 15 (occurs 4 times).\\n(iv) Range = 20 − 12 = 8."}]}, "Science": {"book": "Exploration", "questions": [{"n": 1, "type": "MCQ", "topic": "Matter — Physical and Chemical Changes", "q": "Which of the following is a chemical change?\\n(a) Melting of ice (b) Rusting of iron (c) Dissolving salt in water (d) Evaporation of water", "marks": 1, "answer": "(b) Rusting of iron — a new substance (iron oxide) is formed."}, {"n": 2, "type": "Fill in the blank", "topic": "Force and Laws of Motion", "q": "The SI unit of force is ________.", "marks": 1, "answer": "newton (N); 1 N = 1 kg m s⁻²."}, {"n": 3, "type": "MCQ", "topic": "The Cell", "q": "Which cell organelle is known as the 'powerhouse of the cell'?\\n(a) Ribosome (b) Golgi apparatus (c) Mitochondria (d) Lysosome", "marks": 1, "answer": "(c) Mitochondria — they release energy in the form of ATP."}, {"n": 4, "type": "True/False", "topic": "Sound", "q": "Sound can travel through a vacuum.", "marks": 1, "answer": "False — sound is a mechanical wave and needs a material medium (solid, liquid or gas) to travel."}, {"n": 5, "type": "Assertion-Reason", "topic": "Force and Laws of Motion", "q": "Assertion (A): Passengers standing in a bus fall backward when the bus starts suddenly.\\nReason (R): A body tends to remain in its state of rest due to inertia.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Atoms and Molecules", "q": "Calculate the molar mass of sulphuric acid (H₂SO₄). How many moles are present in 49 g of it? (H = 1 u, S = 32 u, O = 16 u)", "marks": 2, "answer": "Molar mass = 2(1) + 32 + 4(16) = 2 + 32 + 64 = 98 g/mol. (1 mark)\\nMoles = given mass/molar mass = 49/98 = 0.5 mol. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Tissues", "q": "Give two differences between xylem and phloem.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Xylem carries water and minerals from roots to leaves; phloem carries food (prepared by leaves) to other parts.\\n2. Transport in xylem is upward (one direction); in phloem it is in both directions.\\n3. Xylem has mostly dead elements (tracheids, vessels, fibres); phloem has mostly living cells (sieve tubes, companion cells), except phloem fibres."}, {"n": 8, "type": "Short answer", "topic": "Motion", "q": "A car increases its speed uniformly from 18 km/h to 36 km/h in 5 s. Find its acceleration and the distance covered in this time.", "marks": 2, "answer": "u = 18 km/h = 5 m/s; v = 36 km/h = 10 m/s; t = 5 s.\\na = (v − u)/t = (10 − 5)/5 = 1 m/s². (1 mark)\\ns = ut + ½at² = 5 × 5 + ½ × 1 × 25 = 25 + 12.5 = 37.5 m. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Work and Energy", "q": "(a) Define kinetic energy and derive the expression KE = ½mv² for an object of mass m moving with velocity v. (3)\\n(b) A ball of mass 2 kg is held at a height of 5 m. Find its potential energy and its speed just before it hits the ground. (g = 10 m/s²) (2)", "marks": 5, "answer": "(a) Kinetic energy is the energy possessed by a body due to its motion. (½)\\nDerivation: Let a force F act on a body of mass m at rest (u = 0) and give it velocity v over displacement s. Work W = F × s = ma × s. (½)\\nFrom v² − u² = 2as, s = v²/2a. (1)\\nW = ma × v²/2a = ½mv². This work is stored as KE, so KE = ½mv². (1)\\n(b) PE = mgh = 2 × 10 × 5 = 100 J. (1)\\nAt ground all PE → KE: ½ × 2 × v² = 100 ⇒ v² = 100 ⇒ v = 10 m/s. (1)"}, {"n": 10, "type": "Case-based", "topic": "Gravitation", "q": "An astronaut of mass 60 kg is training for a mission to the Moon. Her trainer tells her that on the Moon her weight will be about one-sixth of her weight on Earth, although her mass will not change. All objects attract each other with a gravitational force described by Newton's universal law of gravitation. (Take g on Earth = 9.8 m/s²)\\n(i) What is her weight on Earth? (1)\\n(ii) What will be her mass and approximate weight on the Moon? (1)\\n(iii) Why is her weight less on the Moon? (1)\\n(iv) Write the mathematical form of the universal law of gravitation. (1)", "marks": 4, "answer": "(i) W = mg = 60 × 9.8 = 588 N.\\n(ii) Mass stays 60 kg; weight ≈ 588/6 = 98 N.\\n(iii) The Moon has much smaller mass (and radius) than the Earth, so its gravitational pull (acceleration due to gravity) is about 1/6 of Earth's.\\n(iv) F = G m₁m₂/r², where G = 6.67 × 10⁻¹¹ N m² kg⁻² and r is the distance between the centres of the two masses."}]}, "Social Science": {"book": "Understanding Society: India and Beyond", "questions": [{"n": 1, "type": "Fill in the blank", "topic": "Geography — India: Size and Location", "q": "The ________ passes almost through the middle of India, dividing it into two nearly equal parts.", "marks": 1, "answer": "Tropic of Cancer (23°30′N)."}, {"n": 2, "type": "MCQ", "topic": "Economics — Factors of Production", "q": "Land, labour, physical capital and ________ are the four requirements (factors) of production.\\n(a) Raw materials (b) Human capital (c) Market (d) Government", "marks": 1, "answer": "(b) Human capital — the knowledge and enterprise to put the other factors together."}, {"n": 3, "type": "True/False", "topic": "Political Science — What is Democracy?", "q": "In a democracy, the final decision-making power rests with those elected by the people.", "marks": 1, "answer": "True."}, {"n": 4, "type": "MCQ", "topic": "Geography — Climate", "q": "Which winds bring most of the rainfall to India?\\n(a) North-east trade winds (b) South-west monsoon winds (c) Westerlies (d) Loo", "marks": 1, "answer": "(b) South-west monsoon winds (June to September)."}, {"n": 5, "type": "Assertion-Reason", "topic": "Political Science — Rights", "q": "Assertion (A): The Constitution of India guarantees Fundamental Rights to citizens.\\nReason (R): Fundamental Rights protect citizens against arbitrary and absolute exercise of power by the State.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Geography — Climate", "q": "Distinguish between weather and climate.", "marks": 2, "answer": "Weather is the state of the atmosphere (temperature, rainfall, humidity, wind) over an area at a particular time; it changes daily or even hourly. (1 mark)\\nClimate is the average weather conditions of a large area over a long period (30 years or more); it is relatively stable. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Political Science — Democracy", "q": "State any two features of a democracy.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Rulers are elected by the people and hold final decision-making power.\\n2. Free and fair elections offer a real choice to change rulers.\\n3. Universal adult franchise — one person, one vote, one value.\\n4. Government works within limits set by the constitution and respects citizens' rights (rule of law)."}, {"n": 8, "type": "Short answer", "topic": "Economics — People as Resource", "q": "What is disguised unemployment? Give an example.", "marks": 2, "answer": "Disguised unemployment is when more people are engaged in work than needed, so some appear employed but add nothing to output; removing them does not reduce production. (1 mark)\\nExample: five members of a family working on a small farm that needs only three; the extra two are disguisedly unemployed. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Geography — Physical Features of India", "q": "Describe the major physiographic divisions of India.", "marks": 5, "answer": "One mark per division with a key feature (any five of six, or combined):\\n1. The Himalayan Mountains — young fold mountains in the north; three parallel ranges: Himadri, Himachal and Shiwaliks.\\n2. The Northern Plains — formed by alluvium of the Indus, Ganga and Brahmaputra; fertile, densely populated.\\n3. The Peninsular Plateau — oldest landmass, made of old crystalline, igneous and metamorphic rocks; Central Highlands and Deccan Plateau; Western and Eastern Ghats.\\n4. The Indian Desert — west of the Aravalli hills; sandy, with dunes and scanty rainfall.\\n5. The Coastal Plains — narrow western coast (Konkan, Kannad, Malabar) and wider eastern coast (Northern Circar, Coromandel) with deltas.\\n6. The Islands — Lakshadweep (coral) in the Arabian Sea and Andaman & Nicobar in the Bay of Bengal."}, {"n": 10, "type": "Case-based", "topic": "Economics — Poverty as a Challenge", "q": "Read the passage and answer:\\nRamesh works as a daily-wage labourer in a town. On many days he gets no work. His family cannot afford two proper meals, his children have dropped out of school and they live in a one-room shack. In India, poverty is commonly measured using a 'poverty line', which is based on the minimum level of consumption of food and other basic needs. The government runs programmes such as MGNREGA to provide work to rural households.\\n(i) Mention two indicators of poverty seen in Ramesh's family. (1)\\n(ii) What is a poverty line? (1)\\n(iii) What does MGNREGA provide? (1)\\n(iv) Suggest one way to reduce poverty in the long run. (1)", "marks": 4, "answer": "(i) Irregular work/unemployment, hunger (no two meals), children out of school, poor housing — any two.\\n(ii) The poverty line is a minimum level of income or consumption (food, clothing, shelter, etc.) needed to fulfil basic needs; those below it are called poor.\\n(iii) MGNREGA (2005) guarantees 100 days of wage employment in a year to every rural household.\\n(iv) Promoting education and skill development / generating employment / economic growth / access to health care — any one."}]}, "English": {"book": "Kaveri", "questions": [{"n": 1, "type": "MCQ", "topic": "Grammar — Tenses", "q": "Choose the correct option: My sister ________ to school by bus every day.\\n(a) go (b) goes (c) going (d) gone", "marks": 1, "answer": "(b) goes — simple present tense with a singular subject."}, {"n": 2, "type": "Fill in the blank", "topic": "Grammar — Modals", "q": "Fill in the blank with a suitable modal: You ________ wear a helmet while riding a two-wheeler; it is the law.", "marks": 1, "answer": "must (expresses obligation/compulsion)."}, {"n": 3, "type": "MCQ", "topic": "Vocabulary", "q": "Choose the word closest in meaning to 'diligent':\\n(a) lazy (b) hardworking (c) careless (d) proud", "marks": 1, "answer": "(b) hardworking."}, {"n": 4, "type": "Fill in the blank", "topic": "Grammar — Reported Speech", "q": "Complete the reported speech: He said, 'I am tired.' → He said that he ________ tired.", "marks": 1, "answer": "was (present tense changes to past in reported speech)."}, {"n": 5, "type": "True/False", "topic": "Grammar — Articles", "q": "The article 'an' is used before words that begin with a vowel sound, as in 'an hour'.", "marks": 1, "answer": "True — 'hour' begins with a vowel sound because the 'h' is silent."}, {"n": 6, "type": "Short answer", "topic": "Grammar — Error Correction", "q": "Correct the errors in the following sentences:\\n(a) Each of the boys have a new book.\\n(b) She is more cleverer than her brother.", "marks": 2, "answer": "(a) Each of the boys has a new book. ('Each' takes a singular verb.) (1 mark)\\n(b) She is cleverer than her brother. (Double comparative removed.) (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Grammar — Active and Passive Voice", "q": "Change into the passive voice:\\n(a) The chef cooked a delicious meal.\\n(b) People speak English all over the world.", "marks": 2, "answer": "(a) A delicious meal was cooked by the chef. (1 mark)\\n(b) English is spoken all over the world. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Vocabulary — Idioms", "q": "Give the meaning of each idiom and use it in a sentence: (a) break the ice (b) once in a blue moon", "marks": 2, "answer": "(a) break the ice — to start a conversation in an awkward or new situation. E.g. The teacher told a joke to break the ice on the first day. (1 mark)\\n(b) once in a blue moon — very rarely. E.g. My uncle visits us only once in a blue moon. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Writing — Diary Entry", "q": "You recently visited a village fair with your family. Write a diary entry in about 120 words describing the sights, sounds and your feelings about the visit.", "marks": 5, "answer": "Marking points:\\nFormat (1): date/day/time, 'Dear Diary', signature/name at end.\\nContent (2): description of the fair — stalls, rides, food, crowds, music, local crafts; what the writer did; personal feelings (joy, excitement, lessons such as appreciating rural culture).\\nExpression (2): first person, past tense, logical sequence, coherence, correct grammar and spelling, varied vocabulary.\\nSample opening: 'Sunday, 12 October 2026, 9 p.m. Dear Diary, today was one of the most colourful days of my life...'"}, {"n": 10, "type": "Case-based", "topic": "Reading — Unseen Passage", "q": "Read the passage and answer:\\nTrees are the lungs of our planet. They absorb carbon dioxide and release oxygen, which all living beings need. A single large tree can provide enough oxygen for a family for a year. Trees also reduce soil erosion, give shelter to birds and animals, and keep cities cool. Yet every year, millions of trees are cut down to make space for roads and buildings. If we plant one tree for every tree that is cut, we can protect our environment for future generations.\\n(i) Why are trees called 'the lungs of our planet'? (1)\\n(ii) Mention two other benefits of trees given in the passage. (1)\\n(iii) Why are trees being cut down? (1)\\n(iv) Find a word in the passage that means 'the gradual washing away of soil'. (1)", "marks": 4, "answer": "(i) Because they absorb carbon dioxide and release oxygen needed by living beings.\\n(ii) Any two: reduce soil erosion, shelter birds and animals, keep cities cool.\\n(iii) To make space for roads and buildings.\\n(iv) erosion"}]}, "Hindi": {"book": "Ganga", "questions": [{"n": 1, "type": "MCQ", "topic": "व्याकरण — संधि", "q": "'विद्यालय' शब्द का सही संधि-विच्छेद है —\\n(a) विद्य + आलय (b) विद्या + आलय (c) विद्या + लय (d) विद + आलय", "marks": 1, "answer": "(b) विद्या + आलय — दीर्घ संधि (आ + आ = आ)।"}, {"n": 2, "type": "Fill in the blank", "topic": "व्याकरण — उपसर्ग", "q": "'अनुपस्थित' शब्द में ________ उपसर्ग है।", "marks": 1, "answer": "अन् (अन् + उपस्थित)।"}, {"n": 3, "type": "MCQ", "topic": "व्याकरण — प्रत्यय", "q": "'सुंदरता' शब्द में प्रयुक्त प्रत्यय है —\\n(a) ता (b) रता (c) सुं (d) आ", "marks": 1, "answer": "(a) ता (सुंदर + ता)।"}, {"n": 4, "type": "True/False", "topic": "व्याकरण — समास", "q": "'नीलकमल' (नीला है जो कमल) में कर्मधारय समास है।", "marks": 1, "answer": "सत्य — इसमें विशेषण (नीला) और विशेष्य (कमल) का संबंध है, अतः कर्मधारय समास है।"}, {"n": 5, "type": "MCQ", "topic": "शब्द-भंडार — पर्यायवाची", "q": "'सूर्य' का पर्यायवाची शब्द है —\\n(a) सुधाकर (b) दिनकर (c) राकेश (d) निशाकर", "marks": 1, "answer": "(b) दिनकर। (सुधाकर, राकेश, निशाकर — चंद्रमा के पर्यायवाची हैं।)"}, {"n": 6, "type": "Short answer", "topic": "मुहावरे", "q": "निम्नलिखित मुहावरों का अर्थ लिखकर वाक्य में प्रयोग कीजिए —\\n(क) आँखों का तारा (ख) नौ दो ग्यारह होना", "marks": 2, "answer": "(क) आँखों का तारा — बहुत प्यारा। वाक्य: इकलौता बेटा होने के कारण मोहन अपनी माँ की आँखों का तारा है। (1 अंक)\\n(ख) नौ दो ग्यारह होना — भाग जाना। वाक्य: पुलिस को देखते ही चोर नौ दो ग्यारह हो गया। (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "व्याकरण — अर्थ के आधार पर वाक्य-भेद", "q": "अर्थ के आधार पर वाक्य-भेद पहचानिए —\\n(क) वाह! कितना सुंदर दृश्य है।\\n(ख) शायद आज वर्षा हो।", "marks": 2, "answer": "(क) विस्मयादिबोधक वाक्य। (1 अंक)\\n(ख) संदेहवाचक वाक्य। (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "शब्द-भंडार — विलोम शब्द", "q": "निम्नलिखित शब्दों के विलोम शब्द लिखिए — आदर, सजीव, उन्नति, मान", "marks": 2, "answer": "आदर — अनादर; सजीव — निर्जीव; उन्नति — अवनति; मान — अपमान। (प्रत्येक ½ अंक)"}, {"n": 9, "type": "Long answer", "topic": "लेखन — औपचारिक पत्र", "q": "अपने विद्यालय के प्रधानाचार्य को पत्र लिखकर विद्यालय में पुस्तकालय की पुस्तकें बढ़ाने और पुस्तकालय का समय बढ़ाने का अनुरोध कीजिए। (लगभग 100–120 शब्द)", "marks": 5, "answer": "अंक-विभाजन:\\nप्रारूप (2 अंक): सेवा में, प्रधानाचार्य, विद्यालय का नाम-पता; दिनांक; विषय; संबोधन (महोदय/महोदया); समापन (आपका आज्ञाकारी शिष्य), नाम, कक्षा, अनुक्रमांक।\\nविषय-वस्तु (2 अंक): पुस्तकालय में नई व रोचक पुस्तकों, पत्र-पत्रिकाओं की कमी; छात्रों को पढ़ने के लिए पर्याप्त समय न मिलना; पुस्तकें और समय बढ़ाने से पढ़ने की रुचि व ज्ञान में वृद्धि; विनम्र अनुरोध।\\nभाषा (1 अंक): शुद्ध, शिष्ट एवं स्पष्ट भाषा।"}, {"n": 10, "type": "Case-based", "topic": "अपठित गद्यांश", "q": "निम्नलिखित गद्यांश पढ़कर प्रश्नों के उत्तर दीजिए —\\nपरिश्रम ही सफलता की कुंजी है। जो व्यक्ति मेहनत से नहीं घबराता, वह जीवन में हर कठिनाई को पार कर लेता है। भाग्य के भरोसे बैठे रहने वाले लोग अक्सर पीछे रह जाते हैं। इतिहास गवाह है कि महान व्यक्तियों ने कठोर परिश्रम से ही ऊँचाइयाँ प्राप्त कीं। विद्यार्थी जीवन परिश्रम की आदत डालने का सबसे अच्छा समय है।\\n(i) सफलता की कुंजी किसे कहा गया है? (1)\\n(ii) कौन लोग पीछे रह जाते हैं? (1)\\n(iii) परिश्रम की आदत डालने का सबसे अच्छा समय कौन-सा है? (1)\\n(iv) गद्यांश के लिए उपयुक्त शीर्षक लिखिए। (1)", "marks": 4, "answer": "(i) परिश्रम को सफलता की कुंजी कहा गया है।\\n(ii) भाग्य के भरोसे बैठे रहने वाले लोग पीछे रह जाते हैं।\\n(iii) विद्यार्थी जीवन।\\n(iv) 'परिश्रम का महत्त्व' / 'परिश्रम ही सफलता की कुंजी'।"}]}, "Sanskrit": {"book": "Sharada", "questions": [{"n": 1, "type": "MCQ", "topic": "शब्दरूपाणि", "q": "'बालक' शब्दस्य षष्ठी-विभक्तौ एकवचने रूपम् अस्ति —\\n(a) बालकेन (b) बालकाय (c) बालकस्य (d) बालके", "marks": 1, "answer": "(c) बालकस्य।"}, {"n": 2, "type": "Fill in the blank", "topic": "धातुरूपाणि", "q": "'पठ्' धातोः लट्लकारे प्रथमपुरुषे बहुवचने रूपम् ________ भवति।", "marks": 1, "answer": "पठन्ति।"}, {"n": 3, "type": "MCQ", "topic": "सन्धिः", "q": "'विद्यालयः' इति पदस्य सन्धिविच्छेदः अस्ति —\\n(a) विद्य + आलयः (b) विद्या + आलयः (c) विद्या + लयः (d) विद + आलयः", "marks": 1, "answer": "(b) विद्या + आलयः (दीर्घसन्धिः)।"}, {"n": 4, "type": "True/False", "topic": "लकाराः", "q": "'गच्छति' इति पदं लृट्लकारे अस्ति। (सत्यम् / असत्यम्)", "marks": 1, "answer": "असत्यम् — 'गच्छति' लट्लकारे (वर्तमानकाले) अस्ति; लृट्लकारे 'गमिष्यति' भवति।"}, {"n": 5, "type": "MCQ", "topic": "सर्वनामशब्दाः", "q": "'सः' इति सर्वनामपदस्य स्त्रीलिङ्गरूपम् अस्ति —\\n(a) तत् (b) सा (c) ते (d) ताः", "marks": 1, "answer": "(b) सा।"}, {"n": 6, "type": "Short answer", "topic": "प्रश्ननिर्माणम्", "q": "रेखाङ्कितपदानि आधृत्य प्रश्ननिर्माणं कुरुत —\\n(क) बालकाः (रेखाङ्कितम्) क्रीडाक्षेत्रे क्रीडन्ति।\\n(ख) बालकाः क्रीडाक्षेत्रे (रेखाङ्कितम्) क्रीडन्ति।", "marks": 2, "answer": "(क) के क्रीडाक्षेत्रे क्रीडन्ति? (1 अंक)\\n(ख) बालकाः कुत्र क्रीडन्ति? (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "अनुवादः", "q": "संस्कृतभाषायाम् अनुवादं कुरुत —\\n(क) राम पुस्तक पढ़ता है।\\n(ख) हम सब विद्यालय जाते हैं।", "marks": 2, "answer": "(क) रामः पुस्तकं पठति। (1 अंक)\\n(ख) वयं विद्यालयं गच्छामः। (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "उपपदविभक्तिः", "q": "कोष्ठकात् उचितं पदं चित्वा रिक्तस्थानानि पूरयत —\\n(क) ________ नमः। (गणेश)\\n(ख) सीता ________ सह वनम् अगच्छत्। (राम)", "marks": 2, "answer": "(क) गणेशाय नमः। ('नमः' योगे चतुर्थी) (1 अंक)\\n(ख) सीता रामेण सह वनम् अगच्छत्। ('सह' योगे तृतीया) (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "अनुच्छेदलेखनम्", "q": "'मम विद्यालयः' इति विषयम् अधिकृत्य संस्कृतभाषायां पञ्च वाक्यानि लिखत।", "marks": 5, "answer": "प्रत्येकं शुद्धं वाक्यम् 1 अंकः। आदर्श-उत्तरम् —\\n1. मम विद्यालयः नगरस्य मध्ये अस्ति।\\n2. मम विद्यालयः अतीव सुन्दरः विशालः च अस्ति।\\n3. अत्र एकः पुस्तकालयः, एका प्रयोगशाला, एकं क्रीडाक्षेत्रं च सन्ति।\\n4. अत्र शिक्षकाः स्नेहेन छात्रान् पाठयन्ति।\\n5. अहं मम विद्यालये बहु स्निह्यामि। (अथवा: मम विद्यालयः मह्यं रोचते।)"}, {"n": 10, "type": "Case-based", "topic": "अपठितगद्यांशः", "q": "अधोलिखितं गद्यांशं पठित्वा प्रश्नान् उत्तरत —\\nएकस्मिन् वने एकः विशालः वृक्षः आसीत्। तस्य शाखासु बहवः खगाः निवसन्ति स्म। ग्रीष्मकाले पथिकाः तस्य छायायां विश्रामं कुर्वन्ति स्म। वृक्षः सर्वेभ्यः फलानि छायां च ददाति। अतः वृक्षाः अस्माकं मित्राणि सन्ति। वयं वृक्षान् रक्षेम।\\n(i) वृक्षस्य शाखासु के निवसन्ति स्म? (एकपदेन) (1)\\n(ii) पथिकाः कदा वृक्षस्य छायायां विश्रामं कुर्वन्ति स्म? (एकपदेन) (1)\\n(iii) वृक्षः सर्वेभ्यः किं ददाति? (पूर्णवाक्येन) (1)\\n(iv) 'निवसन्ति स्म' इति क्रियापदस्य कर्तृपदं किम्? (1)", "marks": 4, "answer": "(i) खगाः।\\n(ii) ग्रीष्मकाले।\\n(iii) वृक्षः सर्वेभ्यः फलानि छायां च ददाति।\\n(iv) खगाः।"}]}}, "10": {"Maths": {"book": "Mathematics", "questions": [{"n": 1, "type": "MCQ", "topic": "Real Numbers", "q": "The HCF of 96 and 404 is:\\n(a) 2 (b) 4 (c) 8 (d) 12", "marks": 1, "answer": "(b) 4 — 96 = 2⁵ × 3 and 404 = 2² × 101; HCF = 2² = 4."}, {"n": 2, "type": "MCQ", "topic": "Polynomials", "q": "The sum and product of the zeroes of x² − 5x + 6 are respectively:\\n(a) 5, 6 (b) −5, 6 (c) 6, 5 (d) −5, −6", "marks": 1, "answer": "(a) 5, 6 — sum = −b/a = 5, product = c/a = 6 (zeroes are 2 and 3)."}, {"n": 3, "type": "Fill in the blank", "topic": "Arithmetic Progressions", "q": "The 11th term of the AP 3, 7, 11, 15, ... is ________.", "marks": 1, "answer": "43 — a = 3, d = 4; a₁₁ = 3 + 10 × 4 = 43."}, {"n": 4, "type": "True/False", "topic": "Introduction to Trigonometry", "q": "sin 60° cos 30° + cos 60° sin 30° = 1", "marks": 1, "answer": "True — (√3/2)(√3/2) + (1/2)(1/2) = 3/4 + 1/4 = 1."}, {"n": 5, "type": "Assertion-Reason", "topic": "Probability", "q": "Assertion (A): The probability of an event cannot be 1.2.\\nReason (R): For any event E, 0 ≤ P(E) ≤ 1.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Coordinate Geometry", "q": "Find the coordinates of the point which divides the line segment joining (−1, 7) and (4, −3) in the ratio 2 : 3.", "marks": 2, "answer": "Section formula with m : n = 2 : 3. (½ mark)\\nx = (2 × 4 + 3 × (−1))/(2 + 3) = (8 − 3)/5 = 1. (½ mark)\\ny = (2 × (−3) + 3 × 7)/5 = (−6 + 21)/5 = 3. (½ mark)\\nRequired point = (1, 3). (½ mark)"}, {"n": 7, "type": "Short answer", "topic": "Pair of Linear Equations in Two Variables", "q": "Solve by elimination: x + y = 14 and x − y = 4.", "marks": 2, "answer": "Adding: 2x = 18 ⇒ x = 9. (1 mark)\\nSubstituting: 9 + y = 14 ⇒ y = 5. (1 mark)\\nCheck: 9 − 5 = 4 ✓. Solution x = 9, y = 5."}, {"n": 8, "type": "Short answer", "topic": "Quadratic Equations", "q": "Find the roots of 2x² − 7x + 3 = 0 by factorisation.", "marks": 2, "answer": "2x² − 6x − x + 3 = 0 ⇒ 2x(x − 3) − 1(x − 3) = 0 ⇒ (2x − 1)(x − 3) = 0. (1 mark)\\nx = 1/2 or x = 3. (1 mark)\\n(Check: D = 49 − 24 = 25 > 0, two distinct real roots.)"}, {"n": 9, "type": "Long answer", "topic": "Some Applications of Trigonometry", "q": "The angle of elevation of the top of a tower from a point on the ground is 30°. On walking 40 m towards the tower, the angle of elevation becomes 60°. Find the height of the tower and the distance of the second point from the foot of the tower. (Use √3 = 1.732)", "marks": 5, "answer": "Figure with correct labelling. (1 mark)\\nLet height = h, distance of nearer point from foot = x.\\nIn the nearer triangle: tan 60° = h/x ⇒ h = √3 x. (1 mark)\\nIn the farther triangle: tan 30° = h/(x + 40) ⇒ x + 40 = √3 h = √3(√3 x) = 3x. (1 mark)\\n⇒ 2x = 40 ⇒ x = 20 m. (1 mark)\\nh = 20√3 = 20 × 1.732 = 34.64 m. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Areas Related to Circles", "q": "A garden sprinkler fixed at a point waters a region in the shape of a sector of a circle of radius 21 m. The sprinkler rotates through an angle of 60°. The gardener wants to know how much ground is watered and how much fencing would be needed around the watered region. (Take π = 22/7)\\n(i) Find the area of the circle of radius 21 m. (1)\\n(ii) Find the area of the region watered (sector). (1)\\n(iii) Find the length of the arc of the sector. (1)\\n(iv) Find the perimeter of the watered region. (1)", "marks": 4, "answer": "(i) πr² = (22/7) × 21 × 21 = 1386 m².\\n(ii) Sector area = (60/360) × 1386 = 231 m².\\n(iii) Arc length = (60/360) × 2 × (22/7) × 21 = (1/6) × 132 = 22 m.\\n(iv) Perimeter = arc + 2r = 22 + 42 = 64 m."}]}, "Science": {"book": "Science", "questions": [{"n": 1, "type": "MCQ", "topic": "Chemical Reactions and Equations", "q": "Which of the following is a displacement reaction?\\n(a) CaCO₃ → CaO + CO₂ (b) Fe + CuSO₄ → FeSO₄ + Cu (c) 2H₂ + O₂ → 2H₂O (d) NaOH + HCl → NaCl + H₂O", "marks": 1, "answer": "(b) Fe + CuSO₄ → FeSO₄ + Cu — the more reactive iron displaces copper."}, {"n": 2, "type": "Fill in the blank", "topic": "Acids, Bases and Salts", "q": "The pH of pure water at 25 °C is ________.", "marks": 1, "answer": "7 (neutral)."}, {"n": 3, "type": "MCQ", "topic": "Life Processes", "q": "The structural and functional unit of the kidney is:\\n(a) Neuron (b) Nephron (c) Alveolus (d) Villus", "marks": 1, "answer": "(b) Nephron."}, {"n": 4, "type": "True/False", "topic": "Light — Reflection and Refraction", "q": "A concave lens always forms a virtual, erect and diminished image of a real object.", "marks": 1, "answer": "True — for any position of a real object."}, {"n": 5, "type": "Assertion-Reason", "topic": "Chemical Reactions and Equations", "q": "Assertion (A): Magnesium ribbon is cleaned with sandpaper before burning it in air.\\nReason (R): Cleaning removes the protective layer of magnesium oxide formed on its surface.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Electricity", "q": "Two resistors of 4 Ω and 6 Ω are connected (i) in series and (ii) in parallel. Find the equivalent resistance in each case. What current flows in the series combination if it is connected to a 10 V battery?", "marks": 2, "answer": "(i) Series: R = 4 + 6 = 10 Ω. (½ mark)\\n(ii) Parallel: 1/R = 1/4 + 1/6 = 5/12 ⇒ R = 12/5 = 2.4 Ω. (1 mark)\\nCurrent in series: I = V/R = 10/10 = 1 A. (½ mark)"}, {"n": 7, "type": "Short answer", "topic": "Life Processes — Respiration", "q": "Give two differences between aerobic and anaerobic respiration.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Aerobic occurs in the presence of oxygen; anaerobic in its absence.\\n2. Aerobic: glucose is completely broken into CO₂ and water; anaerobic: incomplete breakdown into ethanol + CO₂ (yeast) or lactic acid (muscles).\\n3. Aerobic releases much more energy than anaerobic.\\n4. Aerobic is completed in mitochondria (after glycolysis in cytoplasm); anaerobic occurs in the cytoplasm."}, {"n": 8, "type": "Short answer", "topic": "Heredity", "q": "A pure tall pea plant (TT) is crossed with a pure dwarf pea plant (tt). Write the genotype of F1 plants and the phenotypic and genotypic ratios in the F2 generation.", "marks": 2, "answer": "F1: all Tt — all tall. (½ mark)\\nF2 (Tt × Tt): TT, Tt, Tt, tt. (½ mark)\\nPhenotypic ratio: 3 tall : 1 dwarf. (½ mark)\\nGenotypic ratio: 1 TT : 2 Tt : 1 tt. (½ mark)"}, {"n": 9, "type": "Long answer", "topic": "Light — Reflection and Refraction", "q": "An object 10 cm tall is placed 30 cm in front of a convex lens of focal length 15 cm. Find (i) the position of the image, (ii) its magnification and height, (iii) the nature of the image, and (iv) the power of the lens. Draw a ray diagram.", "marks": 5, "answer": "u = −30 cm, f = +15 cm, h = 10 cm.\\n(i) 1/v − 1/u = 1/f ⇒ 1/v = 1/15 + 1/(−30) = 2/30 − 1/30 = 1/30 ⇒ v = +30 cm (on the other side of the lens). (1½ marks)\\n(ii) m = v/u = 30/(−30) = −1; h′ = m × h = −10 cm. (1 mark)\\n(iii) Real, inverted, same size (object at 2F₁, image at 2F₂). (½ mark)\\n(iv) P = 1/f (in m) = 1/0.15 = +6.67 D. (1 mark)\\nRay diagram with object at 2F₁ and image at 2F₂. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Our Environment", "q": "In a grassland ecosystem the food chain is: Grass → Deer → Lion. The grass traps 10,000 J of energy from sunlight. At each step only a part of the energy is passed on to the next level; the rest is lost mainly as heat and used in life processes.\\n(i) State the 10 percent law. (1)\\n(ii) How much energy will be available to the deer and to the lion? (1)\\n(iii) Identify the producer and the top consumer here. (1)\\n(iv) Why do food chains generally have only 3–4 trophic levels? (1)", "marks": 4, "answer": "(i) Only about 10% of the energy at one trophic level is transferred to the next level.\\n(ii) Deer: 10% of 10,000 = 1,000 J; Lion: 10% of 1,000 = 100 J.\\n(iii) Producer: grass; top consumer: lion (a secondary consumer in this chain).\\n(iv) Energy decreases greatly at each level, so too little energy remains to support further levels."}]}, "Social Science — History": {"book": "India and the Contemporary World II", "questions": [{"n": 1, "type": "MCQ", "topic": "The Rise of Nationalism in Europe", "q": "Who is considered the architect of the unification of Germany?\\n(a) Giuseppe Mazzini (b) Count Cavour (c) Otto von Bismarck (d) Napoleon Bonaparte", "marks": 1, "answer": "(c) Otto von Bismarck, the Prussian chief minister."}, {"n": 2, "type": "Fill in the blank", "topic": "Nationalism in India", "q": "The Rowlatt Act was passed by the Imperial Legislative Council in the year ________.", "marks": 1, "answer": "1919."}, {"n": 3, "type": "MCQ", "topic": "Nationalism in India", "q": "Gandhiji's Salt March in 1930 went from Sabarmati Ashram to:\\n(a) Champaran (b) Dandi (c) Kheda (d) Bardoli", "marks": 1, "answer": "(b) Dandi."}, {"n": 4, "type": "True/False", "topic": "Print Culture and the Modern World", "q": "The first book printed by Johann Gutenberg with his printing press was the Bible.", "marks": 1, "answer": "True — about 180 copies were printed in the 1450s."}, {"n": 5, "type": "Assertion-Reason", "topic": "Nationalism in India", "q": "Assertion (A): Gandhiji called off the Non-Cooperation Movement in February 1922.\\nReason (R): The movement was turning violent, as seen at Chauri Chaura.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "The Rise of Nationalism in Europe", "q": "What was the Treaty of Vienna (1815)? State any two of its provisions.", "marks": 2, "answer": "It was signed by the European powers (Britain, Russia, Prussia, Austria) after Napoleon's defeat to undo his changes and restore conservative regimes. (1 mark)\\nAny two provisions (½ each): the Bourbon dynasty was restored in France; France lost territories it had annexed; states were set up on France's borders (e.g. Netherlands with Belgium); Prussia got territories on its western frontier; Austria got control of northern Italy; the German Confederation of 39 states was left intact."}, {"n": 7, "type": "Short answer", "topic": "The Making of a Global World", "q": "How did the rinderpest epidemic of the 1890s affect the people of Africa?", "marks": 2, "answer": "Rinderpest, a cattle disease brought by infected cattle from British Asia, killed about 90% of African cattle. (1 mark)\\nAfricans lost their livelihood and were forced to work for wages on European plantations and mines; colonial powers used it to strengthen their control over Africa. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "The Age of Industrialisation", "q": "Why did some industrialists in 19th-century Britain prefer hand labour over machines?", "marks": 2, "answer": "Any two (1 mark each):\\n1. Labour was plentiful and cheap as poor peasants migrated to cities.\\n2. Machines were costly, needed large investment and repairs were expensive.\\n3. Many industries had seasonal demand, so hand labour could be hired only for the season.\\n4. Upper classes preferred hand-made goods symbolising refinement and class; intricate designs needed human skill."}, {"n": 9, "type": "Long answer", "topic": "Nationalism in India", "q": "Describe how different social groups participated in the Civil Disobedience Movement and what they expected from it.", "marks": 5, "answer": "One mark each for any five:\\n1. Rich peasants (Patidars of Gujarat, Jats of UP) — hit by falling prices; wanted reduction of revenue demand.\\n2. Poor peasants — wanted unpaid rent to be remitted; joined radical movements, sometimes led by Socialists.\\n3. Business classes (FICCI, G.D. Birla, Purshottamdas Thakurdas) — wanted protection against foreign imports and a rupee-sterling ratio that discouraged imports.\\n4. Industrial workers (e.g. Nagpur) — boycott of foreign goods; demands for better wages and working conditions; limited participation.\\n5. Women — participated in large numbers in protest marches, salt-making and picketing.\\n6. Limited participation of Dalits (demanded separate electorates; Poona Pact 1932) and many Muslims (alienation after the Khilafat movement declined)."}, {"n": 10, "type": "Case-based", "topic": "Print Culture and the Modern World", "q": "Read the source and answer:\\nIn 1517 the religious reformer Martin Luther wrote Ninety-Five Theses criticising many practices and rituals of the Roman Catholic Church. A printed copy was posted on a church door in Wittenberg. Luther's writings were immediately reproduced in vast numbers and read widely. Deeply grateful to print, Luther said, 'Printing is the ultimate gift of God and the greatest one.'\\n(i) What were the Ninety-Five Theses? (1)\\n(ii) How did print help Luther's ideas spread? (1)\\n(iii) Which major religious movement began as a result? (1)\\n(iv) Why did the Roman Catholic Church try to control print? (1)", "marks": 4, "answer": "(i) A set of 95 propositions written by Martin Luther criticising the practices and rituals of the Roman Catholic Church.\\n(ii) Printing allowed his writings to be reproduced quickly in large numbers and read widely by ordinary people.\\n(iii) The Protestant Reformation.\\n(iv) It feared the spread of dissenting/heretical ideas that questioned its authority, so it imposed controls and kept an Index of Prohibited Books (from 1558)."}]}, "Social Science — Geography": {"book": "Contemporary India II", "questions": [{"n": 1, "type": "MCQ", "topic": "Resources and Development", "q": "Black soil is best suited for the cultivation of:\\n(a) Tea (b) Cotton (c) Rice (d) Jute", "marks": 1, "answer": "(b) Cotton — black soil is also called black cotton soil (regur)."}, {"n": 2, "type": "Fill in the blank", "topic": "Agriculture", "q": "Kharif crops are sown with the onset of the ________ monsoon.", "marks": 1, "answer": "south-west monsoon (June–July); harvested in September–October."}, {"n": 3, "type": "MCQ", "topic": "Minerals and Energy Resources", "q": "Bauxite is the ore of:\\n(a) Iron (b) Copper (c) Aluminium (d) Manganese", "marks": 1, "answer": "(c) Aluminium."}, {"n": 4, "type": "True/False", "topic": "Water Resources", "q": "The Sardar Sarovar Dam is built on the river Narmada.", "marks": 1, "answer": "True — it is in Gujarat."}, {"n": 5, "type": "Assertion-Reason", "topic": "Resources and Development", "q": "Assertion (A): Terrace farming is practised on hill slopes.\\nReason (R): Terraces check the flow of water down the slope and reduce soil erosion.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Resources and Development", "q": "Distinguish between renewable and non-renewable resources with one example of each.", "marks": 2, "answer": "Renewable resources can be renewed or reproduced by physical, chemical or mechanical processes, e.g. solar energy, wind, water, forests. (1 mark)\\nNon-renewable resources take millions of years to form and get exhausted with use, e.g. coal, petroleum, minerals. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Water Resources", "q": "Explain how rooftop rainwater harvesting is practised in the semi-arid regions of Rajasthan.", "marks": 2, "answer": "Houses traditionally had underground tanks called 'tankas' built inside the main house or courtyard, connected by pipes to the sloping rooftops. (1 mark)\\nRainwater from the roof flows into the tanka and is stored as drinking water (palar pani) for the dry months; the tanka also keeps rooms cool. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Manufacturing Industries", "q": "Why is the cotton textile industry concentrated in Maharashtra and Gujarat?", "marks": 2, "answer": "Any two (1 mark each): availability of raw cotton (black soil region); humid climate suitable for spinning; good transport and access to ports (Mumbai) for import of machinery and export; large market; availability of cheap labour and capital."}, {"n": 9, "type": "Long answer", "topic": "Minerals and Energy Resources", "q": "Distinguish between conventional and non-conventional sources of energy. Why is it necessary to conserve energy resources? Suggest two ways of doing so.", "marks": 5, "answer": "Differences (2 marks, any two):\\n• Conventional sources (coal, petroleum, natural gas, firewood, thermal/hydro electricity) have been used for long; non-conventional (solar, wind, tidal, geothermal, biogas, nuclear) are newer.\\n• Most conventional sources are exhaustible and polluting; most non-conventional are renewable and cleaner.\\nNeed for conservation (1½ marks): energy is basic for economic development; fossil fuels are limited and depleting; imports are costly; burning them causes pollution and climate change.\\nWays (1½ marks, any two): use public transport; switch off electrical devices when not in use; use energy-efficient appliances (LED); promote renewable sources like solar and wind."}, {"n": 10, "type": "Case-based", "topic": "Agriculture", "q": "Read the passage and answer:\\nRice is a kharif crop and the staple food of the majority of people in India. It requires high temperature (above 25 °C), high humidity and annual rainfall above 100 cm. In areas of less rainfall it grows with the help of irrigation. Rice is grown in the plains of north and north-eastern India, coastal areas and deltaic regions. Canal irrigation and tubewells have made it possible to grow rice in Punjab and Haryana.\\n(i) What type of crop is rice? (1)\\n(ii) State the temperature and rainfall needed for rice. (1)\\n(iii) How has rice cultivation become possible in Punjab and Haryana? (1)\\n(iv) Name two regions where rice is grown. (1)", "marks": 4, "answer": "(i) A kharif crop (and staple food crop).\\n(ii) Temperature above 25 °C and rainfall above 100 cm (with high humidity).\\n(iii) Through irrigation — a dense network of canals and tubewells.\\n(iv) Any two: plains of north and north-eastern India, coastal areas, deltaic regions."}]}, "Social Science — Political Science": {"book": "Democratic Politics II", "questions": [{"n": 1, "type": "MCQ", "topic": "Power Sharing", "q": "Which language is spoken by the majority of the population in Belgium?\\n(a) French (b) German (c) Dutch (d) English", "marks": 1, "answer": "(c) Dutch — about 59% of the population."}, {"n": 2, "type": "Fill in the blank", "topic": "Federalism", "q": "Subjects like defence, foreign affairs and banking are included in the ________ List.", "marks": 1, "answer": "Union List."}, {"n": 3, "type": "MCQ", "topic": "Political Parties", "q": "A party system in which power usually changes between two main parties is found in:\\n(a) China (b) USA (c) India (d) France", "marks": 1, "answer": "(b) USA — a two-party system (Democrats and Republicans)."}, {"n": 4, "type": "True/False", "topic": "Power Sharing", "q": "In Sri Lanka, an Act passed in 1956 recognised Sinhala as the only official language.", "marks": 1, "answer": "True — this was a majoritarian measure that alienated the Sri Lankan Tamils."}, {"n": 5, "type": "Assertion-Reason", "topic": "Federalism — Decentralisation", "q": "Assertion (A): The 1992 constitutional amendment made it mandatory to reserve at least one-third of seats in local government bodies for women.\\nReason (R): This was done to increase the representation of women in local government.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Power Sharing", "q": "Distinguish between the prudential and moral reasons for power sharing.", "marks": 2, "answer": "Prudential reason: power sharing is good because it reduces the possibility of conflict between social groups and ensures political stability. (1 mark)\\nMoral reason: power sharing is the very spirit of democracy; people affected by decisions have a right to be consulted — it has intrinsic value. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Federalism", "q": "State any two key features of federalism.", "marks": 2, "answer": "Any two (1 mark each):\\n1. There are two or more levels (tiers) of government governing the same citizens.\\n2. Each tier has its own jurisdiction specified in the constitution.\\n3. Fundamental provisions cannot be changed by one level alone; changes need consent of both.\\n4. Courts (Supreme Court) interpret the constitution and settle disputes between levels.\\n5. Sources of revenue are clearly specified for financial autonomy."}, {"n": 8, "type": "Short answer", "topic": "Gender, Religion and Caste", "q": "What is meant by a secular state? Mention one constitutional provision that makes India secular.", "marks": 2, "answer": "A secular state has no official religion and treats all religions equally, keeping religion separate from the state. (1 mark)\\nAny one provision (1 mark): no official religion for India; freedom to profess, practise and propagate any religion; prohibition of discrimination on grounds of religion; state can intervene in religious matters to ensure equality (e.g. ban untouchability)."}, {"n": 9, "type": "Long answer", "topic": "Political Parties", "q": "Describe any five functions performed by political parties in a democracy.", "marks": 5, "answer": "One mark each:\\n1. Contest elections by putting up candidates.\\n2. Put forward different policies and programmes for voters to choose from.\\n3. Play a decisive role in making laws in the legislature.\\n4. Form and run governments.\\n5. Play the role of opposition — criticise the government and voice different views.\\n6. Shape public opinion by raising issues and launching movements.\\n7. Provide people access to government machinery and welfare schemes."}, {"n": 10, "type": "Case-based", "topic": "Outcomes of Democracy", "q": "Read the passage and answer:\\nDemocracy is a better form of government because it produces an accountable, responsive and legitimate government. Citizens have the right to choose their rulers and to examine the decision-making process — this is called transparency. Democracies may be slower in taking decisions, but the decisions are more acceptable. Democracy also promotes the dignity and freedom of individuals, especially of women and disadvantaged groups.\\n(i) Name any two features of a democratic government mentioned in the passage. (1)\\n(ii) What is meant by 'transparency'? (1)\\n(iii) Why are decisions in a democracy more acceptable even if slower? (1)\\n(iv) How does democracy promote the dignity of women? (1)", "marks": 4, "answer": "(i) Any two: accountable, responsive, legitimate.\\n(ii) The right and means of citizens to examine the process of decision-making, i.e. decisions are taken following due norms and procedures that are open to scrutiny.\\n(iii) Because they are taken after deliberation, discussion and negotiation, following due procedure.\\n(iv) It recognises equal rights of women legally and morally, giving them a basis to struggle against discrimination and for equal treatment."}]}, "Social Science — Economics": {"book": "Understanding Economic Development", "questions": [{"n": 1, "type": "MCQ", "topic": "Development", "q": "Per capita income of a country is calculated as:\\n(a) Total income × Total population (b) Total income ÷ Total population (c) Total population ÷ Total income (d) Total income − Total population", "marks": 1, "answer": "(b) Total income ÷ Total population (also called average income)."}, {"n": 2, "type": "Fill in the blank", "topic": "Development", "q": "The Human Development Report, which ranks countries by HDI, is published by ________.", "marks": 1, "answer": "UNDP (United Nations Development Programme)."}, {"n": 3, "type": "MCQ", "topic": "Sectors of the Indian Economy", "q": "Which of the following is a tertiary sector activity?\\n(a) Fishing (b) Banking (c) Brick-making (d) Mining", "marks": 1, "answer": "(b) Banking — it is a service."}, {"n": 4, "type": "True/False", "topic": "Sectors of the Indian Economy", "q": "Under MGNREGA 2005, the government guarantees 100 days of employment in a year to rural households.", "marks": 1, "answer": "True — if work is not provided, an unemployment allowance is to be given."}, {"n": 5, "type": "Assertion-Reason", "topic": "Money and Credit", "q": "Assertion (A): Money acts as a medium of exchange.\\nReason (R): Money eliminates the need for double coincidence of wants.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 6, "type": "Short answer", "topic": "Money and Credit", "q": "Distinguish between formal and informal sources of credit.", "marks": 2, "answer": "Formal sources (banks, cooperatives) are supervised by the RBI, charge reasonable interest and follow rules. (1 mark)\\nInformal sources (moneylenders, traders, relatives, landlords) are not supervised by any organisation, often charge very high interest and may use unfair means to recover loans. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Sectors of the Indian Economy", "q": "Give two differences between the organised and unorganised sectors.", "marks": 2, "answer": "Any two (1 mark each):\\n1. Organised sector enterprises are registered with the government and follow its rules; unorganised units are small, scattered and largely outside government control.\\n2. Organised: regular employment and assured work; unorganised: low-paid, irregular jobs.\\n3. Organised: benefits like paid leave, PF, medical benefits, fixed working hours; unorganised: no such benefits, no job security."}, {"n": 8, "type": "Short answer", "topic": "Globalisation and the Indian Economy", "q": "Explain any two factors that have enabled globalisation.", "marks": 2, "answer": "1. Technology — rapid improvement in transport, information and communication technology (telecom, internet) has made movement of goods, services and information fast and cheap. (1 mark)\\n2. Liberalisation of foreign trade and investment policy — removal of barriers and restrictions set by governments (e.g. India in 1991), with WTO pushing for free trade. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Sectors of the Indian Economy", "q": "Why is the tertiary sector becoming increasingly important in India? Explain with five reasons.", "marks": 5, "answer": "One mark each:\\n1. Basic services (hospitals, schools, post, police, courts, transport, banks) are needed in any country and are provided by the government.\\n2. Development of the primary and secondary sectors increases demand for services like transport, trade and storage.\\n3. As income rises, people demand more services such as eating out, tourism, shopping, private hospitals and schools.\\n4. New services based on information and communication technology (IT, software, call centres) have grown rapidly.\\n5. The tertiary sector has become the largest producing sector, contributing the largest share of GDP."}, {"n": 10, "type": "Case-based", "topic": "Development", "q": "Study the data and answer:\\nMonthly incomes (in ₹) of five citizens in two countries:\\nCountry A: 10,000; 10,000; 10,000; 10,000; 10,000\\nCountry B: 500; 500; 500; 500; 48,000\\n(i) Calculate the average income of each country. (1)\\n(ii) In which country would you prefer to live, and why? (1)\\n(iii) State one limitation of using average income to compare countries. (1)\\n(iv) Name one other indicator used to measure development. (1)", "marks": 4, "answer": "(i) A: 50,000/5 = ₹10,000; B: (4 × 500 + 48,000)/5 = 50,000/5 = ₹10,000. Both averages are equal.\\n(ii) Country A, because income is equally distributed; in B one person is very rich while four are very poor.\\n(iii) Average income hides disparities (distribution of income) among people.\\n(iv) Any one: Infant Mortality Rate, literacy rate, net attendance ratio, life expectancy, Human Development Index."}]}, "English": {"book": "First Flight & Footprints without Feet", "questions": [{"n": 1, "type": "MCQ", "topic": "A Letter to God (First Flight)", "q": "In 'A Letter to God', what destroyed Lencho's crop?\\n(a) A flood (b) A hailstorm (c) Locusts (d) A drought", "marks": 1, "answer": "(b) A hailstorm."}, {"n": 2, "type": "Fill in the blank", "topic": "Nelson Mandela: Long Walk to Freedom (First Flight)", "q": "Nelson Mandela was sworn in as the first Black President of South Africa on 10 May ________.", "marks": 1, "answer": "1994."}, {"n": 3, "type": "MCQ", "topic": "Two Stories about Flying — His First Flight (First Flight)", "q": "In 'His First Flight', how did the young seagull's mother make him fly?\\n(a) She pushed him off the ledge (b) She tempted him with a piece of fish (c) She scolded him (d) She carried him on her back", "marks": 1, "answer": "(b) She tempted him with a piece of fish, which made him dive at it and then spread his wings."}, {"n": 4, "type": "True/False", "topic": "The Thief's Story (Footprints without Feet)", "q": "In 'The Thief's Story', Hari Singh returned the stolen money to Anil by quietly putting it back under the mattress.", "marks": 1, "answer": "True."}, {"n": 5, "type": "MCQ", "topic": "The Making of a Scientist (Footprints without Feet)", "q": "As a child, Richard Ebright was first interested in collecting:\\n(a) coins (b) stamps (c) butterflies (d) rocks", "marks": 1, "answer": "(c) butterflies (along with other insects); later he studied monarch butterflies."}, {"n": 6, "type": "Short answer", "topic": "A Letter to God (First Flight)", "q": "Why did Lencho think that the post office employees were 'a bunch of crooks'?", "marks": 2, "answer": "Lencho had asked God for a hundred pesos but received only seventy. (1 mark)\\nHis faith in God was so firm that he believed God could not make a mistake, so he concluded that the post office employees had taken the rest of the money. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Grammar — Reported Speech", "q": "Change into reported speech:\\n(a) She asked me, 'Where are you going?'\\n(b) The teacher said to the students, 'Do not make a noise.'", "marks": 2, "answer": "(a) She asked me where I was going. (1 mark)\\n(b) The teacher told/ordered the students not to make a noise. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "The Thief's Story (Footprints without Feet)", "q": "Why did Hari Singh decide to return to Anil after stealing his money?", "marks": 2, "answer": "Hari realised that by running away he would lose the chance to learn to read and write and become a respectable 'big man'; stolen money would only give him a short-lived pleasure. (1 mark)\\nHe was also moved by Anil's trust and kindness, and his conscience made him go back. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Writing — Letter to the Editor", "q": "Write a letter to the editor of a national daily, in about 120 words, expressing concern about the increasing use of single-use plastic in your city and suggesting measures to reduce it. You are Aman/Anita, 24, Park Street, Lucknow.", "marks": 5, "answer": "Marking points:\\nFormat (1): sender's address, date, receiver's address (The Editor, name of newspaper), subject, salutation (Sir/Madam), complimentary close (Yours truly), name.\\nContent (2): problem — plastic bags, bottles, cutlery littering streets, choking drains, harming animals, polluting soil and water; suggestions — strict enforcement of the ban, cloth/jute bags, awareness drives, fines, recycling and segregation.\\nExpression (2): formal tone, coherence, accuracy of grammar and spelling, appropriate vocabulary."}, {"n": 10, "type": "Case-based", "topic": "Reading — Unseen Passage", "q": "Read the passage and answer:\\nSleep is as important for students as food and exercise. Research shows that teenagers need eight to ten hours of sleep every night. During sleep, the brain stores what we have learnt during the day, which improves memory. However, many students stay up late using mobile phones. The blue light from screens delays sleep, leaving them tired and unable to concentrate in class. Experts suggest keeping phones away at least an hour before bedtime.\\n(i) How many hours of sleep do teenagers need? (1)\\n(ii) How does sleep improve memory? (1)\\n(iii) Why do students using phones late at night feel tired? (1)\\n(iv) What advice do experts give? (1)", "marks": 4, "answer": "(i) Eight to ten hours every night.\\n(ii) During sleep the brain stores what has been learnt during the day.\\n(iii) The blue light from screens delays sleep, so they do not get enough rest.\\n(iv) To keep phones away at least an hour before bedtime."}]}, "Hindi": {"book": "Kshitij 2 / Kritika 2 / Sparsh 2 / Sanchayan 2", "questions": [{"n": 1, "type": "MCQ", "topic": "नेताजी का चश्मा (क्षितिज 2)", "q": "'नेताजी का चश्मा' पाठ के लेखक कौन हैं?\\n(a) यशपाल (b) स्वयं प्रकाश (c) रामवृक्ष बेनीपुरी (d) प्रेमचंद", "marks": 1, "answer": "(b) स्वयं प्रकाश।"}, {"n": 2, "type": "Fill in the blank", "topic": "बालगोबिन भगत (क्षितिज 2)", "q": "'बालगोबिन भगत' पाठ के लेखक ________ हैं।", "marks": 1, "answer": "रामवृक्ष बेनीपुरी।"}, {"n": 3, "type": "MCQ", "topic": "व्याकरण — वाच्य", "q": "'मोहन द्वारा पत्र लिखा गया।' — इस वाक्य में कौन-सा वाच्य है?\\n(a) कर्तृवाच्य (b) कर्मवाच्य (c) भाववाच्य (d) इनमें से कोई नहीं", "marks": 1, "answer": "(b) कर्मवाच्य — क्रिया कर्म (पत्र) के अनुसार है।"}, {"n": 4, "type": "True/False", "topic": "व्याकरण — रचना के आधार पर वाक्य-भेद", "q": "'जो परिश्रम करता है, वह सफल होता है।' — यह मिश्र वाक्य है।", "marks": 1, "answer": "सत्य — इसमें एक प्रधान उपवाक्य (वह सफल होता है) और एक आश्रित उपवाक्य (जो परिश्रम करता है) है।"}, {"n": 5, "type": "MCQ", "topic": "व्याकरण — रस", "q": "करुण रस का स्थायी भाव है —\\n(a) रति (b) शोक (c) क्रोध (d) उत्साह", "marks": 1, "answer": "(b) शोक।"}, {"n": 6, "type": "Short answer", "topic": "नेताजी का चश्मा (क्षितिज 2)", "q": "'नेताजी का चश्मा' पाठ में कैप्टन कौन था? वह नेताजी की मूर्ति पर चश्मा क्यों लगाता था?", "marks": 2, "answer": "कैप्टन कस्बे का एक बूढ़ा, मरियल-सा, लँगड़ा चश्मेवाला था जो घूम-घूमकर चश्मे बेचता था। (1 अंक)\\nवह सच्चा देशभक्त था; बिना चश्मे की नेताजी की मूर्ति उसे अच्छी नहीं लगती थी, इसलिए वह अपने चश्मों में से एक चश्मा मूर्ति पर लगा देता था — यह उसकी देशभक्ति और नेताजी के प्रति सम्मान का प्रतीक था। (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "बड़े भाई साहब (स्पर्श 2)", "q": "'बड़े भाई साहब' पाठ में बड़े भाई साहब छोटे भाई को बार-बार क्यों डाँटते थे?", "marks": 2, "answer": "छोटा भाई पढ़ाई छोड़कर खेलकूद, गुल्ली-डंडा और पतंगबाज़ी में समय बिताता था, इसलिए बड़े भाई उसे डाँटते और उपदेश देते थे। (1 अंक)\\nबड़े होने के नाते वे स्वयं को उसका अभिभावक समझते थे और उसे अनुशासित तथा पढ़ाई में गंभीर बनाना चाहते थे, ताकि वह भटक न जाए। (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "व्याकरण — वाक्य रूपांतरण", "q": "'वह बीमार होने के कारण विद्यालय नहीं आया।' — इस सरल वाक्य को (क) संयुक्त वाक्य और (ख) मिश्र वाक्य में बदलिए।", "marks": 2, "answer": "(क) संयुक्त वाक्य: वह बीमार था, इसलिए विद्यालय नहीं आया। (1 अंक)\\n(ख) मिश्र वाक्य: क्योंकि वह बीमार था, इसलिए विद्यालय नहीं आया। / वह विद्यालय नहीं आया क्योंकि वह बीमार था। (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "लेखन — अनुच्छेद लेखन", "q": "'समय का सदुपयोग' विषय पर संकेत-बिंदुओं के आधार पर लगभग 120 शब्दों में अनुच्छेद लिखिए।\\nसंकेत-बिंदु: समय का महत्त्व • विद्यार्थी जीवन में समय का सदुपयोग • समय नष्ट करने के दुष्परिणाम", "marks": 5, "answer": "अंक-विभाजन:\\nविषय-वस्तु (3 अंक): समय अमूल्य है, बीता समय लौटकर नहीं आता; विद्यार्थी को समय-सारणी बनाकर पढ़ाई, खेल और विश्राम में संतुलन रखना चाहिए; मोबाइल व व्यर्थ कार्यों में समय नष्ट करने से असफलता और पछतावा मिलता है; महापुरुषों ने समय का सदुपयोग कर सफलता पाई — तीनों संकेत-बिंदुओं का समावेश।\\nभाषा एवं प्रस्तुति (2 अंक): शुद्ध भाषा, क्रमबद्धता, सूक्ति/उदाहरण का प्रयोग (जैसे 'काल करे सो आज कर...'), शब्द-सीमा का पालन।"}, {"n": 10, "type": "Case-based", "topic": "अपठित गद्यांश", "q": "निम्नलिखित गद्यांश पढ़कर प्रश्नों के उत्तर दीजिए —\\nपुस्तकें मनुष्य की सच्ची मित्र होती हैं। वे हमें ज्ञान देती हैं, हमारा मनोरंजन करती हैं और कठिन समय में मार्गदर्शन करती हैं। अच्छी पुस्तकें पढ़ने से हमारे विचार शुद्ध होते हैं और चरित्र का निर्माण होता है। आजकल लोग मोबाइल और टेलीविज़न में अधिक समय बिताते हैं, जिससे पढ़ने की आदत कम होती जा रही है। हमें प्रतिदिन कुछ समय अच्छी पुस्तकें पढ़ने के लिए अवश्य निकालना चाहिए।\\n(i) पुस्तकों को मनुष्य की सच्ची मित्र क्यों कहा गया है? (1)\\n(ii) अच्छी पुस्तकें पढ़ने से क्या लाभ होता है? (1)\\n(iii) पढ़ने की आदत कम होने का क्या कारण बताया गया है? (1)\\n(iv) 'मनोरंजन' शब्द का संधि-विच्छेद कीजिए। (1)", "marks": 4, "answer": "(i) क्योंकि वे ज्ञान देती हैं, मनोरंजन करती हैं और कठिन समय में मार्गदर्शन करती हैं।\\n(ii) विचार शुद्ध होते हैं और चरित्र का निर्माण होता है।\\n(iii) लोग मोबाइल और टेलीविज़न में अधिक समय बिताते हैं।\\n(iv) मनः + रंजन (विसर्ग संधि)।"}]}, "Sanskrit": {"book": "Shemushi 2", "questions": [{"n": 1, "type": "MCQ", "topic": "सन्धिः", "q": "'सदैव' इति पदस्य सन्धिविच्छेदः अस्ति —\\n(a) सदा + ऐव (b) सद + एव (c) सदा + एव (d) सदै + व", "marks": 1, "answer": "(c) सदा + एव (वृद्धिसन्धिः — आ + ए = ऐ)।"}, {"n": 2, "type": "Fill in the blank", "topic": "प्रत्ययाः", "q": "'पठितव्यम्' इति पदे पठ् धातुना सह ________ प्रत्ययः अस्ति।", "marks": 1, "answer": "तव्यत् (पठ् + तव्यत्)।"}, {"n": 3, "type": "MCQ", "topic": "समयलेखनम्", "q": "7:30 इति समयः संस्कृते कथं लिख्यते?\\n(a) पादोनसप्तवादनम् (b) सपादसप्तवादनम् (c) सार्धसप्तवादनम् (d) सप्तवादनम्", "marks": 1, "answer": "(c) सार्धसप्तवादनम्।"}, {"n": 4, "type": "True/False", "topic": "समासः", "q": "'राजपुरुषः' (राज्ञः पुरुषः) इत्यत्र तत्पुरुषसमासः अस्ति। (सत्यम् / असत्यम्)", "marks": 1, "answer": "सत्यम् — षष्ठी-तत्पुरुषसमासः।"}, {"n": 5, "type": "MCQ", "topic": "प्रत्ययाः", "q": "'गम् + क्त्वा' इति योगेन पदं भवति —\\n(a) गमित्वा (b) गत्वा (c) गन्तुम् (d) गतवान्", "marks": 1, "answer": "(b) गत्वा।"}, {"n": 6, "type": "Short answer", "topic": "वाच्यपरिवर्तनम्", "q": "वाच्यपरिवर्तनं कुरुत (कर्तृवाच्यात् कर्मवाच्ये/भाववाच्ये) —\\n(क) रामः ग्रन्थं पठति।\\n(ख) बालकः हसति।", "marks": 2, "answer": "(क) रामेण ग्रन्थः पठ्यते। (कर्मवाच्यम्) (1 अंक)\\n(ख) बालकेन हस्यते। (भाववाच्यम्) (1 अंक)"}, {"n": 7, "type": "Short answer", "topic": "प्रत्ययाः", "q": "प्रकृति-प्रत्ययविभागं कुरुत — (क) धनवान् (ख) कृत्वा", "marks": 2, "answer": "(क) धनवान् = धन + मतुप् (1 अंक)\\n(ख) कृत्वा = कृ + क्त्वा (1 अंक)"}, {"n": 8, "type": "Short answer", "topic": "अव्ययपदानि", "q": "मञ्जूषातः उचितम् अव्ययपदं चित्वा रिक्तस्थानानि पूरयत — [उच्चैः, अधुना]\\n(क) बालकाः ________ हसन्ति।\\n(ख) ________ अहं गृहं गच्छामि।", "marks": 2, "answer": "(क) बालकाः उच्चैः हसन्ति। (1 अंक)\\n(ख) अधुना अहं गृहं गच्छामि। (1 अंक)"}, {"n": 9, "type": "Long answer", "topic": "पत्रलेखनम्", "q": "मञ्जूषायाः पदानि चित्वा मित्रं प्रति लिखितं पत्रं पूरयत —\\nमञ्जूषा: [सप्रेम, कुशलिनः, परीक्षायाम्, उत्तीर्णः, प्रथमं, अभिनन्दनानि, पितृभ्यां, मित्रम्, भवतः, दिल्लीतः]\\n________(1)\\nतिथिः ...\\nप्रिय मित्र सुरेश,\\n________(2) नमस्ते।\\nअत्र सर्वे ________(3) सन्ति। भवतः पत्रं प्राप्तम्। भवान् वार्षिक-________(4) ________(5) अभवत्, कक्षायां च ________(6) स्थानं प्राप्तवान् इति ज्ञात्वा अहं प्रसन्नः अस्मि। मम हार्दिकानि ________(7)। ________(8) मम प्रणामाः। ________(9) पत्रोत्तरस्य प्रतीक्षायाम्।\\nभवतः ________(10)\\nमहेशः", "marks": 5, "answer": "प्रत्येकं शुद्धं पदम् ½ अंकः —\\n(1) दिल्लीतः (2) सप्रेम (3) कुशलिनः (4) परीक्षायाम् (5) उत्तीर्णः (6) प्रथमं (7) अभिनन्दनानि (8) पितृभ्यां (9) भवतः (10) मित्रम्"}, {"n": 10, "type": "Case-based", "topic": "अपठितगद्यांशः", "q": "अधोलिखितं गद्यांशं पठित्वा प्रश्नान् उत्तरत —\\nपर्यावरणस्य रक्षणम् अस्माकं परमं कर्तव्यम् अस्ति। अद्य नगरेषु वायुः जलं च प्रदूषिते स्तः। वाहनानां धूमेन वायुः दूषितः भवति। कारखानानां मलिनजलेन नद्यः दूषिताः भवन्ति। यदि वयं वृक्षान् रोपयामः, जलं रक्षामः, प्लास्टिकस्य प्रयोगं च न कुर्मः, तर्हि पर्यावरणं स्वच्छं भविष्यति।\\n(i) अस्माकं परमं कर्तव्यं किम्? (एकपदेन/पदद्वयेन) (1)\\n(ii) वायुः केन दूषितः भवति? (एकपदेन) (1)\\n(iii) नद्यः कथं दूषिताः भवन्ति? (पूर्णवाक्येन) (1)\\n(iv) 'भविष्यति' इति क्रियापदे कः लकारः? (1)", "marks": 4, "answer": "(i) पर्यावरणस्य रक्षणम्।\\n(ii) वाहनानां धूमेन।\\n(iii) कारखानानां मलिनजलेन नद्यः दूषिताः भवन्ति।\\n(iv) लृट्लकारः (भविष्यत्काले)।"}]}}, "11": {"Physics": {"book": "Physics Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Units and Measurement", "q": "Impulse has the same dimensions as:\\n(a) Force\\n(b) Momentum\\n(c) Energy\\n(d) Power", "marks": 1, "answer": "(b) Momentum. Impulse = F x t = change in momentum, dimensions [MLT^-1]."}, {"n": 2, "type": "Assertion-Reason", "topic": "Motion in a Plane", "q": "Assertion (A): A body moving in a circle with uniform speed is accelerated.\\nReason (R): The direction of velocity of the body changes continuously.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A. The changing direction of velocity gives a centripetal acceleration v^2/r."}, {"n": 3, "type": "Fill in the blank", "topic": "Mechanical Properties of Fluids", "q": "The SI unit of coefficient of viscosity is ________.", "marks": 1, "answer": "Pascal second (Pa s), i.e. N s m^-2 (also called poiseuille)."}, {"n": 4, "type": "MCQ", "topic": "Gravitation", "q": "The escape speed from the surface of the Earth is about:\\n(a) 7.9 km/s\\n(b) 9.8 km/s\\n(c) 11.2 km/s\\n(d) 3.0 km/s", "marks": 1, "answer": "(c) 11.2 km/s (v_e = sqrt(2gR))."}, {"n": 5, "type": "MCQ", "topic": "Oscillations", "q": "For small oscillations, the time period of a simple pendulum depends on:\\n(a) mass of the bob\\n(b) length of the pendulum\\n(c) amplitude of oscillation\\n(d) material of the bob", "marks": 1, "answer": "(b) length of the pendulum. T = 2π sqrt(l/g); it is independent of mass and (for small angles) amplitude."}, {"n": 6, "type": "Short answer", "topic": "Motion in a Straight Line", "q": "A car starts from rest and accelerates uniformly at 2 m/s^2 for 5 s. Find (i) its final velocity and (ii) the distance covered in this time.", "marks": 2, "answer": "u = 0, a = 2 m/s^2, t = 5 s.\\n(i) v = u + at = 0 + 2 x 5 = 10 m/s. (1 mark)\\n(ii) s = ut + (1/2)at^2 = 0 + (1/2)(2)(25) = 25 m. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Work, Energy and Power", "q": "A body of mass 2 kg is moving with a speed of 3 m/s. Find its kinetic energy. By what factor does the kinetic energy change if its speed is doubled?", "marks": 2, "answer": "KE = (1/2)mv^2 = (1/2)(2)(3)^2 = 9 J. (1 mark)\\nAt 6 m/s, KE = (1/2)(2)(36) = 36 J, i.e. KE becomes 4 times, since KE is proportional to v^2. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Thermodynamics", "q": "State the first law of thermodynamics. A gas absorbs 500 J of heat and does 200 J of work on the surroundings. Find the change in its internal energy.", "marks": 2, "answer": "First law: heat supplied to a system equals the increase in its internal energy plus the work done by the system, ΔQ = ΔU + ΔW. (1 mark)\\nΔU = ΔQ - ΔW = 500 - 200 = 300 J (internal energy increases by 300 J). (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Motion in a Plane", "q": "A projectile is thrown with initial speed u at an angle θ with the horizontal. Derive expressions for (i) time of flight, (ii) maximum height and (iii) horizontal range. Show that the range is maximum when θ = 45°.", "marks": 5, "answer": "Components: u_x = u cosθ (constant), u_y = u sinθ, acceleration -g vertically. (1 mark)\\n(i) Time of flight: y = 0 when u sinθ T - (1/2)gT^2 = 0, so T = 2u sinθ / g. (1 mark)\\n(ii) Max height: at top v_y = 0, so 0 = u^2 sin^2θ - 2gH, giving H = u^2 sin^2θ / 2g. (1 mark)\\n(iii) Range: R = u cosθ x T = u cosθ x 2u sinθ/g = u^2 sin2θ / g. (1 mark)\\nMaximum range: sin2θ is maximum (=1) when 2θ = 90°, i.e. θ = 45°, so R_max = u^2/g. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Laws of Motion", "q": "During a cricket match, a ball of mass 0.15 kg moving at 20 m/s towards a batsman is hit straight back with a speed of 20 m/s. The bat is in contact with the ball for 0.01 s. A fielder later catches a similar fast ball by moving his hands backwards.\\n(i) Find the magnitude of change in momentum of the ball.\\n(ii) Find the average force exerted by the bat.\\n(iii) Why does the fielder pull his hands back while catching?\\n(iv) Name the law of motion that relates force and rate of change of momentum.", "marks": 4, "answer": "(i) Δp = m(v - u) = 0.15 x (20 - (-20)) = 0.15 x 40 = 6 kg m/s. (1)\\n(ii) F = Δp/Δt = 6/0.01 = 600 N. (1)\\n(iii) Moving the hands back increases the time of contact, so the rate of change of momentum, and hence the force on the hands, is reduced. (1)\\n(iv) Newton's second law of motion, F = dp/dt. (1)"}]}, "Chemistry": {"book": "Chemistry Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Some Basic Concepts of Chemistry", "q": "The number of moles present in 4.4 g of CO2 is:\\n(a) 0.01\\n(b) 0.1\\n(c) 1\\n(d) 0.44", "marks": 1, "answer": "(b) 0.1. Molar mass of CO2 = 44 g/mol; moles = 4.4/44 = 0.1."}, {"n": 2, "type": "Fill in the blank", "topic": "Structure of Atom", "q": "The maximum number of electrons that can be accommodated in the shell with n = 3 is ________.", "marks": 1, "answer": "18 (2n^2 = 2 x 9)."}, {"n": 3, "type": "Assertion-Reason", "topic": "Classification of Elements and Periodicity in Properties", "q": "Assertion (A): Fluorine has a less negative electron gain enthalpy than chlorine.\\nReason (R): Due to its small size, the added electron in fluorine experiences strong repulsion from electrons in the compact 2p subshell.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Chemical Bonding and Molecular Structure", "q": "According to VSEPR theory, the shape of the NH3 molecule is:\\n(a) Trigonal planar\\n(b) Tetrahedral\\n(c) Trigonal pyramidal\\n(d) Linear", "marks": 1, "answer": "(c) Trigonal pyramidal (3 bond pairs + 1 lone pair, bond angle about 107°)."}, {"n": 5, "type": "MCQ", "topic": "Organic Chemistry: Some Basic Principles and Techniques", "q": "The IUPAC name of CH3-CH2-CH(CH3)-CH3 is:\\n(a) 2-Methylbutane\\n(b) 3-Methylbutane\\n(c) Pentane\\n(d) 2-Ethylpropane", "marks": 1, "answer": "(a) 2-Methylbutane (longest chain of 4 C, methyl at C-2 with lowest locant)."}, {"n": 6, "type": "Short answer", "topic": "Equilibrium", "q": "Calculate the pH of (i) 0.001 M HCl and (ii) 0.01 M NaOH solution at 298 K. (Assume complete ionisation.)", "marks": 2, "answer": "(i) [H+] = 10^-3 M, pH = -log(10^-3) = 3. (1 mark)\\n(ii) [OH-] = 10^-2 M, pOH = 2, pH = 14 - 2 = 12. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Redox Reactions", "q": "Calculate the oxidation number of (i) Cr in K2Cr2O7 and (ii) Mn in KMnO4.", "marks": 2, "answer": "(i) 2(+1) + 2x + 7(-2) = 0, so 2x = 12, x = +6. (1 mark)\\n(ii) (+1) + y + 4(-2) = 0, so y = +7. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Thermodynamics", "q": "For a reaction, ΔH = +30 kJ/mol and ΔS = +100 J/K/mol. Assuming these do not change with temperature, find the temperature above which the reaction becomes spontaneous.", "marks": 2, "answer": "ΔG = ΔH - TΔS; reaction is spontaneous when ΔG < 0. (1 mark)\\nAt equilibrium, T = ΔH/ΔS = 30000 J / 100 J/K = 300 K. So the reaction is spontaneous above 300 K. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Hydrocarbons", "q": "Explain, with equations, the addition of HBr to propene (a) in the absence of peroxide and (b) in the presence of peroxide. Give the mechanism of the reaction in case (a).", "marks": 5, "answer": "(a) Markovnikov addition: CH3-CH=CH2 + HBr -> CH3-CHBr-CH3 (2-bromopropane, major). The negative part of the reagent goes to the carbon with fewer H atoms. (1 mark)\\nMechanism (electrophilic addition): Step 1: H+ attacks the double bond forming carbocation; secondary carbocation CH3-CH(+)-CH3 is more stable than primary CH3CH2CH2(+), so it forms preferentially. (1 mark) Step 2: Br- attacks the secondary carbocation to give 2-bromopropane. (1 mark)\\n(b) Peroxide (Kharasch) effect / anti-Markovnikov addition: CH3-CH=CH2 + HBr --(peroxide)--> CH3-CH2-CH2Br (1-bromopropane). (1 mark) It proceeds by a free radical mechanism in which the more stable secondary radical is formed; the effect is observed only with HBr, not HCl or HI. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Structure of Atom", "q": "According to Bohr's model, the energy of the electron in the nth orbit of a hydrogen atom is E_n = -2.18 x 10^-18 / n^2 J. When the electron jumps from a higher to a lower orbit, energy is emitted as radiation, giving the line spectrum of hydrogen.\\n(i) Calculate the energy of the electron in n = 2.\\n(ii) In which region of the spectrum does the Balmer series lie?\\n(iii) Calculate the energy emitted when the electron falls from n = 3 to n = 2.\\n(iv) State one limitation of Bohr's model.", "marks": 4, "answer": "(i) E_2 = -2.18 x 10^-18 / 4 = -5.45 x 10^-19 J. (1)\\n(ii) Visible region. (1)\\n(iii) ΔE = 2.18 x 10^-18 (1/4 - 1/9) = 2.18 x 10^-18 x 5/36 = 3.03 x 10^-19 J. (1)\\n(iv) Any one: cannot explain spectra of multi-electron atoms; cannot explain Zeeman/Stark effect; contradicts Heisenberg's uncertainty principle and dual nature of electron. (1)"}]}, "Biology": {"book": "Biology", "questions": [{"n": 1, "type": "MCQ", "topic": "Cell: The Unit of Life", "q": "The site of protein synthesis in a cell is:\\n(a) Lysosome\\n(b) Ribosome\\n(c) Golgi apparatus\\n(d) Centriole", "marks": 1, "answer": "(b) Ribosome."}, {"n": 2, "type": "Assertion-Reason", "topic": "Cell: The Unit of Life", "q": "Assertion (A): Mitochondria and chloroplasts are called semi-autonomous organelles.\\nReason (R): They possess their own circular DNA and 70S ribosomes.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 3, "type": "Fill in the blank", "topic": "Cell Cycle and Cell Division", "q": "Crossing over between non-sister chromatids of homologous chromosomes occurs during the ________ stage of prophase I.", "marks": 1, "answer": "Pachytene."}, {"n": 4, "type": "MCQ", "topic": "Photosynthesis in Higher Plants", "q": "In C4 plants, the primary CO2 acceptor in mesophyll cells is:\\n(a) RuBP\\n(b) PEP (phosphoenolpyruvate)\\n(c) Oxaloacetic acid\\n(d) PGA", "marks": 1, "answer": "(b) PEP (phosphoenolpyruvate)."}, {"n": 5, "type": "MCQ", "topic": "Animal Kingdom", "q": "The water vascular system is a characteristic feature of phylum:\\n(a) Porifera\\n(b) Mollusca\\n(c) Echinodermata\\n(d) Annelida", "marks": 1, "answer": "(c) Echinodermata."}, {"n": 6, "type": "Short answer", "topic": "Respiration in Plants", "q": "Define Respiratory Quotient (RQ). What is its value when (i) carbohydrates and (ii) fats are used as respiratory substrates?", "marks": 2, "answer": "RQ = volume of CO2 evolved / volume of O2 consumed during respiration. (1 mark)\\n(i) Carbohydrates: RQ = 1. (ii) Fats: RQ less than 1 (e.g. tripalmitin about 0.7). (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Neural Control and Coordination", "q": "Differentiate between myelinated and non-myelinated nerve fibres (any two points).", "marks": 2, "answer": "Myelinated: axon enveloped by Schwann cells forming myelin sheath; gaps called nodes of Ranvier present; saltatory, faster conduction; found in spinal and cranial nerves.\\nNon-myelinated: Schwann cell encloses axon but no myelin sheath; no nodes of Ranvier; slower conduction; found in autonomous and somatic neural systems.\\n(Any two correct differences, 1 mark each.)"}, {"n": 8, "type": "Short answer", "topic": "Breathing and Exchange of Gases", "q": "Define tidal volume and vital capacity, giving their approximate values in a healthy adult.", "marks": 2, "answer": "Tidal volume: volume of air inspired or expired during normal respiration, about 500 mL. (1 mark)\\nVital capacity: maximum volume of air a person can breathe out after a forced inspiration = ERV + TV + IRV, about 3500-4500 mL. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Excretory Products and their Elimination", "q": "Describe the process of urine formation in the human nephron.", "marks": 5, "answer": "Urine formation involves three processes:\\n1. Glomerular filtration: blood is filtered through glomerular capillaries into Bowman's capsule across endothelium, basement membrane and podocytes (ultrafiltration); GFR about 125 mL/min, i.e. 180 L/day. (1.5 marks)\\n2. Reabsorption: about 99% of filtrate is reabsorbed. Glucose, amino acids, Na+ actively reabsorbed in PCT; water passively. Henle's loop: descending limb permeable to water, ascending limb permeable to electrolytes; DCT and collecting duct reabsorb water and Na+ (conditional). (1.5 marks)\\n3. Tubular secretion: H+, K+, ammonia secreted into filtrate, maintaining ionic and acid-base balance. (1 mark)\\nConcentration of urine by counter-current mechanism of Henle's loop and vasa recta; ADH increases water reabsorption. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Chemical Coordination and Integration", "q": "A 45-year-old man complains of frequent urination, excessive thirst and tiredness. His blood test shows a fasting glucose level much higher than normal, and glucose is also found in his urine. The doctor says one pancreatic hormone is deficient.\\n(i) Name the disorder and the deficient hormone.\\n(ii) Which cells of the pancreas secrete this hormone?\\n(iii) Name the pancreatic hormone that has the opposite effect and state its action.\\n(iv) Why does glucose appear in his urine?", "marks": 4, "answer": "(i) Diabetes mellitus; insulin. (1)\\n(ii) Beta (β) cells of the Islets of Langerhans. (1)\\n(iii) Glucagon (from α cells); it stimulates glycogenolysis and gluconeogenesis, raising blood glucose (hyperglycaemic hormone). (1)\\n(iv) Blood glucose exceeds the renal threshold, so kidneys cannot reabsorb all filtered glucose and it is lost in urine (glycosuria). (1)"}]}, "Maths": {"book": "Mathematics", "questions": [{"n": 1, "type": "MCQ", "topic": "Sets", "q": "If a set A has 3 elements, the number of subsets of A is:\\n(a) 3\\n(b) 6\\n(c) 8\\n(d) 9", "marks": 1, "answer": "(c) 8 (2^3 = 8)."}, {"n": 2, "type": "MCQ", "topic": "Complex Numbers and Quadratic Equations", "q": "The value of i^35 is:\\n(a) 1\\n(b) -1\\n(c) i\\n(d) -i", "marks": 1, "answer": "(d) -i. i^35 = (i^4)^8 x i^3 = 1 x (-i) = -i."}, {"n": 3, "type": "Fill in the blank", "topic": "Permutations and Combinations", "q": "The value of 7P2 is ________.", "marks": 1, "answer": "42 (7!/5! = 7 x 6)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Trigonometric Functions", "q": "Assertion (A): sin 75° = (√6 + √2)/4.\\nReason (R): sin(A + B) = sin A cos B + cos A sin B.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both true and R explains A: sin 75° = sin45°cos30° + cos45°sin30° = (√2/2)(√3/2) + (√2/2)(1/2) = (√6 + √2)/4."}, {"n": 5, "type": "MCQ", "topic": "Straight Lines", "q": "The slope of the line passing through the points (2, 3) and (4, 7) is:\\n(a) 1/2\\n(b) 2\\n(c) 4\\n(d) -2", "marks": 1, "answer": "(b) 2. m = (7 - 3)/(4 - 2) = 4/2 = 2."}, {"n": 6, "type": "Short answer", "topic": "Sequences and Series", "q": "Find the sum of the first 20 terms of the AP 3, 7, 11, 15, ...", "marks": 2, "answer": "a = 3, d = 4, n = 20. (1/2 mark)\\nS_n = (n/2)[2a + (n-1)d] = 10[6 + 19 x 4] = 10[6 + 76] = 10 x 82 = 820. (1.5 marks)"}, {"n": 7, "type": "Short answer", "topic": "Limits and Derivatives", "q": "Find the derivative of f(x) = x^2 using the first principle.", "marks": 2, "answer": "f'(x) = lim(h->0) [f(x+h) - f(x)]/h = lim(h->0) [(x+h)^2 - x^2]/h (1/2 mark)\\n= lim(h->0) [2xh + h^2]/h = lim(h->0) (2x + h) (1 mark)\\n= 2x. (1/2 mark)"}, {"n": 8, "type": "Short answer", "topic": "Probability", "q": "Two fair dice are thrown together. Find the probability that (i) the sum of numbers is 7, (ii) the sum is greater than 10.", "marks": 2, "answer": "Total outcomes = 36.\\n(i) Sum 7: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6 outcomes; P = 6/36 = 1/6. (1 mark)\\n(ii) Sum > 10: (5,6),(6,5),(6,6) = 3 outcomes; P = 3/36 = 1/12. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Binomial Theorem", "q": "(a) Expand (2x - 3)^4 using the binomial theorem.\\n(b) Find the middle term in the expansion of (x/3 + 9y)^10.", "marks": 5, "answer": "(a) (2x - 3)^4 = 4C0(2x)^4 - 4C1(2x)^3(3) + 4C2(2x)^2(3)^2 - 4C3(2x)(3)^3 + 4C4(3)^4 (1 mark)\\n= 16x^4 - 96x^3 + 216x^2 - 216x + 81. (1 mark)\\n(b) n = 10 (even), so there are 11 terms and the middle term is the 6th term, T6 = T(5+1). (1 mark)\\nT6 = 10C5 (x/3)^5 (9y)^5 = 252 x (x^5/243) x 59049 y^5 (1 mark)\\n= 252 x 243 x^5 y^5 = 61236 x^5 y^5. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Conic Sections", "q": "The cross-section of a satellite dish is a parabola. With the vertex at the origin and the axis along the x-axis, its equation is y^2 = 16x. The receiver is placed at the focus so that all incoming signals parallel to the axis are reflected to it.\\n(i) Find the coordinates of the focus where the receiver should be placed.\\n(ii) Find the equation of the directrix.\\n(iii) Find the length of the latus rectum.\\n(iv) Find the equation of the parabola with vertex at origin and focus (0, 3).", "marks": 4, "answer": "Comparing y^2 = 16x with y^2 = 4ax, a = 4.\\n(i) Focus (4, 0). (1)\\n(ii) Directrix x = -4. (1)\\n(iii) Latus rectum = 4a = 16 units. (1)\\n(iv) Focus on positive y-axis with a = 3: x^2 = 4ay = 12y. (1)"}]}, "Accountancy": {"book": "Financial Accounting Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Theory Base of Accounting", "q": "The assumption that a business will continue to operate for an indefinitely long period is called:\\n(a) Money measurement concept\\n(b) Going concern concept\\n(c) Accounting period concept\\n(d) Matching concept", "marks": 1, "answer": "(b) Going concern concept."}, {"n": 2, "type": "Fill in the blank", "topic": "Trial Balance and Rectification of Errors", "q": "A trial balance is prepared to check the ________ accuracy of the ledger accounts.", "marks": 1, "answer": "Arithmetical."}, {"n": 3, "type": "Assertion-Reason", "topic": "Introduction to Accounting", "q": "Assertion (A): Drawings reduce the owner's capital.\\nReason (R): Drawings are the amounts of cash or goods withdrawn by the owner for personal use.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Depreciation, Provisions and Reserves", "q": "Under the Written Down Value method, the amount of depreciation:\\n(a) remains the same every year\\n(b) decreases every year\\n(c) increases every year\\n(d) is zero in the last year", "marks": 1, "answer": "(b) decreases every year, because a fixed rate is applied to the reducing book value."}, {"n": 5, "type": "MCQ", "topic": "Bank Reconciliation Statement", "q": "While preparing a BRS starting with the debit balance as per Cash Book, cheques deposited into the bank but not yet collected are:\\n(a) added\\n(b) deducted\\n(c) ignored\\n(d) shown separately as a note", "marks": 1, "answer": "(b) deducted, because the Pass Book balance is lower until the cheques are credited."}, {"n": 6, "type": "Short answer", "topic": "Recording of Transactions I", "q": "Pass journal entries: (i) Started business with cash ₹1,00,000. (ii) Purchased goods from Ram on credit ₹20,000.", "marks": 2, "answer": "(i) Cash A/c Dr. 1,00,000\\n      To Capital A/c 1,00,000\\n(Being business started with cash) (1 mark)\\n(ii) Purchases A/c Dr. 20,000\\n      To Ram 20,000\\n(Being goods purchased on credit) (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Depreciation, Provisions and Reserves", "q": "A machine was bought for ₹1,00,000 and ₹10,000 was spent on its installation. Its useful life is 5 years with an estimated scrap value of ₹10,000. Calculate annual depreciation and the rate of depreciation under the Straight Line Method.", "marks": 2, "answer": "Cost = 1,00,000 + 10,000 = ₹1,10,000.\\nAnnual depreciation = (1,10,000 - 10,000)/5 = ₹20,000. (1 mark)\\nRate = 20,000/1,10,000 x 100 = 18.18% p.a. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Recording of Transactions I", "q": "Show the accounting equation for: (i) Rahul started business with cash ₹60,000. (ii) Bought goods on credit ₹15,000.", "marks": 2, "answer": "(i) Assets (Cash 60,000) = Liabilities 0 + Capital 60,000. (1 mark)\\n(ii) Assets (Cash 60,000 + Stock 15,000 = 75,000) = Liabilities (Creditors 15,000) + Capital 60,000; 75,000 = 75,000. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Recording of Transactions I", "q": "Journalise the following transactions of M/s Rohan Traders:\\n1. Sold goods to Kavi on credit ₹15,000.\\n2. Paid rent ₹4,000 in cash.\\n3. Received ₹14,800 from Kavi in full settlement of his account.\\n4. Purchased furniture by cheque ₹12,000.\\n5. Goods costing ₹2,000 withdrawn by the proprietor for personal use.", "marks": 5, "answer": "1. Kavi Dr. 15,000 / To Sales A/c 15,000 (Goods sold on credit) (1)\\n2. Rent A/c Dr. 4,000 / To Cash A/c 4,000 (Rent paid) (1)\\n3. Cash A/c Dr. 14,800; Discount Allowed A/c Dr. 200 / To Kavi 15,000 (Cash received in full settlement) (1)\\n4. Furniture A/c Dr. 12,000 / To Bank A/c 12,000 (Furniture purchased by cheque) (1)\\n5. Drawings A/c Dr. 2,000 / To Purchases A/c 2,000 (Goods withdrawn for personal use) (1)"}, {"n": 10, "type": "Case-based", "topic": "Financial Statements I", "q": "From the books of Meena Stores for the year ended 31 March 2026: Opening stock ₹20,000; Purchases ₹80,000; Sales ₹1,50,000; Return inwards ₹5,000; Wages ₹10,000; Carriage inwards ₹2,000; Closing stock ₹25,000.\\n(i) Calculate net sales.\\n(ii) Calculate cost of goods sold.\\n(iii) Calculate gross profit.\\n(iv) Where is closing stock shown in the Balance Sheet?", "marks": 4, "answer": "(i) Net sales = 1,50,000 - 5,000 = ₹1,45,000. (1)\\n(ii) COGS = 20,000 + 80,000 + 10,000 + 2,000 - 25,000 = ₹87,000. (1)\\n(iii) Gross profit = 1,45,000 - 87,000 = ₹58,000. (1)\\n(iv) On the assets side under current assets. (1)"}]}, "Business Studies": {"book": "Business Studies", "questions": [{"n": 1, "type": "MCQ", "topic": "Forms of Business Organisation", "q": "The liability of a sole proprietor is:\\n(a) limited to capital invested\\n(b) unlimited\\n(c) limited to guarantee\\n(d) shared with the government", "marks": 1, "answer": "(b) unlimited; personal assets can be used to pay business debts."}, {"n": 2, "type": "Fill in the blank", "topic": "Forms of Business Organisation", "q": "The minimum number of members required to form a private company is ________.", "marks": 1, "answer": "Two (2)."}, {"n": 3, "type": "Assertion-Reason", "topic": "Private, Public and Global Enterprises", "q": "Assertion (A): In a government company, at least 51% of the paid-up capital is held by the government.\\nReason (R): A government company is registered under the Companies Act.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(b) Both A and R are true but R is not the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Sources of Business Finance", "q": "Which of the following is a source of long-term finance?\\n(a) Trade credit\\n(b) Commercial paper\\n(c) Equity shares\\n(d) Bank overdraft", "marks": 1, "answer": "(c) Equity shares."}, {"n": 5, "type": "MCQ", "topic": "Internal Trade", "q": "A large retail establishment that offers a wide variety of products, grouped into well-defined sections, under one roof is called a:\\n(a) Chain store\\n(b) Department store\\n(c) Itinerant retailer\\n(d) Street stall", "marks": 1, "answer": "(b) Department store."}, {"n": 6, "type": "Short answer", "topic": "Sources of Business Finance", "q": "Differentiate between equity shares and debentures on any two bases.", "marks": 2, "answer": "Status: equity shareholders are owners; debenture holders are creditors.\\nReturn: dividend on shares is paid only if profits exist and varies; interest on debentures is fixed and payable even in loss.\\nVoting rights: shareholders have voting rights; debenture holders do not.\\nSecurity/repayment: debentures are usually secured and repaid on maturity; equity capital is not refunded during company's life.\\n(Any two, 1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Emerging Modes of Business", "q": "State any two benefits of e-business.", "marks": 2, "answer": "Any two: ease of formation and lower investment; convenience (24x7 availability); speed of transactions; global reach; movement towards a less-paper society; lower cost of operations. (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Forms of Business Organisation", "q": "What is a Joint Hindu Family business? State any two of its features.", "marks": 2, "answer": "It is a business owned and carried on by members of a Hindu Undivided Family, governed by Hindu Law; membership is by birth. (1 mark)\\nFeatures (any two, 1/2 each): the eldest member (karta) manages the business; liability of karta is unlimited while that of co-parceners is limited to their share; continuity is not affected by death of karta; membership by birth; formation not by agreement."}, {"n": 9, "type": "Long answer", "topic": "Social Responsibility of Business and Business Ethics", "q": "Explain the social responsibility of business towards different interest groups.", "marks": 5, "answer": "(1 mark each)\\n1. Shareholders/owners: fair and regular return on investment, safety of capital, accurate information.\\n2. Workers: fair wages, safe working conditions, respect for their rights, opportunities for participation.\\n3. Consumers: quality goods at reasonable prices, no adulteration or misleading advertising, redressal of complaints.\\n4. Government and community: obeying laws, paying taxes honestly, protecting the environment, being a good citizen.\\n5. Suppliers/creditors: fair terms of trade, timely payment of dues."}, {"n": 10, "type": "Case-based", "topic": "International Business", "q": "Arjun Textiles, a garment firm in Tiruppur, received an order from a US importer for 10,000 shirts. Before shipping, the firm obtained an Importer-Exporter Code, asked the buyer to send a letter of credit, and got a document from the chamber of commerce certifying that the goods were produced in India.\\n(i) Which mode of entry into international business is being used?\\n(ii) What is a letter of credit?\\n(iii) Name the document certifying the country of production.\\n(iv) From which authority is the IEC number obtained?", "marks": 4, "answer": "(i) Exporting (direct export). (1)\\n(ii) A guarantee issued by the importer's bank that it will honour payment up to a certain amount to the exporter on presentation of required documents. (1)\\n(iii) Certificate of origin. (1)\\n(iv) Directorate General of Foreign Trade (DGFT). (1)"}]}, "Economics": {"book": "Statistics for Economics & Introductory Microeconomics", "questions": [{"n": 1, "type": "MCQ", "topic": "Measures of Central Tendency", "q": "The median of the values 3, 9, 7, 11, 5 is:\\n(a) 5\\n(b) 7\\n(c) 9\\n(d) 11", "marks": 1, "answer": "(b) 7. Arranged: 3, 5, 7, 9, 11; middle (3rd) value = 7."}, {"n": 2, "type": "Fill in the blank", "topic": "Theory of Consumer Behaviour", "q": "When marginal utility is zero, total utility is ________.", "marks": 1, "answer": "Maximum."}, {"n": 3, "type": "Assertion-Reason", "topic": "The Theory of the Firm under Perfect Competition", "q": "Assertion (A): A firm under perfect competition is a price taker.\\nReason (R): There are a large number of firms selling a homogeneous product.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Correlation", "q": "The value of Karl Pearson's coefficient of correlation lies between:\\n(a) 0 and 1\\n(b) -1 and +1\\n(c) -∞ and +∞\\n(d) 0 and 100", "marks": 1, "answer": "(b) -1 and +1."}, {"n": 5, "type": "MCQ", "topic": "Introduction (Microeconomics)", "q": "The slope of the production possibility curve is called:\\n(a) Marginal rate of substitution\\n(b) Marginal rate of transformation\\n(c) Marginal utility\\n(d) Marginal product", "marks": 1, "answer": "(b) Marginal rate of transformation."}, {"n": 6, "type": "Short answer", "topic": "Measures of Central Tendency", "q": "Calculate the arithmetic mean from the following data using the direct method:\\nMarks: 10, 20, 30\\nNo. of students: 2, 3, 5", "marks": 2, "answer": "Σfx = 10x2 + 20x3 + 30x5 = 20 + 60 + 150 = 230; Σf = 10. (1 mark)\\nMean = Σfx/Σf = 230/10 = 23 marks. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Production and Costs", "q": "A firm's Total Fixed Cost is ₹100. Its Total Variable Cost at output 1, 2 and 3 units is ₹40, ₹70 and ₹120. Find TC, AC and MC at 3 units.", "marks": 2, "answer": "TC at 3 = TFC + TVC = 100 + 120 = ₹220. (1/2 mark)\\nAC = TC/Q = 220/3 = ₹73.33. (1/2 mark)\\nMC at 3 = TVC3 - TVC2 = 120 - 70 = ₹50 (equivalently TC3 - TC2 = 220 - 170). (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Theory of Consumer Behaviour", "q": "When the price of a good falls from ₹10 to ₹8, its quantity demanded rises from 40 units to 50 units. Calculate price elasticity of demand using the percentage method and comment on it.", "marks": 2, "answer": "% change in quantity = (10/40) x 100 = 25%; % change in price = (-2/10) x 100 = -20%. (1 mark)\\ned = 25 / (-20) = -1.25, i.e. |ed| = 1.25 > 1, so demand is elastic. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Production and Costs", "q": "Explain the law of variable proportions with the help of a schedule and a diagram showing TP and MP curves.", "marks": 5, "answer": "Statement: when more units of a variable factor are combined with fixed factors, MP of the variable factor initially rises, then falls, and eventually becomes negative. (1 mark)\\nSchedule (e.g. labour 1-6, TP 10, 24, 36, 44, 48, 46; MP 10, 14, 12, 8, 4, -2). (1 mark)\\nPhase I: TP increases at increasing rate, MP rises (better utilisation of fixed factor). Phase II: TP increases at diminishing rate, MP falls but positive; TP max when MP = 0. Phase III: TP falls, MP negative (overcrowding of fixed factor). (2 marks)\\nCorrectly labelled diagram of TP and MP curves with three phases. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Market Equilibrium", "q": "In a local vegetable market, demand and supply of tomatoes are given by Qd = 200 - 10p and Qs = 50 + 15p (p in ₹/kg, Q in kg).\\n(i) Find the equilibrium price.\\n(ii) Find the equilibrium quantity.\\n(iii) If the government fixes the price at ₹4/kg, what is the excess demand?\\n(iv) State one likely consequence of such a price ceiling.", "marks": 4, "answer": "(i) 200 - 10p = 50 + 15p, so 25p = 150, p = ₹6/kg. (1)\\n(ii) Q = 200 - 60 = 140 kg (check: 50 + 90 = 140). (1)\\n(iii) At p = 4: Qd = 160, Qs = 110; excess demand = 50 kg. (1)\\n(iv) Shortage leading to long queues, rationing or black-marketing. (1)"}]}, "History": {"book": "Themes in World History", "questions": [{"n": 1, "type": "MCQ", "topic": "Writing and City Life", "q": "The earliest Mesopotamian cuneiform script was written on:\\n(a) Papyrus\\n(b) Clay tablets\\n(c) Palm leaves\\n(d) Silk", "marks": 1, "answer": "(b) Clay tablets."}, {"n": 2, "type": "Fill in the blank", "topic": "Nomadic Empires", "q": "In 1206, Temujin was proclaimed ________, the 'Oceanic Khan' or universal ruler of the Mongols.", "marks": 1, "answer": "Genghis Khan."}, {"n": 3, "type": "Assertion-Reason", "topic": "Changing Cultural Traditions", "q": "Assertion (A): The Renaissance in Italy saw a revival of classical Greek and Roman learning.\\nReason (R): Humanist scholars studied and translated ancient texts.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "The Three Orders", "q": "In medieval French society, the 'first order' consisted of the:\\n(a) Nobility\\n(b) Peasants\\n(c) Clergy\\n(d) Merchants", "marks": 1, "answer": "(c) Clergy."}, {"n": 5, "type": "MCQ", "topic": "Paths to Modernisation", "q": "The Meiji Restoration in Japan took place in:\\n(a) 1853\\n(b) 1868\\n(c) 1894\\n(d) 1911", "marks": 1, "answer": "(b) 1868."}, {"n": 6, "type": "Short answer", "topic": "Writing and City Life", "q": "Why did writing develop in Mesopotamia? Give two reasons.", "marks": 2, "answer": "Any two: to keep records of transactions in a complex urban economy; to record goods and quantities received and distributed by temples; for trade with distant regions; to write lists, laws and dictionaries. (1 mark each)"}, {"n": 7, "type": "Short answer", "topic": "Nomadic Empires", "q": "What was the 'yasa'? How did it help the Mongols?", "marks": 2, "answer": "Yasa was the code of law/customary rules attributed to Genghis Khan (meaning law, decree or order). (1 mark)\\nIt gave the Mongols a common identity, confidence and discipline, and helped them govern a large, diverse empire and assert their authority over sedentary subjects. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Displacing Indigenous Peoples", "q": "State two ways in which European settlers displaced the native peoples of North America.", "marks": 2, "answer": "Any two: native people were made to sign treaties/sell land for little money and pushed westward; land was taken for farming, mining and railways; forced removal (e.g. Indian Removal Act 1830, Trail of Tears); diseases and wars reduced their numbers. (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "An Empire Across Three Continents", "q": "Describe the main features of the economy of the Roman Empire.", "marks": 5, "answer": "(1 mark each, any five)\\n1. Rich economic infrastructure of ports, mines, quarries, brickyards and olive oil factories.\\n2. Large-scale trade in wine, olive oil and grain carried in amphorae; e.g. Spanish olive oil (Dressel 20).\\n3. Fertile regions like Campania, Sicily, Egypt and Byzacium were highly productive.\\n4. Advanced techniques: water-mills, water-powered mining, screw presses.\\n5. Well-developed monetary system and banking; gold solidus later provided stable currency.\\n6. Use of both slave labour and free wage labour; urban centres with markets."}, {"n": 10, "type": "Case-based", "topic": "The Three Orders", "q": "Read the passage and answer: 'Feudalism in France from the ninth century rested on the relationship between lords and peasants. Peasants cultivated their own land and also the lord's. The Church received a tenth of the peasants' produce. Serfs could not leave the manor, used the lord's mill and oven, and paid fees. From the fourteenth century, famines, the Black Death and peasant revolts weakened this system.'\\n(i) Who formed the second order?\\n(ii) What was the 'tithe'?\\n(iii) State two obligations of serfs.\\n(iv) Mention one factor that weakened feudalism.", "marks": 4, "answer": "(i) The nobility. (1)\\n(ii) A tax of one-tenth of produce paid by peasants to the Church. (1)\\n(iii) Any two: work on the lord's land; could not leave the estate without permission; use and pay for the lord's mill, oven and wine press; pay fees and give gifts. (1)\\n(iv) Any one: Black Death/plague; famines; peasant revolts; rise of towns and money economy. (1)"}]}, "Geography": {"book": "Fundamentals of Physical Geography & India: Physical Environment", "questions": [{"n": 1, "type": "MCQ", "topic": "Interior of the Earth", "q": "The discontinuity between the crust and the mantle is called:\\n(a) Gutenberg discontinuity\\n(b) Mohorovicic discontinuity\\n(c) Lehmann discontinuity\\n(d) Conrad discontinuity", "marks": 1, "answer": "(b) Mohorovicic (Moho) discontinuity."}, {"n": 2, "type": "Fill in the blank", "topic": "Composition and Structure of Atmosphere", "q": "All weather phenomena occur in the ________, the lowest layer of the atmosphere.", "marks": 1, "answer": "Troposphere."}, {"n": 3, "type": "Assertion-Reason", "topic": "Solar Radiation, Heat Balance and Temperature", "q": "Assertion (A): In the troposphere, temperature decreases with increase in altitude.\\nReason (R): The atmosphere is heated mainly from below by terrestrial radiation.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A (normal lapse rate about 6.5°C per 1000 m)."}, {"n": 4, "type": "MCQ", "topic": "Drainage System (India)", "q": "Which of the following peninsular rivers flows westwards through a rift valley and forms an estuary?\\n(a) Godavari\\n(b) Krishna\\n(c) Narmada\\n(d) Mahanadi", "marks": 1, "answer": "(c) Narmada."}, {"n": 5, "type": "MCQ", "topic": "Atmospheric Circulation and Weather Systems", "q": "The Coriolis force is:\\n(a) maximum at the equator\\n(b) maximum at the poles\\n(c) equal everywhere\\n(d) maximum at 30° latitude", "marks": 1, "answer": "(b) maximum at the poles (zero at the equator)."}, {"n": 6, "type": "Short answer", "topic": "Geomorphic Processes", "q": "Distinguish between weathering and erosion.", "marks": 2, "answer": "Weathering: in-situ (on the spot) breakdown of rocks by physical, chemical and biological processes; no transportation involved. (1 mark)\\nErosion: removal and transportation of rock debris by mobile agents such as running water, wind, glaciers and waves. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Drainage System (India)", "q": "Give any two differences between Himalayan and Peninsular rivers.", "marks": 2, "answer": "Any two (1 mark each): Himalayan rivers are perennial (snow and rain fed), Peninsular mostly seasonal (rain fed); Himalayan rivers form deep gorges/V-shaped valleys in mountains, Peninsular rivers flow in broad, shallow valleys; Himalayan rivers meander and shift courses in plains, Peninsular have fixed courses; Himalayan rivers are young and actively eroding, Peninsular are old and graded."}, {"n": 8, "type": "Short answer", "topic": "Climate (India)", "q": "What is El Nino? How does it affect the Indian monsoon?", "marks": 2, "answer": "El Nino is a warm ocean current that appears off the coast of Peru in the eastern Pacific, replacing the cold Peruvian current, at irregular intervals of about three to seven years. (1 mark)\\nIt is associated with weakening of the Indian monsoon, often leading to deficient rainfall and droughts in India. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Distribution of Oceans and Continents", "q": "What are the three types of plate boundaries? Explain each with an example.", "marks": 5, "answer": "1. Divergent boundaries: plates move apart and new crust is created (spreading sites), e.g. Mid-Atlantic Ridge. (1.5 marks)\\n2. Convergent boundaries: plates move towards each other and crust is destroyed as one plate subducts, e.g. Indian plate and Eurasian plate forming the Himalayas; Pacific ocean trenches. Can be ocean-ocean, ocean-continent or continent-continent. (2 marks)\\n3. Transform boundaries: plates slide past each other horizontally; crust neither created nor destroyed, e.g. San Andreas Fault. (1.5 marks)"}, {"n": 10, "type": "Case-based", "topic": "Natural Hazards and Disasters", "q": "In May 2019, a severe cyclonic storm struck the Odisha coast with winds over 175 km/h. Timely warnings by the India Meteorological Department and evacuation of over a million people to cyclone shelters kept the loss of life low, though houses and power lines were badly damaged.\\n(i) What is a tropical cyclone?\\n(ii) Why is the east coast of India more prone to cyclones than the west coast?\\n(iii) What is the calm central region of a cyclone called?\\n(iv) Suggest two mitigation measures for cyclones.", "marks": 4, "answer": "(i) An intense low-pressure system over warm tropical seas with strong winds spiralling inward (anticlockwise in the northern hemisphere) and heavy rain. (1)\\n(ii) The Bay of Bengal has higher sea surface temperature and is enclosed, and cyclones move westwards with the prevailing winds towards the east coast. (1)\\n(iii) The eye. (1)\\n(iv) Any two: early warning systems; cyclone shelters; coastal mangrove plantations/shelter belts; cyclone-resistant buildings; evacuation plans. (1)"}]}, "Political Science": {"book": "Political Theory & Indian Constitution at Work", "questions": [{"n": 1, "type": "MCQ", "topic": "Rights in the Indian Constitution", "q": "The Right to Constitutional Remedies is provided under:\\n(a) Article 14\\n(b) Article 19\\n(c) Article 21\\n(d) Article 32", "marks": 1, "answer": "(d) Article 32."}, {"n": 2, "type": "Fill in the blank", "topic": "Local Governments", "q": "The ________ Constitutional Amendment Act, 1992 gave constitutional status to rural local government (Panchayati Raj).", "marks": 1, "answer": "73rd."}, {"n": 3, "type": "Assertion-Reason", "topic": "Election and Representation", "q": "Assertion (A): India adopted the First Past the Post (FPTP) system for Lok Sabha elections.\\nReason (R): FPTP is simple to understand, even for ordinary voters, and helps form stable governments.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Judiciary", "q": "The Chief Justice of India is appointed by the:\\n(a) Prime Minister\\n(b) President\\n(c) Parliament\\n(d) Law Minister", "marks": 1, "answer": "(b) President."}, {"n": 5, "type": "MCQ", "topic": "Freedom", "q": "The 'harm principle' as a limit on individual freedom was given by:\\n(a) Karl Marx\\n(b) J.S. Mill\\n(c) Rousseau\\n(d) John Rawls", "marks": 1, "answer": "(b) J.S. Mill."}, {"n": 6, "type": "Short answer", "topic": "Freedom", "q": "Distinguish between negative liberty and positive liberty.", "marks": 2, "answer": "Negative liberty: defines an area of non-interference in which the individual is free from external constraints, especially by the state ('freedom from'). (1 mark)\\nPositive liberty: concerned with expanding opportunities and conditions (education, health, etc.) that enable individuals to develop themselves ('freedom to'); state may act to create them. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Legislature", "q": "State two limitations on the powers of the Rajya Sabha with respect to Money Bills.", "marks": 2, "answer": "Any two: a Money Bill can be introduced only in the Lok Sabha; Rajya Sabha cannot reject or amend it, it can only make recommendations; it must return the bill within 14 days, else it is deemed passed; Lok Sabha may reject its recommendations. (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Secularism", "q": "Give two differences between Indian secularism and the Western model of secularism.", "marks": 2, "answer": "Any two: Western model insists on strict mutual exclusion of state and religion, Indian model follows principled distance allowing state intervention (e.g. banning untouchability); Western model focuses on individual freedom, Indian model protects both individual and community (minority) rights; Indian state may support religious institutions (e.g. aid to minority schools) whereas Western state does not. (1 mark each)"}, {"n": 9, "type": "Long answer", "topic": "Federalism", "q": "'The Indian Constitution creates a federation with a strong centre.' Explain with five provisions.", "marks": 5, "answer": "(1 mark each, any five)\\n1. Union List has more and important subjects; residuary powers with the Centre.\\n2. Parliament can make laws on State List subjects in national interest (Art. 249) and during emergency.\\n3. Emergency provisions convert the federation into a unitary system; President's Rule (Art. 356).\\n4. Governor appointed by the President; can reserve state bills for the President.\\n5. Parliament can alter boundaries or names of states (Art. 3).\\n6. Centre controls major financial resources; states depend on grants.\\n7. Single constitution, single citizenship, integrated judiciary and All India Services."}, {"n": 10, "type": "Case-based", "topic": "Judiciary", "q": "A newspaper reported that children were being made to work as bonded labourers in brick kilns. A social activist wrote a letter to the Supreme Court describing their condition. The Court treated the letter as a petition, ordered an inquiry, and directed the state government to release and rehabilitate the children.\\n(i) What is this type of litigation called?\\n(ii) Under which Article can one approach the Supreme Court for enforcing Fundamental Rights?\\n(iii) Which Fundamental Right was being violated?\\n(iv) State one criticism of judicial activism.", "marks": 4, "answer": "(i) Public Interest Litigation (PIL), an example of judicial activism. (1)\\n(ii) Article 32. (1)\\n(iii) Right against Exploitation (Articles 23 and 24: prohibition of forced/bonded labour and child labour). (1)\\n(iv) Any one: it overburdens courts; blurs separation of powers between organs; courts take up executive functions. (1)"}]}, "Sociology": {"book": "Introducing Sociology & Understanding Society", "questions": [{"n": 1, "type": "MCQ", "topic": "Sociology and Society", "q": "The term 'sociological imagination' was coined by:\\n(a) Emile Durkheim\\n(b) Max Weber\\n(c) C. Wright Mills\\n(d) Karl Marx", "marks": 1, "answer": "(c) C. Wright Mills."}, {"n": 2, "type": "Fill in the blank", "topic": "Understanding Social Institutions", "q": "When a newly married couple lives with the husband's parents, the residence is called ________.", "marks": 1, "answer": "Patrilocal."}, {"n": 3, "type": "Assertion-Reason", "topic": "Introducing Western Sociologists", "q": "Assertion (A): Durkheim said social facts should be studied as 'things'.\\nReason (R): Social facts exist outside individuals and exercise constraint over them.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Terms, Concepts and their Use in Sociology", "q": "Which of the following is an example of a primary group?\\n(a) Political party\\n(b) Family\\n(c) Trade union\\n(d) Corporation", "marks": 1, "answer": "(b) Family."}, {"n": 5, "type": "MCQ", "topic": "Doing Sociology: Research Methods", "q": "A method in which the researcher lives with a community for a long period, learning its language and taking part in daily life, is called:\\n(a) Survey\\n(b) Interview\\n(c) Participant observation\\n(d) Questionnaire", "marks": 1, "answer": "(c) Participant observation."}, {"n": 6, "type": "Short answer", "topic": "Terms, Concepts and their Use in Sociology", "q": "Differentiate between ascribed status and achieved status with one example each.", "marks": 2, "answer": "Ascribed status: assigned at birth or involuntarily, based on age, sex, caste, kinship, e.g. being a daughter or a member of a caste. (1 mark)\\nAchieved status: acquired through individual effort and choice, e.g. doctor, teacher, sports champion. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Introducing Western Sociologists", "q": "State any two features of bureaucracy as described by Max Weber.", "marks": 2, "answer": "Any two: functioning of officials within fixed jurisdiction/official duties; hierarchical ordering of positions; reliance on written documents (files); office management by trained experts; conduct in office governed by rules, separate from private life. (1 mark each)"}, {"n": 8, "type": "Short answer", "topic": "Culture and Socialisation", "q": "What is socialisation? Name two agencies of socialisation.", "marks": 2, "answer": "Socialisation is the process by which a helpless infant gradually becomes a self-aware, knowledgeable person skilled in the ways of the culture into which he or she is born. (1 mark)\\nAny two agencies: family, peer group, school, mass media, work/other agencies. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Introducing Western Sociologists", "q": "Explain Karl Marx's ideas on mode of production and class struggle.", "marks": 5, "answer": "1. Economic base (forces and relations of production) shapes the superstructure of society. (1 mark)\\n2. Mode of production: forces of production (land, labour, technology) and relations of production (ownership and control); history passes through primitive communism, slavery, feudalism, capitalism. (1 mark)\\n3. Classes are formed on the basis of position in the production process; under capitalism, bourgeoisie (owners) and proletariat (workers). (1 mark)\\n4. Exploitation: workers produce surplus value appropriated by capitalists. (1 mark)\\n5. Class struggle is the driving force of history; class consciousness would lead to revolution and a classless society. (1 mark)"}, {"n": 10, "type": "Case-based", "topic": "Indian Sociologists", "q": "In a village in Karnataka, members of a lower caste group gave up eating meat and drinking liquor, started wearing the sacred thread and invited priests to perform rituals in Sanskrit. Over a generation, they claimed a higher position in the local caste hierarchy.\\n(i) Name the process described.\\n(ii) Which Indian sociologist coined this term?\\n(iii) How is this process different from Westernisation?\\n(iv) Give one criticism of this concept.", "marks": 4, "answer": "(i) Sanskritisation. (1)\\n(ii) M.N. Srinivas. (1)\\n(iii) Sanskritisation is imitation of customs of upper castes, while Westernisation refers to changes due to British rule/Western influence in technology, institutions, ideology and values. (1)\\n(iv) Any one: it exaggerates social mobility (only positional change, structure unchanged); it accepts upper caste practices as superior, justifying inequality; it can spread discriminatory practices like dowry. (1)"}]}, "Psychology": {"book": "Introduction to Psychology", "questions": [{"n": 1, "type": "MCQ", "topic": "What is Psychology?", "q": "The first psychology laboratory was set up in Leipzig in 1879 by:\\n(a) Sigmund Freud\\n(b) Wilhelm Wundt\\n(c) William James\\n(d) John Watson", "marks": 1, "answer": "(b) Wilhelm Wundt."}, {"n": 2, "type": "Fill in the blank", "topic": "Learning", "q": "Classical conditioning was first investigated by ________ through experiments on dogs.", "marks": 1, "answer": "Ivan P. Pavlov."}, {"n": 3, "type": "Assertion-Reason", "topic": "Methods of Enquiry in Psychology", "q": "Assertion (A): In an experiment, the variable manipulated by the experimenter is called the independent variable.\\nReason (R): Its effect is observed on the dependent variable.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Human Development", "q": "According to Piaget, a child develops object permanence during the:\\n(a) Sensorimotor stage\\n(b) Preoperational stage\\n(c) Concrete operational stage\\n(d) Formal operational stage", "marks": 1, "answer": "(a) Sensorimotor stage."}, {"n": 5, "type": "MCQ", "topic": "The Bases of Human Behaviour", "q": "The part of the brain that maintains body balance and posture is the:\\n(a) Medulla\\n(b) Hypothalamus\\n(c) Cerebellum\\n(d) Thalamus", "marks": 1, "answer": "(c) Cerebellum."}, {"n": 6, "type": "Short answer", "topic": "Motivation and Emotion", "q": "Name the levels of needs in Maslow's hierarchy, from lowest to highest.", "marks": 2, "answer": "Physiological needs, safety and security needs, belongingness and love needs, esteem needs, self-actualisation. (All five in correct order: 2 marks; correct names but wrong order: 1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Methods of Enquiry in Psychology", "q": "What is naturalistic observation? State one advantage and one limitation.", "marks": 2, "answer": "Observation of behaviour in its natural setting without any manipulation or control by the researcher. (1 mark)\\nAdvantage: behaviour is studied as it naturally occurs. Limitation: observer bias / time consuming / no control over variables. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Learning", "q": "Explain insight learning with reference to Kohler's experiment.", "marks": 2, "answer": "Kohler placed a hungry chimpanzee in a cage with bananas out of reach and sticks/boxes available; after failed attempts the chimpanzee suddenly joined sticks or stacked boxes to get the bananas. (1 mark)\\nInsight learning is sudden perception of relationships among elements of a problem leading to a solution, which can be transferred to similar problems. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Human Memory", "q": "Explain the stage model of memory given by Atkinson and Shiffrin.", "marks": 5, "answer": "Memory is viewed as three separate stores through which information passes. (1 mark)\\n1. Sensory memory: large capacity, very short duration (less than a second); holds sensory impressions (iconic, echoic). (1 mark)\\n2. Short-term memory: information attended to enters STM; limited capacity (about 7±2 items), duration up to about 30 seconds, mainly acoustically encoded; kept by rehearsal. (1.5 marks)\\n3. Long-term memory: permanent store with unlimited capacity, mainly semantically encoded; information transferred through elaborative rehearsal. (1.5 marks)"}, {"n": 10, "type": "Case-based", "topic": "Learning", "q": "Aman's mother gives him a chocolate every time he finishes his homework on time, and he now completes it regularly. When he forgot to switch off the TV, his screen time was taken away. His teacher stopped nagging him once he started coming on time, and his punctuality increased.\\n(i) Which type of learning is shown here?\\n(ii) Identify the example of positive reinforcement.\\n(iii) Identify the example of negative reinforcement.\\n(iv) How is punishment different from negative reinforcement?", "marks": 4, "answer": "(i) Operant (instrumental) conditioning (Skinner). (1)\\n(ii) Getting a chocolate for completing homework on time. (1)\\n(iii) Removal of the teacher's nagging when he comes on time. (1)\\n(iv) Punishment (e.g. taking away screen time) decreases or suppresses a behaviour, while negative reinforcement strengthens a behaviour by removing an unpleasant stimulus. (1)"}]}, "Computer Science": {"book": "Computer Science (Python)", "questions": [{"n": 1, "type": "MCQ", "topic": "Getting Started with Python", "q": "What is the output of: print(7 // 2, 7 % 2)\\n(a) 3.5 1\\n(b) 3 1\\n(c) 3 0\\n(d) 4 1", "marks": 1, "answer": "(b) 3 1 (floor division gives 3, remainder is 1)."}, {"n": 2, "type": "Fill in the blank", "topic": "Encoding Schemes and Number System", "q": "The binary equivalent of decimal 13 is ________.", "marks": 1, "answer": "1101 (8 + 4 + 0 + 1)."}, {"n": 3, "type": "Assertion-Reason", "topic": "Tuples and Dictionaries", "q": "Assertion (A): Tuples are immutable in Python.\\nReason (R): Elements of a tuple cannot be changed after it is created.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(a) Both A and R are true and R is the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Tuples and Dictionaries", "q": "Which of the following creates a valid dictionary?\\n(a) d = {1: 'a', 2: 'b'}\\n(b) d = {[1, 2]: 'a'}\\n(c) d = (1: 'a', 2: 'b')\\n(d) d = [1: 'a']", "marks": 1, "answer": "(a) d = {1: 'a', 2: 'b'}. (Lists cannot be keys; (b) raises TypeError, (c) and (d) are syntax errors.)"}, {"n": 5, "type": "MCQ", "topic": "Boolean Logic", "q": "According to De Morgan's law, NOT(A AND B) is equal to:\\n(a) NOT A AND NOT B\\n(b) NOT A OR NOT B\\n(c) A OR B\\n(d) A AND NOT B", "marks": 1, "answer": "(b) NOT A OR NOT B."}, {"n": 6, "type": "Short answer", "topic": "Strings", "q": "Write the output of the following code:\\ns = 'COMPUTER'\\nprint(s[2:5])\\nprint(s[::-2])", "marks": 2, "answer": "Indices: C0 O1 M2 P3 U4 T5 E6 R7.\\ns[2:5] -> MPU (1 mark)\\ns[::-2] takes indices 7, 5, 3, 1 -> RTPO (1 mark)\\nOutput:\\nMPU\\nRTPO"}, {"n": 7, "type": "Short answer", "topic": "Lists", "q": "Write the output of the following code:\\nL = [10, 20, 30]\\nL.append([40, 50])\\nprint(len(L))\\nL.extend([60, 70])\\nprint(len(L))\\nprint(L)", "marks": 2, "answer": "append adds the list as a single element; extend adds each element.\\nOutput:\\n4\\n6\\n[10, 20, 30, [40, 50], 60, 70]\\n(1 mark for 4 and 6, 1 mark for the list)"}, {"n": 8, "type": "Short answer", "topic": "Encoding Schemes and Number System", "q": "Convert (2F) base 16 into (i) decimal and (ii) binary.", "marks": 2, "answer": "(i) 2 x 16 + 15 x 1 = 32 + 15 = 47. So (2F)16 = (47)10. (1 mark)\\n(ii) 2 = 0010, F = 1111, so (2F)16 = (00101111)2 = (101111)2. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Strings", "q": "Write a Python program to input a string and count the number of vowels, consonants, uppercase letters and lowercase letters in it.", "marks": 5, "answer": "s = input('Enter a string: ')\\nv = c = u = l = 0\\nfor ch in s:\\n    if ch.isalpha():\\n        if ch.lower() in 'aeiou':\\n            v += 1\\n        else:\\n            c += 1\\n        if ch.isupper():\\n            u += 1\\n        else:\\n            l += 1\\nprint('Vowels:', v)\\nprint('Consonants:', c)\\nprint('Uppercase:', u)\\nprint('Lowercase:', l)\\nMarking: input (1/2), loop (1), vowel/consonant logic (1.5), upper/lower logic (1.5), output (1/2). Example: input 'Hello World' gives Vowels 3, Consonants 7, Uppercase 2, Lowercase 8."}, {"n": 10, "type": "Case-based", "topic": "Tuples and Dictionaries", "q": "A class teacher stores marks in a dictionary:\\nd = {'Asha': 85, 'Ravi': 72, 'Meena': 91}\\n(i) Write a statement to add John with 65 marks.\\n(ii) Write code to print names of students scoring more than 80.\\n(iii) After step (i), what is the output of print(sorted(d))?\\n(iv) What is the output of print(d.get('Karan', 0))?", "marks": 4, "answer": "(i) d['John'] = 65 (1)\\n(ii) for name in d:\\n    if d[name] > 80:\\n        print(name)\\nOutput: Asha, Meena (each on new line) (1)\\n(iii) ['Asha', 'John', 'Meena', 'Ravi'] (1)\\n(iv) 0 (key not present, so default value is returned) (1)"}]}, "Informatics Practices": {"book": "Informatics Practices", "questions": [{"n": 1, "type": "MCQ", "topic": "Database Concepts and SQL", "q": "Which of the following is NOT a DDL command?\\n(a) CREATE\\n(b) ALTER\\n(c) DROP\\n(d) INSERT", "marks": 1, "answer": "(d) INSERT (it is a DML command)."}, {"n": 2, "type": "Fill in the blank", "topic": "Database Concepts and SQL", "q": "An attribute or set of attributes chosen to uniquely identify each tuple in a relation is called the ________.", "marks": 1, "answer": "Primary key."}, {"n": 3, "type": "Assertion-Reason", "topic": "Database Concepts and SQL", "q": "Assertion (A): A relation can have more than one candidate key.\\nReason (R): The primary key is chosen from among the candidate keys.\\n(a) Both A and R are true and R is the correct explanation of A.\\n(b) Both A and R are true but R is not the correct explanation of A.\\n(c) A is true but R is false.\\n(d) A is false but R is true.", "marks": 1, "answer": "(b) Both A and R are true but R is not the correct explanation of A."}, {"n": 4, "type": "MCQ", "topic": "Python: Lists", "q": "What is the output of: print(len([1, [2, 3], 4]))\\n(a) 2\\n(b) 3\\n(c) 4\\n(d) Error", "marks": 1, "answer": "(b) 3 (the nested list [2, 3] counts as one element)."}, {"n": 5, "type": "MCQ", "topic": "Emerging Trends", "q": "A network of physical devices embedded with sensors and software that exchange data over the internet is called:\\n(a) Cloud computing\\n(b) Internet of Things (IoT)\\n(c) Blockchain\\n(d) Virtual reality", "marks": 1, "answer": "(b) Internet of Things (IoT)."}, {"n": 6, "type": "Short answer", "topic": "Python: Dictionaries", "q": "Write the output of the following code:\\nd = {'a': 1, 'b': 2}\\nd['c'] = 3\\nd['a'] = 10\\nprint(d)\\nprint(len(d))", "marks": 2, "answer": "'c' is added as a new key; value of existing key 'a' is updated.\\nOutput:\\n{'a': 10, 'b': 2, 'c': 3}\\n3\\n(1 mark each line)"}, {"n": 7, "type": "Short answer", "topic": "Database Concepts and SQL", "q": "Differentiate between DELETE and DROP commands in SQL.", "marks": 2, "answer": "DELETE: a DML command that removes some or all rows (records) from a table; the table structure remains, e.g. DELETE FROM STUDENT WHERE Marks < 33; (1 mark)\\nDROP: a DDL command that removes the entire table (structure and data) from the database, e.g. DROP TABLE STUDENT; (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Emerging Trends", "q": "What is cloud computing? Name any two of its service models.", "marks": 2, "answer": "Cloud computing is the delivery of computing resources (servers, storage, software, etc.) over the internet on demand, typically on a pay-per-use basis. (1 mark)\\nAny two: Infrastructure as a Service (IaaS), Platform as a Service (PaaS), Software as a Service (SaaS). (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Database Concepts and SQL", "q": "Consider a table STUDENT(RollNo, Name, Class, Marks, City). Write SQL queries to:\\n(i) display all records;\\n(ii) display names of students from Delhi;\\n(iii) display names and marks of students with marks between 60 and 80;\\n(iv) display records in descending order of marks;\\n(v) increase marks of RollNo 5 by 5.", "marks": 5, "answer": "(i) SELECT * FROM STUDENT;\\n(ii) SELECT Name FROM STUDENT WHERE City = 'Delhi';\\n(iii) SELECT Name, Marks FROM STUDENT WHERE Marks BETWEEN 60 AND 80;\\n(iv) SELECT * FROM STUDENT ORDER BY Marks DESC;\\n(v) UPDATE STUDENT SET Marks = Marks + 5 WHERE RollNo = 5;\\n(1 mark each)"}, {"n": 10, "type": "Case-based", "topic": "Python: Lists", "q": "A weather station stores the maximum temperatures (°C) of five days in a list:\\ntemps = [32, 35, 29, 40, 38]\\n(i) Write a statement to display the highest temperature.\\n(ii) Write a statement to display the average temperature and give its output.\\n(iii) What is the output of print(temps[1:4])?\\n(iv) Write code to count days with temperature above 35 and state the count.", "marks": 4, "answer": "(i) print(max(temps)) -> 40 (1)\\n(ii) print(sum(temps)/len(temps)) -> 174/5 = 34.8 (1)\\n(iii) [35, 29, 40] (1)\\n(iv) count = 0\\nfor t in temps:\\n    if t > 35:\\n        count += 1\\nprint(count)\\nOutput: 2 (40 and 38) (1)"}]}, "English": {"book": "Hornbill & Snapshots", "questions": [{"n": 1, "type": "MCQ", "topic": "The Portrait of a Lady (Hornbill)", "q": "When the author went to university and got a room of his own, the grandmother spent her afternoons:\\n(a) reading the scriptures aloud\\n(b) spinning the wheel and feeding sparrows\\n(c) teaching village children\\n(d) walking to the temple", "marks": 1, "answer": "(b) spinning the wheel and feeding sparrows."}, {"n": 2, "type": "Fill in the blank", "topic": "We're Not Afraid to Die... if We Can All Be Together (Hornbill)", "q": "The name of the family's boat on their round-the-world voyage was ________.", "marks": 1, "answer": "Wavewalker."}, {"n": 3, "type": "MCQ", "topic": "Discovering Tut: the Saga Continues (Hornbill)", "q": "In 2005, Tutankhamun's mummy was examined using a portable:\\n(a) X-ray machine\\n(b) MRI scanner\\n(c) CT scanner\\n(d) Microscope", "marks": 1, "answer": "(c) CT scanner (used by Zahi Hawass's team)."}, {"n": 4, "type": "MCQ", "topic": "The Summer of the Beautiful White Horse (Snapshots)", "q": "The white horse that Mourad took belonged to:\\n(a) Uncle Khosrove\\n(b) John Byro\\n(c) Aram's father\\n(d) A travelling circus", "marks": 1, "answer": "(b) John Byro, a farmer of the Assyrian community."}, {"n": 5, "type": "MCQ", "topic": "The Address (Snapshots)", "q": "The address that the narrator's mother had given her was:\\n(a) Number 46, Marconi Street\\n(b) Number 64, Marconi Street\\n(c) Number 46, Baker Street\\n(d) Number 12, Station Road", "marks": 1, "answer": "(a) Number 46, Marconi Street (Mrs Dorling's house)."}, {"n": 6, "type": "Short answer", "topic": "The Portrait of a Lady (Hornbill)", "q": "Why was the grandmother unhappy with the author's education at the English school in the city?", "marks": 2, "answer": "She could no longer help him with lessons as they were in English; there was no teaching about God and the scriptures. (1 mark)\\nShe was most disturbed when she learnt that music was taught, as she associated music with harlots and beggars and felt it was not meant for gentlefolk. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "We're Not Afraid to Die... if We Can All Be Together (Hornbill)", "q": "How did the children, Jonathan and Suzanne, show courage during the storm?", "marks": 2, "answer": "Suzanne, despite a severe head injury and swollen eyes, did not complain and wrote a touching card to her parents saying they were not afraid to die if they could all be together. (1 mark)\\nJonathan calmly said he was not afraid to die if they could all die together; both children stayed brave and did not panic, supporting their parents. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "The Address (Snapshots)", "q": "Why did the narrator decide to forget the address at the end of the story?", "marks": 2, "answer": "The objects in Mrs Dorling's house, though familiar, had lost their value and emotional connection because they were placed in strange surroundings and reminded her painfully of the past. (1 mark)\\nShe realised that memories of her mother were more precious than the things themselves, so she decided to move on and forget the address. (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Writing Skills: Article Writing", "q": "You are Kavya/Karan of Class XI. Write an article in 150-200 words for your school magazine on 'The Importance of Physical Fitness for Teenagers', suggesting ways to stay fit.", "marks": 5, "answer": "Format (1 mark): title and writer's name.\\nContent (2 marks), value points: sedentary lifestyle and screen addiction among teens; fitness builds strength, immunity and concentration; reduces stress, obesity and lifestyle diseases; ways: daily exercise/sports/yoga, balanced diet, adequate sleep, limiting screen time, outdoor activities; role of schools and parents.\\nExpression (2 marks): coherence, organisation, accuracy of grammar and suitable vocabulary; clear introduction, body and conclusion."}, {"n": 10, "type": "Case-based", "topic": "Reading: Unseen Passage", "q": "Read the passage and answer:\\nHoney bees are among the most important pollinators on Earth. Nearly one-third of the food we eat depends on pollination by insects, mainly bees. However, bee populations are declining worldwide due to pesticide use, loss of flowering plants and climate change. Scientists warn that without bees, crops like apples, almonds and mustard would suffer heavily. Farmers can help by planting a variety of flowers and reducing chemical sprays, while city dwellers can grow flowering plants on balconies.\\n(i) Why are bees important?\\n(ii) State two causes of their decline.\\n(iii) How can city dwellers help?\\n(iv) Find a word from the passage meaning 'decreasing'.", "marks": 4, "answer": "(i) They are major pollinators; nearly one-third of our food depends on insect pollination, mainly by bees. (1)\\n(ii) Any two: pesticide use; loss of flowering plants; climate change. (1)\\n(iii) By growing flowering plants on their balconies. (1)\\n(iv) Declining. (1)"}]}}, "12": {"Physics": {"book": "Physics Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Electric Charges and Fields", "q": "The SI unit of electric flux is:\\n(a) N C^-1\\n(b) N m^2 C^-1\\n(c) N m^-2 C\\n(d) V m^-1", "marks": 1, "answer": "(b) N m^2 C^-1 (flux = E x area, so N C^-1 x m^2)."}, {"n": 2, "type": "Assertion-Reason", "topic": "Current Electricity", "q": "Assertion (A): The drift speed of electrons in a conductor is very small, yet a bulb glows almost instantly when the switch is closed.\\nReason (R): On closing the switch, an electric field is set up throughout the conductor almost instantly, so free electrons everywhere start drifting at once.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 3, "type": "Fill in the blank", "topic": "Electromagnetic Induction", "q": "The production of an induced emf in a coil due to a change of current in the same coil is called ________.", "marks": 1, "answer": "Self-induction."}, {"n": 4, "type": "MCQ", "topic": "Electromagnetic Waves", "q": "Which electromagnetic waves are used in radar systems for aircraft navigation?\\n(a) Infrared waves\\n(b) Microwaves\\n(c) X-rays\\n(d) Gamma rays", "marks": 1, "answer": "(b) Microwaves."}, {"n": 5, "type": "MCQ", "topic": "Semiconductor Electronics", "q": "In a p-type semiconductor, the majority charge carriers are:\\n(a) free electrons\\n(b) holes\\n(c) positive ions\\n(d) negative ions", "marks": 1, "answer": "(b) Holes (produced by trivalent acceptor impurity such as boron)."}, {"n": 6, "type": "Short answer", "topic": "Current Electricity", "q": "Two resistors of 4 ohm and 12 ohm are connected in parallel across a 6 V battery of negligible internal resistance. Find (i) the equivalent resistance and (ii) the current drawn from the battery.", "marks": 2, "answer": "(i) 1/R = 1/4 + 1/12 = 3/12 + 1/12 = 4/12, so R = 3 ohm. (1 mark)\\n(ii) I = V/R = 6/3 = 2 A. (1 mark)"}, {"n": 7, "type": "Short answer", "topic": "Dual Nature of Radiation and Matter", "q": "Light of photon energy 3.5 eV falls on a metal surface of work function 2.0 eV. Find (i) the maximum kinetic energy of the emitted photoelectrons and (ii) the stopping potential.", "marks": 2, "answer": "(i) Einstein's equation: K_max = h nu - phi_0 = 3.5 - 2.0 = 1.5 eV. (1 mark)\\n(ii) e V_0 = K_max, so V_0 = 1.5 V. (1 mark)"}, {"n": 8, "type": "Short answer", "topic": "Atoms", "q": "Using the Bohr model, find the energy of the electron in the n = 2 orbit of a hydrogen atom, and the energy of the photon emitted when it jumps from n = 2 to n = 1. (E_n = -13.6/n^2 eV)", "marks": 2, "answer": "E_2 = -13.6/2^2 = -3.4 eV; E_1 = -13.6 eV. (1 mark)\\nPhoton energy = E_2 - E_1 = -3.4 - (-13.6) = 10.2 eV (Lyman series line). (1 mark)"}, {"n": 9, "type": "Long answer", "topic": "Electric Charges and Fields (Gauss's Law)", "q": "State Gauss's law in electrostatics. Using it, derive an expression for the electric field at a distance r from an infinitely long straight wire having uniform linear charge density lambda. Show how the field varies with r and state its direction for positive lambda.", "marks": 5, "answer": "Marking points:\\n1. Statement: Total electric flux through a closed surface = q_enclosed/epsilon_0. (1)\\n2. Choose a cylindrical Gaussian surface of radius r and length l coaxial with the wire; by symmetry E is radial and has the same magnitude on the curved surface. (1)\\n3. Flux through the flat ends is zero (E is parallel to the end faces); flux through curved surface = E x 2 pi r l. (1)\\n4. Charge enclosed = lambda l, so E (2 pi r l) = lambda l / epsilon_0, giving E = lambda / (2 pi epsilon_0 r). (1)\\n5. E is proportional to 1/r (graph: hyperbola-like fall); directed radially outward from the wire for positive lambda. (1)"}, {"n": 10, "type": "Case-based", "topic": "Alternating Current (Series LCR resonance)", "q": "Read the case and answer.\\nA radio receiver uses a series LCR circuit for tuning. In a lab model, a coil of inductance L = 2.0 H, a capacitor C = 32 microfarad and a resistor R = 10 ohm are connected in series to a 200 V (rms) source of variable frequency. When the source frequency equals the natural frequency of the circuit, the current becomes maximum.\\n(i) Find the resonant angular frequency. (1)\\n(ii) Find the rms current at resonance. (1)\\n(iii) Find the quality factor Q of the circuit. (1)\\n(iv) What is the power factor of the circuit at resonance? (1)", "marks": 4, "answer": "(i) omega_0 = 1/sqrt(LC) = 1/sqrt(2.0 x 32 x 10^-6) = 1/sqrt(64 x 10^-6) = 1/(8 x 10^-3) = 125 rad/s.\\n(ii) At resonance X_L = X_C, so Z = R = 10 ohm; I_rms = 200/10 = 20 A.\\n(iii) Q = omega_0 L / R = (125 x 2.0)/10 = 25.\\n(iv) Power factor cos phi = R/Z = 1 (current and voltage in phase)."}]}, "Chemistry": {"book": "Chemistry Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Solutions", "q": "The van't Hoff factor (i) for K2SO4, assuming complete dissociation in water, is:\\n(a) 1\\n(b) 2\\n(c) 3\\n(d) 4", "marks": 1, "answer": "(c) 3 (K2SO4 -> 2K+ + SO4^2-)."}, {"n": 2, "type": "Assertion-Reason", "topic": "Electrochemistry", "q": "Assertion (A): Molar conductivity of an electrolyte increases on dilution.\\nReason (R): Conductivity (specific conductance) of a solution decreases on dilution because the number of ions per unit volume decreases.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(b) Both A and R are true, but R is not the correct explanation of A. (Molar conductivity increases because the volume containing one mole of electrolyte increases, and for weak electrolytes the degree of dissociation also increases.)"}, {"n": 3, "type": "Fill in the blank", "topic": "Chemical Kinetics", "q": "The unit of the rate constant for a first order reaction is ________.", "marks": 1, "answer": "s^-1 (time^-1)."}, {"n": 4, "type": "MCQ", "topic": "Coordination Compounds", "q": "The IUPAC name of [Co(NH3)6]Cl3 is:\\n(a) Hexaamminecobalt(III) chloride\\n(b) Hexaamminecobalt(II) chloride\\n(c) Cobalt hexaammine chloride\\n(d) Hexaamminecobaltate(III) chloride", "marks": 1, "answer": "(a) Hexaamminecobalt(III) chloride."}, {"n": 5, "type": "MCQ", "topic": "Aldehydes, Ketones and Carboxylic Acids", "q": "Which of the following gives a positive iodoform test?\\n(a) Methanal\\n(b) Propanal\\n(c) Propan-2-one\\n(d) Benzaldehyde", "marks": 1, "answer": "(c) Propan-2-one (acetone), as it contains the CH3-CO- group."}, {"n": 6, "type": "Short answer", "topic": "Chemical Kinetics", "q": "The rate constant of a first order reaction is 0.0693 min^-1. Calculate (i) its half-life and (ii) the time required for 75% completion of the reaction.", "marks": 2, "answer": "(i) t1/2 = 0.693/k = 0.693/0.0693 = 10 min. (1)\\n(ii) 75% completion = two half-lives (100 -> 50 -> 25), so t = 2 x 10 = 20 min. [Check: t = (2.303/k) log(100/25) = (2.303/0.0693) x 0.602 = 20 min.] (1)"}, {"n": 7, "type": "Short answer", "topic": "Electrochemistry", "q": "Calculate the emf of the cell at 298 K:\\nZn(s) | Zn2+ (0.1 M) || Cu2+ (1 M) | Cu(s)\\nGiven E°cell = 1.10 V.", "marks": 2, "answer": "Cell reaction: Zn + Cu2+ -> Zn2+ + Cu, n = 2. (1/2)\\nNernst equation: E = E° - (0.059/n) log([Zn2+]/[Cu2+]) (1/2)\\nE = 1.10 - (0.059/2) log(0.1/1) = 1.10 - 0.0295 x (-1) (1/2)\\nE = 1.10 + 0.0295 = 1.1295 V (about 1.13 V). (1/2)"}, {"n": 8, "type": "Short answer", "topic": "The d- and f-Block Elements", "q": "Zn, Cd and Hg are not regarded as transition elements although they belong to the d-block. Give two reasons.", "marks": 2, "answer": "1. They have completely filled d-orbitals (d10 configuration) both in the ground state and in their common oxidation state (+2), whereas a transition element must have an incompletely filled d-subshell in the atom or common ion. (1)\\n2. Hence they do not show typical transition properties such as variable oxidation states, coloured ions or marked catalytic activity; they are also soft with low melting points (weak metallic bonding as d-electrons do not take part). (1)"}, {"n": 9, "type": "Long answer", "topic": "Haloalkanes and Haloarenes", "q": "Explain the SN1 and SN2 mechanisms of nucleophilic substitution in haloalkanes with one example each. Compare them on the basis of order of reaction, stereochemistry and reactivity of alkyl halides. Which will react faster by SN1: (CH3)3CBr or CH3Br? Why?", "marks": 5, "answer": "Marking points:\\n1. SN2: single-step, nucleophile attacks from the back side as the halide leaves; transition state with 5 groups; e.g. CH3Cl + OH- -> CH3OH + Cl-. Rate = k[RX][Nu-], second order. (1)\\n2. SN2 gives inversion of configuration (Walden inversion); reactivity 1° > 2° > 3° (steric hindrance). (1)\\n3. SN1: two steps - slow ionisation to form carbocation (rate-determining), then fast attack by nucleophile; e.g. (CH3)3CBr + OH- -> (CH3)3COH + Br- in polar protic solvent. Rate = k[RX], first order. (1)\\n4. SN1 gives racemisation (planar carbocation attacked from both faces); reactivity 3° > 2° > 1° (carbocation stability). (1)\\n5. (CH3)3CBr reacts faster by SN1 because it forms a stable tertiary carbocation (stabilised by +I effect and hyperconjugation of three methyl groups); CH3+ is very unstable. (1)"}, {"n": 10, "type": "Case-based", "topic": "Solutions (Colligative properties)", "q": "Read the case and answer.\\nColligative properties depend only on the number of solute particles, not on their nature. A student dissolves 1.8 g of glucose (molar mass 180 g/mol) in 100 g of water. Kb for water = 0.52 K kg mol^-1 and the boiling point of pure water is 373.15 K.\\n(i) Calculate the molality of the solution. (1)\\n(ii) Calculate the boiling point of the solution. (1)\\n(iii) Would a 0.1 m NaCl solution show a larger or smaller elevation? Give reason. (1)\\n(iv) Which colligative property is preferred to find molar masses of proteins/polymers? (1)", "marks": 4, "answer": "(i) Moles of glucose = 1.8/180 = 0.01 mol; molality = 0.01/0.100 kg = 0.1 mol/kg.\\n(ii) Delta Tb = Kb x m = 0.52 x 0.1 = 0.052 K; boiling point = 373.15 + 0.052 = 373.202 K.\\n(iii) Larger (about double), because NaCl dissociates into Na+ and Cl- (i about 2), doubling the number of particles.\\n(iv) Osmotic pressure - it is measurable at room temperature and gives large values even for very dilute solutions, so biomolecules are not damaged."}]}, "Biology": {"book": "Biology", "questions": [{"n": 1, "type": "MCQ", "topic": "Sexual Reproduction in Flowering Plants", "q": "Which of the following is triploid (3n) in angiosperms?\\n(a) Zygote\\n(b) Nucellus\\n(c) Primary endosperm nucleus\\n(d) Megaspore mother cell", "marks": 1, "answer": "(c) Primary endosperm nucleus (formed by fusion of a male gamete with two polar nuclei - triple fusion)."}, {"n": 2, "type": "Assertion-Reason", "topic": "Principles of Inheritance and Variation", "q": "Assertion (A): Haemophilia is more common in males than in females.\\nReason (R): The gene for haemophilia is X-linked recessive, and males have only one X chromosome.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A. (A single recessive allele on the X chromosome expresses in hemizygous males.)"}, {"n": 3, "type": "Fill in the blank", "topic": "Biotechnology: Principles and Processes", "q": "The enzyme that joins DNA fragments by forming phosphodiester bonds is called ________.", "marks": 1, "answer": "DNA ligase."}, {"n": 4, "type": "MCQ", "topic": "Human Health and Disease", "q": "Malaria in humans is caused by:\\n(a) Entamoeba histolytica\\n(b) Plasmodium\\n(c) Wuchereria bancrofti\\n(d) Salmonella typhi", "marks": 1, "answer": "(b) Plasmodium (transmitted by female Anopheles mosquito)."}, {"n": 5, "type": "MCQ", "topic": "Reproductive Health", "q": "Copper T (CuT) is an example of:\\n(a) Hormone-releasing IUD\\n(b) Non-medicated IUD\\n(c) Copper-releasing IUD\\n(d) Barrier method", "marks": 1, "answer": "(c) Copper-releasing IUD (Cu ions suppress sperm motility and fertilising capacity)."}, {"n": 6, "type": "Short answer", "topic": "Principles of Inheritance and Variation", "q": "In pea, tall (T) is dominant over dwarf (t). Show the cross between two heterozygous tall plants and give the phenotypic and genotypic ratios of the F2 generation.", "marks": 2, "answer": "Cross: Tt x Tt; gametes T, t from each parent. Punnett square gives TT, Tt, Tt, tt. (1)\\nGenotypic ratio 1 TT : 2 Tt : 1 tt; phenotypic ratio 3 tall : 1 dwarf. (1)"}, {"n": 7, "type": "Short answer", "topic": "Ecosystem", "q": "Differentiate between gross primary productivity (GPP) and net primary productivity (NPP). How are they related?", "marks": 2, "answer": "GPP is the total rate of production of organic matter by producers during photosynthesis. NPP is the biomass available to consumers after respiratory losses of producers are deducted. (1)\\nRelation: NPP = GPP - R (R = respiration losses). (1)"}, {"n": 8, "type": "Short answer", "topic": "Biotechnology: Principles and Processes", "q": "What are restriction endonucleases? Write the recognition sequence of EcoRI and explain why it is called a palindrome.", "marks": 2, "answer": "Restriction endonucleases are 'molecular scissors' that cut DNA at specific recognition sequences. (1/2)\\nEcoRI recognises 5'-GAATTC-3' / 3'-CTTAAG-5' and cuts between G and A, producing sticky ends. (1/2 + 1/2)\\nIt is a palindrome because the sequence reads the same on both strands when read in the same orientation (5' to 3'). (1/2)"}, {"n": 9, "type": "Long answer", "topic": "Molecular Basis of Inheritance", "q": "Explain the lac operon of E. coli. Describe how it functions in the absence and presence of lactose. Why is it called a case of negative regulation?", "marks": 5, "answer": "Marking points:\\n1. Operon concept (Jacob and Monod): a polycistronic structural gene unit regulated by a common promoter and operator. (1)\\n2. Components: regulator gene i (codes repressor), promoter p, operator o, structural genes z (beta-galactosidase), y (permease), a (transacetylase). (1)\\n3. Absence of lactose: repressor protein binds to operator and prevents RNA polymerase from transcribing z, y, a - operon switched off. (1)\\n4. Presence of lactose (inducer; actually allolactose): inducer binds repressor and inactivates it; repressor cannot bind operator; RNA polymerase transcribes structural genes - enzymes formed, lactose metabolised. (1)\\n5. Negative regulation because the regulatory protein (repressor) switches the operon off; its removal allows expression. (1)"}, {"n": 10, "type": "Case-based", "topic": "Human Health and Disease (Immunity)", "q": "Read the case and answer.\\nRiya, aged 8, cut her foot on a rusty nail and was immediately given an anti-tetanus serum (ATS) injection. Her younger brother received oral polio drops the same week under the pulse polio programme. Their mother recalled that doctors had advised her to feed the babies colostrum soon after birth.\\n(i) Which type of immunity did Riya receive from ATS? (1)\\n(ii) Which type of immunity does the polio vaccine generate? (1)\\n(iii) Name the antibody present in colostrum. (1)\\n(iv) Why are booster doses of vaccines given? (1)", "marks": 4, "answer": "(i) Artificially acquired passive immunity (ready-made antibodies/antitoxins are injected; quick but short-lived).\\n(ii) Artificially acquired active immunity (body produces its own antibodies and memory cells).\\n(iii) IgA.\\n(iv) To stimulate memory B and T cells again so that a stronger, longer-lasting secondary (anamnestic) response is maintained."}]}, "Maths": {"book": "Mathematics Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Determinants", "q": "If A is a square matrix of order 3 and |A| = 4, then |2A| equals:\\n(a) 8\\n(b) 16\\n(c) 32\\n(d) 64", "marks": 1, "answer": "(c) 32, since |kA| = k^n |A| = 2^3 x 4 = 32."}, {"n": 2, "type": "MCQ", "topic": "Inverse Trigonometric Functions", "q": "The principal value of sin^-1(-1/2) is:\\n(a) -pi/6\\n(b) 5pi/6\\n(c) 7pi/6\\n(d) pi/3", "marks": 1, "answer": "(a) -pi/6 (principal range of sin^-1 is [-pi/2, pi/2])."}, {"n": 3, "type": "Fill in the blank", "topic": "Differential Equations", "q": "The degree of the differential equation (d^2y/dx^2)^3 + (dy/dx)^2 + y = 0 is ________.", "marks": 1, "answer": "3 (highest order derivative d^2y/dx^2 has power 3; the equation is polynomial in derivatives)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Continuity and Differentiability", "q": "Assertion (A): The function f(x) = |x| is continuous at x = 0.\\nReason (R): The function f(x) = |x| is differentiable at x = 0.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(c) A is true, but R is false. (LHD = -1 and RHD = 1 at x = 0, so |x| is not differentiable there.)"}, {"n": 5, "type": "MCQ", "topic": "Probability", "q": "If P(A) = 0.5, P(B) = 0.4 and P(A and B) = 0.2, then P(A|B) is:\\n(a) 0.4\\n(b) 0.5\\n(c) 0.8\\n(d) 0.1", "marks": 1, "answer": "(b) 0.5, since P(A|B) = P(A and B)/P(B) = 0.2/0.4 = 0.5."}, {"n": 6, "type": "Short answer", "topic": "Continuity and Differentiability", "q": "Find dy/dx if y = e^(3x) sin 2x.", "marks": 2, "answer": "Product rule: dy/dx = e^(3x) d/dx(sin 2x) + sin 2x d/dx(e^(3x)) (1)\\n= 2e^(3x) cos 2x + 3e^(3x) sin 2x = e^(3x)(3 sin 2x + 2 cos 2x). (1)"}, {"n": 7, "type": "Short answer", "topic": "Integrals", "q": "Evaluate: integral of x e^x dx.", "marks": 2, "answer": "Integration by parts with u = x, dv = e^x dx: du = dx, v = e^x. (1/2)\\nIntegral = x e^x - integral e^x dx (1)\\n= x e^x - e^x + C = e^x (x - 1) + C. (1/2)"}, {"n": 8, "type": "Short answer", "topic": "Vector Algebra", "q": "Find the angle between the vectors a = i + j and b = j + k.", "marks": 2, "answer": "a . b = (1)(0) + (1)(1) + (0)(1) = 1; |a| = sqrt2, |b| = sqrt2. (1)\\ncos theta = 1/(sqrt2 x sqrt2) = 1/2, so theta = pi/3 (60 degrees). (1)"}, {"n": 9, "type": "Long answer", "topic": "Linear Programming", "q": "Solve graphically: Maximise Z = 3x + 2y subject to x + y <= 4, x + 3y <= 6, x >= 0, y >= 0.", "marks": 5, "answer": "Marking points:\\n1. Lines: x + y = 4 through (4,0),(0,4); x + 3y = 6 through (6,0),(0,2). Correct graph and shading towards origin in first quadrant. (1)\\n2. Intersection: subtract x + y = 4 from x + 3y = 6 -> 2y = 2, y = 1, x = 3; point (3,1). (1)\\n3. Corner points of bounded feasible region: O(0,0), A(4,0), B(3,1), C(0,2). (1)\\n4. Z values: O -> 0; A -> 12; B -> 9 + 2 = 11; C -> 4. (1)\\n5. Maximum Z = 12 at x = 4, y = 0. (1)"}, {"n": 10, "type": "Case-based", "topic": "Probability (Bayes' Theorem)", "q": "Read the case and answer.\\nA factory has two machines A and B. Machine A produces 60% and machine B produces 40% of the total bolts. 2% of bolts made by A and 3% of bolts made by B are defective. A bolt is picked at random from the day's production.\\n(i) Find the probability that the bolt is defective. (2)\\n(ii) If the bolt is found defective, find the probability that it was made by machine A. (1)\\n(iii) Find the probability that the bolt is not defective. (1)", "marks": 4, "answer": "Let E1 = made by A, E2 = made by B, D = defective. P(E1) = 0.6, P(E2) = 0.4, P(D|E1) = 0.02, P(D|E2) = 0.03.\\n(i) Total probability: P(D) = 0.6 x 0.02 + 0.4 x 0.03 = 0.012 + 0.012 = 0.024.\\n(ii) Bayes' theorem: P(E1|D) = 0.012/0.024 = 1/2.\\n(iii) P(not D) = 1 - 0.024 = 0.976."}]}, "Accountancy": {"book": "Accountancy Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Accounting for Partnership: Basic Concepts", "q": "In the absence of a partnership deed, interest on partners' capital is:\\n(a) allowed at 6% p.a.\\n(b) not allowed\\n(c) allowed at 12% p.a.\\n(d) allowed at bank rate", "marks": 1, "answer": "(b) Not allowed (as per the Indian Partnership Act, 1932, in the absence of a deed)."}, {"n": 2, "type": "MCQ", "topic": "Reconstitution of Partnership: Admission", "q": "Sacrificing ratio is calculated as:\\n(a) New ratio - Old ratio\\n(b) Old ratio - New ratio\\n(c) Old ratio + New ratio\\n(d) New ratio / Old ratio", "marks": 1, "answer": "(b) Old ratio - New ratio."}, {"n": 3, "type": "Fill in the blank", "topic": "Accounting for Share Capital", "q": "As per SEBI guidelines, a company can allot shares only if it receives at least ________% of the issued amount as minimum subscription.", "marks": 1, "answer": "90%."}, {"n": 4, "type": "Assertion-Reason", "topic": "Accounting Ratios", "q": "Assertion (A): A current ratio of 2:1 is generally considered ideal.\\nReason (R): Even if current assets are realised at half their book value, the firm can still pay its current liabilities.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Cash Flow Statement", "q": "Purchase of machinery for cash is classified in a Cash Flow Statement under:\\n(a) Operating activities\\n(b) Investing activities\\n(c) Financing activities\\n(d) Cash equivalents", "marks": 1, "answer": "(b) Investing activities (outflow)."}, {"n": 6, "type": "Short answer", "topic": "Goodwill: Nature and Valuation", "q": "The profits of a firm for the last three years were Rs 40,000, Rs 50,000 and Rs 60,000. Calculate the value of goodwill at two years' purchase of the average profits.", "marks": 2, "answer": "Average profit = (40,000 + 50,000 + 60,000)/3 = 1,50,000/3 = Rs 50,000. (1)\\nGoodwill = 50,000 x 2 = Rs 1,00,000. (1)"}, {"n": 7, "type": "Short answer", "topic": "Reconstitution of Partnership: Admission", "q": "A and B share profits in the ratio 3:2. They admit C for a 1/5 share, which he takes from A and B in their old ratio. Calculate the new profit sharing ratio.", "marks": 2, "answer": "Remaining share for A and B = 1 - 1/5 = 4/5, divided in old ratio 3:2 (since sacrifice is in old ratio). (1/2)\\nA = 4/5 x 3/5 = 12/25; B = 4/5 x 2/5 = 8/25; C = 1/5 = 5/25. (1)\\nNew ratio A : B : C = 12 : 8 : 5. (1/2)"}, {"n": 8, "type": "Short answer", "topic": "Accounting for Share Capital", "q": "XYZ Ltd issued 10,000 equity shares of Rs 10 each at a premium of Rs 2 per share, the whole amount payable on application. All shares were subscribed and allotted. Pass journal entries.", "marks": 2, "answer": "1. Bank A/c Dr 1,20,000\\n   To Equity Share Application A/c 1,20,000\\n(Application money received on 10,000 shares @ Rs 12) (1)\\n2. Equity Share Application A/c Dr 1,20,000\\n   To Equity Share Capital A/c 1,00,000\\n   To Securities Premium A/c 20,000\\n(Application money transferred on allotment) (1)"}, {"n": 9, "type": "Long answer", "topic": "Reconstitution of Partnership: Retirement", "q": "X, Y and Z are partners sharing profits 2:2:1. Z retires. X and Y will share future profits equally. On Z's retirement: goodwill of the firm is valued at Rs 50,000; General Reserve is Rs 15,000; profit on revaluation is Rs 5,000. Z's capital balance is Rs 40,000. Calculate the gaining ratio, pass journal entries for goodwill, reserve and revaluation profit, and find the amount due to Z (transferred to his loan account).", "marks": 5, "answer": "1. Gaining ratio: X = 1/2 - 2/5 = 1/10; Y = 1/2 - 2/5 = 1/10; ratio 1:1. (1)\\n2. Goodwill (Z's share = 50,000 x 1/5 = 10,000): X's Capital A/c Dr 5,000; Y's Capital A/c Dr 5,000; To Z's Capital A/c 10,000. (1)\\n3. General Reserve A/c Dr 15,000; To X's Capital 6,000; To Y's Capital 6,000; To Z's Capital 3,000 (2:2:1). (1)\\n4. Revaluation A/c Dr 5,000; To X's Capital 2,000; To Y's Capital 2,000; To Z's Capital 1,000. (1)\\n5. Amount due to Z = 40,000 + 10,000 + 3,000 + 1,000 = Rs 54,000. Entry: Z's Capital A/c Dr 54,000; To Z's Loan A/c 54,000. (1)"}, {"n": 10, "type": "Case-based", "topic": "Accounting Ratios", "q": "Read the case and answer.\\nMeera Ltd's balance sheet shows current assets of Rs 4,00,000, which include inventory of Rs 1,00,000 and prepaid expenses of Rs 20,000. Its current liabilities are Rs 2,00,000. The finance manager wants to check liquidity before applying for a bank loan.\\n(i) Calculate the current ratio. (1)\\n(ii) Calculate the quick (liquid) ratio. (1)\\n(iii) If the company pays trade payables of Rs 50,000 in cash, calculate the new current ratio and state whether it increases, decreases or remains unchanged. (2)", "marks": 4, "answer": "(i) Current ratio = 4,00,000/2,00,000 = 2:1.\\n(ii) Quick assets = 4,00,000 - 1,00,000 - 20,000 = 2,80,000; quick ratio = 2,80,000/2,00,000 = 1.4:1.\\n(iii) New current assets = 3,50,000; new current liabilities = 1,50,000; current ratio = 3,50,000/1,50,000 = 2.33:1 (approx). The ratio increases (when a ratio above 1 has equal amounts removed from numerator and denominator, it rises)."}]}, "Business Studies": {"book": "Business Studies Part I & II", "questions": [{"n": 1, "type": "MCQ", "topic": "Principles of Management", "q": "'One head, one plan' for a group of activities having the same objective is Fayol's principle of:\\n(a) Unity of command\\n(b) Unity of direction\\n(c) Scalar chain\\n(d) Order", "marks": 1, "answer": "(b) Unity of direction."}, {"n": 2, "type": "MCQ", "topic": "Directing", "q": "Which of the following is NOT an element of directing?\\n(a) Supervision\\n(b) Motivation\\n(c) Leadership\\n(d) Recruitment", "marks": 1, "answer": "(d) Recruitment (it is part of staffing)."}, {"n": 3, "type": "Fill in the blank", "topic": "Directing (Motivation)", "q": "The highest level need in Maslow's hierarchy of needs is ________.", "marks": 1, "answer": "Self-actualisation needs."}, {"n": 4, "type": "Assertion-Reason", "topic": "Planning", "q": "Assertion (A): Planning is futuristic.\\nReason (R): Planning involves looking ahead and preparing for the future by forecasting future events.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Marketing", "q": "Which of the following is NOT one of the 4 Ps of the marketing mix?\\n(a) Product\\n(b) Price\\n(c) People\\n(d) Promotion", "marks": 1, "answer": "(c) People (the 4 Ps are Product, Price, Place and Promotion)."}, {"n": 6, "type": "Short answer", "topic": "Financial Markets", "q": "Distinguish between money market and capital market on any two bases.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Instruments: money market - treasury bills, commercial paper, call money, certificates of deposit; capital market - equity shares, debentures, bonds.\\n2. Duration: money market deals in short-term funds (up to one year); capital market in medium and long-term funds.\\n3. Participants: money market - mainly RBI, banks, financial institutions; capital market - also individual investors.\\n4. Risk and return: money market has lower risk and lower returns; capital market higher risk and higher expected return."}, {"n": 7, "type": "Short answer", "topic": "Financial Management", "q": "Explain any two factors affecting the working capital requirements of a business.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Nature of business: trading firms need less working capital than manufacturing firms.\\n2. Scale of operations: larger scale needs more inventory and debtors, hence more working capital.\\n3. Business cycle: more working capital needed in boom, less in depression.\\n4. Seasonal factors: more needed in peak season.\\n5. Production cycle: longer cycle needs more working capital.\\n6. Credit allowed/availed: liberal credit to customers increases need; credit from suppliers reduces it.\\n7. Operating efficiency, availability of raw material, growth prospects, inflation."}, {"n": 8, "type": "Short answer", "topic": "Business Environment", "q": "Explain any two features of business environment.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Totality of external forces: it is the sum total of all things external to a business.\\n2. Specific and general forces: specific forces (customers, competitors, suppliers) and general forces (economic, social, political, legal, technological).\\n3. Inter-relatedness: different forces are closely related (e.g. health awareness increased demand for organic food).\\n4. Dynamic nature: it keeps changing.\\n5. Uncertainty: future changes are difficult to predict.\\n6. Complexity and relativity: it is difficult to understand and differs from place to place."}, {"n": 9, "type": "Long answer", "topic": "Controlling", "q": "Explain the steps involved in the process of controlling.", "marks": 5, "answer": "Marking points (1 mark each):\\n1. Setting performance standards: standards may be quantitative (cost, units, time) or qualitative (goodwill, motivation); should be measurable.\\n2. Measurement of actual performance: done objectively through personal observation, sample checking, reports.\\n3. Comparing actual performance with standards: reveals deviations.\\n4. Analysing deviations: using critical point control (focus on key result areas) and management by exception (only significant deviations reported); find causes.\\n5. Taking corrective action: e.g. training, revising standards, repairing machines, so that deviations do not recur."}, {"n": 10, "type": "Case-based", "topic": "Principles of Management (Scientific Management)", "q": "Read the case and answer.\\nPrakash Industries restructured its factory. Under the factory manager, a Planning In-charge and a Production In-charge were appointed, each with four specialists. On the shop floor, workers now receive instructions from a speed boss, a gang boss, a repair boss and an inspector. The company also announced that workers producing above the standard output would be paid Rs 60 per unit, while those below standard would get Rs 50 per unit.\\n(i) Identify the technique of scientific management in the first part. (1)\\n(ii) Identify the technique in the last line. (1)\\n(iii) Name any two specialists who work under the Planning In-charge. (2)", "marks": 4, "answer": "(i) Functional foremanship (F.W. Taylor).\\n(ii) Differential piece wage system.\\n(iii) Any two: Route clerk, Instruction card clerk, Time and cost clerk, Disciplinarian (1 mark each)."}]}, "Economics": {"book": "Introductory Macroeconomics & Indian Economic Development", "questions": [{"n": 1, "type": "MCQ", "topic": "National Income Accounting", "q": "Which of the following is included in the national income of India?\\n(a) Old-age pension\\n(b) Sale of a second-hand car\\n(c) Services of a housewife\\n(d) Imputed rent of owner-occupied houses", "marks": 1, "answer": "(d) Imputed rent of owner-occupied houses."}, {"n": 2, "type": "MCQ", "topic": "Determination of Income and Employment", "q": "If the marginal propensity to consume (MPC) is 0.8, the value of the investment multiplier is:\\n(a) 2\\n(b) 4\\n(c) 5\\n(d) 8", "marks": 1, "answer": "(c) 5, since k = 1/(1 - MPC) = 1/0.2 = 5."}, {"n": 3, "type": "Fill in the blank", "topic": "Money and Banking", "q": "The rate at which the RBI lends short-term funds to commercial banks against government securities is called the ________.", "marks": 1, "answer": "Repo rate."}, {"n": 4, "type": "Assertion-Reason", "topic": "Government Budget and the Economy", "q": "Assertion (A): Revenue deficit implies dissaving on the part of the government.\\nReason (R): The government has to use the savings of other sectors of the economy to finance a part of its consumption expenditure.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Development Experiences of India: A Comparison with Neighbours", "q": "The 'Great Leap Forward' campaign was initiated in China in:\\n(a) 1949\\n(b) 1958\\n(c) 1965\\n(d) 1978", "marks": 1, "answer": "(b) 1958."}, {"n": 6, "type": "Short answer", "topic": "National Income Accounting", "q": "Calculate Gross Domestic Product at market price (GDPmp) from the following (Rs crore): Net National Product at factor cost = 5,000; Depreciation = 300; Net indirect taxes = 200; Net factor income from abroad = (-)100.", "marks": 2, "answer": "GDPmp = NNPfc + Depreciation + Net indirect taxes - NFIA (1)\\n= 5,000 + 300 + 200 - (-100) = Rs 5,600 crore. (1)"}, {"n": 7, "type": "Short answer", "topic": "Balance of Payments", "q": "Distinguish between the current account and the capital account of the balance of payments (any two points).", "marks": 2, "answer": "1. Current account records exports and imports of goods and services, income and transfer payments; capital account records transactions that change assets or liabilities (FDI, portfolio investment, borrowings). (1)\\n2. Current account transactions do not change the stock of assets/liabilities of residents; capital account transactions do (they create claims or liabilities). Current account items affect income; capital account items affect ownership. (1)"}, {"n": 8, "type": "Short answer", "topic": "Indian Economy 1950-1990", "q": "State any two objectives of land reforms introduced in India after independence.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Abolition of intermediaries (zamindars) and making tillers owners of land ('land to the tiller').\\n2. Land ceiling - fixing maximum land an individual can own, to reduce concentration of ownership and redistribute surplus land.\\n3. Promote equity in agriculture and increase productivity, since owners have an incentive to invest."}, {"n": 9, "type": "Long answer", "topic": "Liberalisation, Privatisation and Globalisation: An Appraisal", "q": "Explain the main measures of the economic reforms introduced in India in 1991 under liberalisation, privatisation and globalisation.", "marks": 5, "answer": "Marking points:\\n1. Background: 1991 crisis - high fiscal deficit, low foreign exchange reserves, rising prices; loans from World Bank/IMF with conditions (New Economic Policy). (1)\\n2. Liberalisation: abolition of industrial licensing for most industries; de-reservation; financial sector reforms (reduced SLR/CRR, entry of private and foreign banks); tax reforms (lower rates); foreign exchange reforms (devaluation of rupee, market-determined rate). (1.5)\\n3. Privatisation: disinvestment - sale of part of equity of PSUs to private sector; Navratna/Maharatna autonomy to improve efficiency. (1)\\n4. Globalisation: trade and investment policy reforms - reduced import tariffs and quantitative restrictions, removal of export duties, encouragement of FDI; outsourcing; WTO membership (1995). (1.5)"}, {"n": 10, "type": "Case-based", "topic": "Determination of Income and Employment", "q": "Read the case and answer.\\nIn an economy, the consumption function is C = 100 + 0.75Y and autonomous investment is I = 50 (Rs crore). Equilibrium is reached where aggregate demand equals aggregate supply.\\n(i) Calculate the equilibrium level of income. (1)\\n(ii) Calculate consumption expenditure at equilibrium. (1)\\n(iii) Calculate saving at equilibrium and compare it with investment. (1)\\n(iv) Find the value of the investment multiplier. (1)", "marks": 4, "answer": "(i) Y = C + I = 100 + 0.75Y + 50, so 0.25Y = 150 and Y = Rs 600 crore.\\n(ii) C = 100 + 0.75 x 600 = 100 + 450 = Rs 550 crore.\\n(iii) S = Y - C = 600 - 550 = Rs 50 crore, which equals I = 50 (S = I at equilibrium).\\n(iv) k = 1/(1 - MPC) = 1/0.25 = 4."}]}, "History": {"book": "Themes in Indian History I-III", "questions": [{"n": 1, "type": "MCQ", "topic": "Bricks, Beads and Bones: The Harappan Civilisation", "q": "Which Harappan site is famous for a dockyard?\\n(a) Kalibangan\\n(b) Lothal\\n(c) Banawali\\n(d) Harappa", "marks": 1, "answer": "(b) Lothal (in Gujarat)."}, {"n": 2, "type": "MCQ", "topic": "Kings, Farmers and Towns", "q": "Who deciphered the Brahmi script in 1838?\\n(a) Alexander Cunningham\\n(b) John Marshall\\n(c) James Prinsep\\n(d) R.E.M. Wheeler", "marks": 1, "answer": "(c) James Prinsep."}, {"n": 3, "type": "Fill in the blank", "topic": "Through the Eyes of Travellers", "q": "Kitab-ul-Hind, an Arabic account of India, was written by ________.", "marks": 1, "answer": "Al-Biruni."}, {"n": 4, "type": "Assertion-Reason", "topic": "Colonialism and the Countryside", "q": "Assertion (A): The British gave the Santhals land in the Rajmahal foothills demarcated as Damin-i-Koh.\\nReason (R): The British wanted the Santhals to clear forests and practise settled plough agriculture, which would bring revenue.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Peasants, Zamindars and the State", "q": "The Ain-i Akbari was written by:\\n(a) Abul Fazl\\n(b) Badauni\\n(c) Babur\\n(d) Bernier", "marks": 1, "answer": "(a) Abul Fazl."}, {"n": 6, "type": "Short answer", "topic": "Bricks, Beads and Bones: The Harappan Civilisation", "q": "Mention any two features of the drainage system of Harappan cities.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Streets were laid out on a grid pattern and drains were planned first, with houses built along them.\\n2. Every house had drains connected to street drains; main drains were made of bricks and covered with loose slabs that could be removed for cleaning.\\n3. Longer drains had sumps at intervals for cleaning; small towns like Lothal also had such drains."}, {"n": 7, "type": "Short answer", "topic": "Thinkers, Beliefs and Buildings", "q": "Give two reasons why the stupa at Sanchi survived while those at Amaravati did not.", "marks": 2, "answer": "1. The rulers of Bhopal, Shahjehan Begum and her successor Sultan Jehan Begum, provided money for its preservation; Sultan Jehan Begum funded the museum and guest house where John Marshall worked. (1)\\n2. Sanchi escaped the attention of early scholars and local rajas who carted away sculptures from Amaravati; scholars like H.H. Cole opposed removing originals and favoured plaster-cast copies, so it was preserved in situ; the Begums also preferred to keep the gateways in place when the French and British wanted them. (1)"}, {"n": 8, "type": "Short answer", "topic": "Mahatma Gandhi and the Nationalist Movement", "q": "Explain any two reasons why the Dandi March (1930) is considered significant.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. It brought Gandhiji to world attention; the European and American press covered it widely.\\n2. It was the first nationalist activity in which women participated in large numbers.\\n3. It made the British realise that their Raj would not last forever and they had to devolve some power to Indians (leading to Round Table Conferences).\\n4. Salt, used by all, united rich and poor against an unjust colonial tax."}, {"n": 9, "type": "Long answer", "topic": "Bhakti-Sufi Traditions", "q": "Discuss the teachings of Kabir and Guru Nanak. How did they challenge existing religious practices?", "marks": 5, "answer": "Marking points:\\n1. Kabir: Ultimate Reality is one, formless (nirguna); called by many names - Allah, Rama, Hari, Alakh; rejected idol worship and polytheism. (1)\\n2. Kabir used Vedantic (atman) and Sufi (haqq) terms; composed verses (sakhis, pads, Bijak, Kabir Granthavali); rejected rituals of both Hinduism and Islam and caste distinctions. (1)\\n3. Guru Nanak: worship of one formless God (nirankar); simple path - remembering and repeating the Name (nam japna), honest work (kirat karna), sharing (vand chhakna). (1)\\n4. Guru Nanak rejected sacrifices, ritual baths, image worship, austerities and scriptures of both religions; expressed ideas through hymns (shabad) in Punjabi, sung in ragas. (1)\\n5. Challenge: both opposed caste, priestly authority and external rituals, stressed inner devotion and equality; laid foundation of community (Guru Nanak's langar and sangat, later Sikh Panth). (1)"}, {"n": 10, "type": "Case-based", "topic": "Framing the Constitution", "q": "Read the case and answer.\\nOn 13 December 1946, an important resolution was moved in the Constituent Assembly. It declared India to be an 'Independent Sovereign Republic', guaranteed its citizens justice, equality and freedom, and assured that adequate safeguards would be provided for minorities, backward and tribal areas, and depressed and other backward classes. The mover said the Assembly must look to the past as well as the future.\\n(i) Name this resolution. (1)\\n(ii) Who moved it? (1)\\n(iii) Explain any two ideals expressed in this resolution. (2)", "marks": 4, "answer": "(i) The Objectives Resolution.\\n(ii) Jawaharlal Nehru.\\n(iii) Any two, 1 mark each: India to be an independent sovereign republic (no external authority); social, economic and political justice, equality and freedom of thought, expression, belief and worship for all citizens; adequate safeguards for minorities, backward and tribal areas and depressed classes; democracy - all power derived from the people."}]}, "Geography": {"book": "Fundamentals of Human Geography & India: People and Economy", "questions": [{"n": 1, "type": "MCQ", "topic": "Human Geography: Nature and Scope", "q": "The concept of 'Neodeterminism' or 'Stop and Go Determinism' was given by:\\n(a) Ellen C. Semple\\n(b) Griffith Taylor\\n(c) Vidal de la Blache\\n(d) Friedrich Ratzel", "marks": 1, "answer": "(b) Griffith Taylor."}, {"n": 2, "type": "MCQ", "topic": "Tertiary and Quaternary Activities", "q": "Which of the following is a quaternary activity?\\n(a) Mining\\n(b) Retail trading\\n(c) Research and development\\n(d) Weaving", "marks": 1, "answer": "(c) Research and development (knowledge-based activity)."}, {"n": 3, "type": "Fill in the blank", "topic": "Human Development", "q": "The Human Development Report is published every year by ________.", "marks": 1, "answer": "UNDP (United Nations Development Programme)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Land Resources and Agriculture", "q": "Assertion (A): Kharif crops are sown with the onset of the south-west monsoon.\\nReason (R): Kharif crops such as rice require high temperature and a lot of water.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Transport and Communication (India)", "q": "National Waterway No. 1 lies on which river stretch?\\n(a) Brahmaputra: Sadiya-Dhubri\\n(b) Ganga: Haldia-Prayagraj\\n(c) West Coast Canal: Kottapuram-Kollam\\n(d) Godavari-Krishna", "marks": 1, "answer": "(b) Ganga-Bhagirathi-Hooghly: Haldia to Prayagraj (about 1,620 km)."}, {"n": 6, "type": "Short answer", "topic": "Primary Activities", "q": "Mention any two features of plantation agriculture.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Large estates with huge capital investment.\\n2. Single-crop specialisation (tea, coffee, rubber, sugarcane, cocoa, banana).\\n3. Scientific methods of cultivation and managerial/technical support.\\n4. Cheap labour and good transport network linking estates to processing units and markets; mainly export-oriented."}, {"n": 7, "type": "Short answer", "topic": "Population: Distribution, Density, Growth and Composition (Migration)", "q": "Give any two push factors and any two pull factors of rural-to-urban migration in India.", "marks": 2, "answer": "Push factors (any two, 1 mark): poverty, high population pressure on land, lack of basic infrastructure (health, education), natural disasters, unemployment/underemployment. \\nPull factors (any two, 1 mark): better job opportunities, regular work, higher wages, better education, health and recreation facilities in cities."}, {"n": 8, "type": "Short answer", "topic": "Water Resources", "q": "What is rainwater harvesting? State any two of its benefits.", "marks": 2, "answer": "Rainwater harvesting is the method of capturing and storing rainwater for various uses and for recharging groundwater. (1)\\nBenefits (any two, 1/2 each): increases groundwater availability; raises water table; reduces urban flooding and soil erosion; improves groundwater quality by dilution of contaminants like fluoride and nitrates; checks saline water intrusion in coastal areas."}, {"n": 9, "type": "Long answer", "topic": "The World Population", "q": "Explain the Demographic Transition Theory with its three stages.", "marks": 5, "answer": "Marking points:\\n1. Meaning: the theory describes and predicts future population of an area; population changes from high fluctuating birth and death rates to low birth and death rates as society moves from rural agrarian and illiterate to urban industrial and literate. (1)\\n2. Stage I: high fertility and high mortality; slow population growth; people engaged in agriculture, low life expectancy, mostly illiterate, low technology. (1.5)\\n3. Stage II: fertility remains high early on but declines with time; mortality falls due to better sanitation and health; rapid population growth (population explosion). (1.5)\\n4. Stage III: both fertility and mortality decline considerably; population is stable or grows slowly; urbanised, literate, high technology; controlled family size. (1)"}, {"n": 10, "type": "Case-based", "topic": "Water Resources (Watershed Management)", "q": "Read the case and answer.\\nIn Alwar district of Rajasthan, villagers built johads and check dams and formed a people's body called the Arvary Pani Sansad to manage water collectively. In Andhra Pradesh, a programme called 'Neeru-Meeru' (Water and You) helped build percolation tanks and rainwater structures with people's participation. Such efforts turned dry wells and rivers into perennial sources.\\n(i) What is watershed management? (1)\\n(ii) Name the nationally launched programme for integrated watershed development. (1)\\n(iii) State any two benefits of such community-based watershed management. (2)", "marks": 4, "answer": "(i) Efficient management and conservation of surface and groundwater resources of an area (watershed), including prevention of runoff, storage and recharge through percolation tanks, recharge wells, etc., along with conservation of land, vegetation and animals.\\n(ii) Haryali (Central Government), aimed at conserving water for drinking, irrigation, fisheries and afforestation with people's participation. (Also accept Integrated Watershed Management Programme.)\\n(iii) Any two: recharges groundwater and revives rivers/wells; increases irrigation and agricultural productivity; reduces soil erosion; ensures drinking water; creates community ownership and sustainability."}]}, "Political Science": {"book": "Contemporary World Politics & Politics in India since Independence", "questions": [{"n": 1, "type": "MCQ", "topic": "The End of Bipolarity", "q": "The model of transition from an authoritarian socialist system to a democratic capitalist system in post-Soviet states is known as:\\n(a) Perestroika\\n(b) Shock therapy\\n(c) Glasnost\\n(d) Detente", "marks": 1, "answer": "(b) Shock therapy."}, {"n": 2, "type": "MCQ", "topic": "New Centres of Power", "q": "ASEAN was established in the year:\\n(a) 1957\\n(b) 1967\\n(c) 1977\\n(d) 1985", "marks": 1, "answer": "(b) 1967 (Bangkok Declaration)."}, {"n": 3, "type": "Fill in the blank", "topic": "Era of One-Party Dominance", "q": "The first general elections in independent India were held in ________.", "marks": 1, "answer": "1951-52 (between October 1951 and February 1952)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Challenges of Nation Building", "q": "Assertion (A): The States Reorganisation Commission was appointed in 1953.\\nReason (R): There were widespread popular demands, such as the Andhra movement, for redrawing state boundaries on linguistic lines.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Environment and Natural Resources", "q": "The Kyoto Protocol is an international agreement related to:\\n(a) Nuclear disarmament\\n(b) Reduction of greenhouse gas emissions\\n(c) Protection of Antarctica\\n(d) Trade in endangered species", "marks": 1, "answer": "(b) Reduction of greenhouse gas emissions."}, {"n": 6, "type": "Short answer", "topic": "India's External Relations", "q": "What is Panchsheel? Mention any two of its principles.", "marks": 2, "answer": "Panchsheel: the five principles of peaceful coexistence signed by Jawaharlal Nehru and Zhou Enlai on 29 April 1954 between India and China. (1)\\nAny two (1/2 each): mutual respect for each other's territorial integrity and sovereignty; mutual non-aggression; mutual non-interference in internal affairs; equality and mutual benefit; peaceful coexistence."}, {"n": 7, "type": "Short answer", "topic": "The End of Bipolarity", "q": "State any two consequences of the disintegration of the Soviet Union.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. End of the Cold War confrontation and ideological disputes; end of the arms race.\\n2. Change in power relations - the US became the sole superpower (unipolar world).\\n3. Capitalism became the dominant economic system; IMF and World Bank became powerful advisers.\\n4. Emergence of many new independent countries (e.g. the Baltic states, Central Asian republics)."}, {"n": 8, "type": "Short answer", "topic": "Security in the Contemporary World", "q": "Differentiate between the traditional and non-traditional notions of security (any two points).", "marks": 2, "answer": "1. Traditional security focuses on the state and threats from military force of other states; non-traditional security includes a wide range of threats to human beings (human security) and the globe. (1)\\n2. Traditional threats: war, invasion, arms race; non-traditional threats: terrorism, human rights violations, global poverty, migration, health epidemics (HIV-AIDS), climate change. Traditional security uses deterrence, defence, balance of power and alliances; non-traditional requires global cooperation. (1)"}, {"n": 9, "type": "Long answer", "topic": "Era of One-Party Dominance", "q": "Explain any five factors responsible for the dominance of the Congress party in the first three general elections of India.", "marks": 5, "answer": "Any five, 1 mark each:\\n1. Legacy of the national movement - Congress was seen as the inheritor of the freedom struggle.\\n2. Only party with an organisation spread across the country, down to the local level.\\n3. Popular leadership, especially Jawaharlal Nehru.\\n4. Social and ideological coalition - accommodated revolutionaries and pacifists, conservatives and radicals, all castes, religions and classes.\\n5. Tolerance of factions within the party, which kept groups inside rather than forming rival parties.\\n6. First-past-the-post system gave it a larger share of seats than votes.\\n7. Weak and divided opposition."}, {"n": 10, "type": "Case-based", "topic": "Politics of Planned Development", "q": "Read the case and answer.\\nAfter independence, India chose planning as the path to development. A Planning Commission was set up by a resolution of the Government of India. The First Five Year Plan (1951-56) focused on one sector since the country faced food shortages after Partition. The Second Plan, drafted under the leadership of a noted statistician, stressed heavy industries. In 2015, the Planning Commission was replaced by a new body.\\n(i) In which year was the Planning Commission set up? (1)\\n(ii) Which sector did the First Five Year Plan emphasise? (1)\\n(iii) Name the statistician who drafted the Second Plan. (1)\\n(iv) Name the body that replaced the Planning Commission. (1)", "marks": 4, "answer": "(i) 1950 (March 1950).\\n(ii) Agriculture (including dams and irrigation).\\n(iii) P.C. Mahalanobis.\\n(iv) NITI Aayog (National Institution for Transforming India)."}]}, "Sociology": {"book": "Indian Society & Social Change and Development in India", "questions": [{"n": 1, "type": "MCQ", "topic": "The Demographic Structure of the Indian Society", "q": "Who argued that population grows in a geometric progression while food production grows in an arithmetic progression?\\n(a) Karl Marx\\n(b) Thomas Robert Malthus\\n(c) Emile Durkheim\\n(d) Max Weber", "marks": 1, "answer": "(b) Thomas Robert Malthus."}, {"n": 2, "type": "MCQ", "topic": "Cultural Change", "q": "The concept of 'Sanskritisation' was introduced by:\\n(a) G.S. Ghurye\\n(b) M.N. Srinivas\\n(c) Andre Beteille\\n(d) B.R. Ambedkar", "marks": 1, "answer": "(b) M.N. Srinivas."}, {"n": 3, "type": "Fill in the blank", "topic": "The Story of Indian Democracy", "q": "The 73rd Constitutional Amendment Act, 1992 gave constitutional status to ________.", "marks": 1, "answer": "Panchayati Raj institutions (rural local self-government)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Social Institutions: Continuity and Change", "q": "Assertion (A): Caste is an ascribed status.\\nReason (R): Membership of a caste is determined by birth.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "The Demographic Structure of the Indian Society", "q": "In India, sex ratio is expressed as:\\n(a) Number of males per 1000 females\\n(b) Number of females per 1000 males\\n(c) Number of females per 100 persons\\n(d) Number of births per 1000 population", "marks": 1, "answer": "(b) Number of females per 1000 males."}, {"n": 6, "type": "Short answer", "topic": "Patterns of Social Inequality and Exclusion", "q": "Distinguish between prejudice and stereotype.", "marks": 2, "answer": "Prejudice: pre-conceived opinions or attitudes (usually negative) held by members of one group towards another, based on hearsay rather than direct evidence, and resistant to change. (1)\\nStereotype: fixed, generalised image of a whole group of people (e.g. of ethnic or social groups or women) that ignores individual differences; stereotypes often form the basis of prejudice. (1)"}, {"n": 7, "type": "Short answer", "topic": "Cultural Change", "q": "What is Westernisation? Give any two examples of its effects on Indian society.", "marks": 2, "answer": "Westernisation (M.N. Srinivas): changes in Indian society and culture as a result of over 150 years of British rule, at the levels of technology, institutions, ideology and values. (1)\\nExamples (any two, 1/2 each): adoption of western dress, food habits and lifestyle; spread of English education; changes in ideas like humanism and rationalism; use of new technology; changes in art and literature."}, {"n": 8, "type": "Short answer", "topic": "The Demographic Structure of the Indian Society", "q": "State any two reasons for the declining child sex ratio in India.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Sex-selective abortion using modern technology (ultrasound) despite legal bans.\\n2. Female infanticide and neglect of girl children in health care and nutrition.\\n3. Strong son preference due to patriarchal values, dowry, and inheritance norms.\\n4. Paradoxically, prosperous regions show the worst ratios as smaller families increase pressure for sons."}, {"n": 9, "type": "Long answer", "topic": "Patterns of Social Inequality and Exclusion", "q": "What is untouchability? Explain its three main dimensions with examples. Mention one constitutional measure against it.", "marks": 5, "answer": "Marking points:\\n1. Meaning: an extreme aspect of the caste system that prescribes strict social sanctions against members of castes at the bottom of the purity-pollution scale; considered 'impure' so that even their touch was thought to pollute. (1)\\n2. Exclusion: denial of access to common drinking water sources, temples, religious ceremonies and festivals. (1)\\n3. Humiliation-subordination: forced gestures of deference such as taking off footwear, standing with bowed heads, not wearing clean clothes, and so on. (1)\\n4. Exploitation: economic exploitation - forced unpaid labour (begar) or very low wages, confiscation of property. (1)\\n5. Measure: Article 17 abolished untouchability; Protection of Civil Rights Act 1955 and SC/ST (Prevention of Atrocities) Act 1989; reservations in education, jobs and legislatures. (1)"}, {"n": 10, "type": "Case-based", "topic": "The Demographic Structure of the Indian Society (Demographic Dividend)", "q": "Read the case and answer.\\nIndia today has one of the youngest populations in the world. A large share of its people are in the working age group (15-64 years). Economists say this can be a 'window of opportunity', but only if young people are healthy, educated, skilled and gainfully employed. Otherwise, a large jobless youth population could become a burden.\\n(i) What is meant by 'demographic dividend'? (1)\\n(ii) Define dependency ratio. (1)\\n(iii) Suggest two conditions needed for India to benefit from its demographic dividend. (2)", "marks": 4, "answer": "(i) The benefit (economic growth) arising from a large proportion of working-age population relative to dependants.\\n(ii) Dependency ratio = ratio of the dependent population (below 15 and above 64 years) to the working-age population (15-64 years); a falling ratio can lead to growth.\\n(iii) Any two, 1 mark each: expanding quality education and skill development; creating adequate employment opportunities; better health care and nutrition; including women in the workforce."}]}, "Psychology": {"book": "Psychology", "questions": [{"n": 1, "type": "MCQ", "topic": "Variations in Psychological Attributes", "q": "A child has a mental age of 10 years and a chronological age of 8 years. The child's IQ is:\\n(a) 80\\n(b) 100\\n(c) 125\\n(d) 150", "marks": 1, "answer": "(c) 125, since IQ = (MA/CA) x 100 = (10/8) x 100 = 125."}, {"n": 2, "type": "MCQ", "topic": "Variations in Psychological Attributes", "q": "The Triarchic Theory of Intelligence was proposed by:\\n(a) Howard Gardner\\n(b) Robert Sternberg\\n(c) J.P. Das\\n(d) Charles Spearman", "marks": 1, "answer": "(b) Robert Sternberg (componential, experiential and contextual intelligence)."}, {"n": 3, "type": "Fill in the blank", "topic": "Meeting Life Challenges", "q": "The General Adaptation Syndrome (GAS) model of stress was proposed by ________.", "marks": 1, "answer": "Hans Selye."}, {"n": 4, "type": "Assertion-Reason", "topic": "Therapeutic Approaches", "q": "Assertion (A): Systematic desensitisation is used to treat phobias.\\nReason (R): In this technique, the client is progressively exposed to anxiety-provoking stimuli while remaining relaxed, so that anxiety is gradually eliminated.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(a) Both A and R are true, and R is the correct explanation of A. (Technique introduced by Wolpe.)"}, {"n": 5, "type": "MCQ", "topic": "Self and Personality", "q": "Which of the following is NOT one of the Big Five personality factors?\\n(a) Openness to experience\\n(b) Conscientiousness\\n(c) Intelligence\\n(d) Neuroticism", "marks": 1, "answer": "(c) Intelligence (the five are openness, extraversion, agreeableness, neuroticism, conscientiousness)."}, {"n": 6, "type": "Short answer", "topic": "Meeting Life Challenges", "q": "Distinguish between eustress and distress with an example of each.", "marks": 2, "answer": "Eustress: a healthy, positive level of stress that motivates and improves performance, e.g. mild pressure before an exam leading to focused preparation. (1)\\nDistress: excessive or negative stress that harms performance and health, e.g. constant worry causing sleeplessness and illness. (1)"}, {"n": 7, "type": "Short answer", "topic": "Psychological Disorders", "q": "Describe any two positive symptoms of schizophrenia.", "marks": 2, "answer": "Any two, 1 mark each:\\n1. Delusions: false beliefs held firmly despite contrary evidence (e.g. of persecution, grandeur, reference, control).\\n2. Hallucinations: perceptions without external stimuli, most commonly auditory (hearing voices).\\n3. Disorganised thinking and speech (formal thought disorder, derailment, neologisms).\\n4. Inappropriate affect: emotions unsuited to the situation."}, {"n": 8, "type": "Short answer", "topic": "Attitude and Social Cognition", "q": "Explain the concept of cognitive dissonance with an example.", "marks": 2, "answer": "Cognitive dissonance (Leon Festinger): when two cognitive components of an attitude are inconsistent, a person feels mental discomfort (dissonance) and changes one of them to restore consistency. (1)\\nExample: 'Pan masala causes cancer' and 'I eat pan masala' are dissonant; the person may stop eating pan masala to reduce dissonance. (1)"}, {"n": 9, "type": "Long answer", "topic": "Self and Personality", "q": "Explain Freud's structure of personality. Describe any two defence mechanisms.", "marks": 5, "answer": "Marking points:\\n1. Id: source of psychic energy; works on the pleasure principle; seeks immediate gratification of instinctual (sexual, aggressive) desires; unconscious. (1)\\n2. Ego: grows out of id; works on the reality principle; mediates between id's demands and the external world and superego. (1)\\n3. Superego: moral branch; internalised values of parents and society; works on the morality principle. (1)\\n4-5. Any two defence mechanisms (1 mark each): Repression - anxiety-provoking thoughts pushed into the unconscious; Projection - attributing one's own traits to others; Denial - refusing to accept reality; Reaction formation - acting opposite to one's feelings; Rationalisation - giving logical reasons to justify unacceptable behaviour."}, {"n": 10, "type": "Case-based", "topic": "Meeting Life Challenges (Coping)", "q": "Read the case and answer.\\nAman has board exams in two months and feels constant pressure from parents to score above 95%. He has headaches and cannot sleep. His friend Kabir faced similar pressure; he made a study timetable, spoke to his teachers about difficult topics and practised deep breathing daily. Another friend, Rohit, spends hours playing video games to 'forget' about the exams.\\n(i) Identify the type of stress Aman is experiencing (source of stress). (1)\\n(ii) Which coping strategy is Kabir using? (1)\\n(iii) Identify Rohit's coping strategy and suggest two life skills that could help Aman. (2)", "marks": 4, "answer": "(i) Psychological stress arising from social pressure (academic/parental expectations; also frustration and internal pressure); it shows physiological effects such as headaches and insomnia.\\n(ii) Task-oriented coping (Endler and Parker) - gathering information, planning and taking direct action; supported by relaxation techniques.\\n(iii) Rohit uses avoidance-oriented coping (denying or minimising the situation). Life skills for Aman (any two): time management, assertiveness, rational thinking, improving relationships, self-care (proper sleep, exercise, nutrition), overcoming unhelpful habits."}]}, "Computer Science": {"book": "Computer Science (Python)", "questions": [{"n": 1, "type": "MCQ", "topic": "File Handling in Python", "q": "Which file mode opens a text file for writing at the end of the existing content without erasing it?\\n(a) 'r'\\n(b) 'w'\\n(c) 'a'\\n(d) 'x'", "marks": 1, "answer": "(c) 'a' (append mode)."}, {"n": 2, "type": "MCQ", "topic": "Structured Query Language (SQL)", "q": "Which SQL command removes a table along with its structure from the database?\\n(a) DELETE\\n(b) DROP TABLE\\n(c) REMOVE\\n(d) ALTER TABLE", "marks": 1, "answer": "(b) DROP TABLE."}, {"n": 3, "type": "Fill in the blank", "topic": "Stack", "q": "A stack follows the ________ principle.", "marks": 1, "answer": "LIFO (Last In, First Out)."}, {"n": 4, "type": "Assertion-Reason", "topic": "File Handling in Python (Binary files)", "q": "Assertion (A): Binary files store data as a sequence of bytes and are not in human-readable form.\\nReason (R): The pickle module is used to serialise and de-serialise Python objects.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(b) Both A and R are true, but R is not the correct explanation of A."}, {"n": 5, "type": "MCQ", "topic": "Computer Networks", "q": "Which network device connects two networks that use different protocols?\\n(a) Hub\\n(b) Switch\\n(c) Repeater\\n(d) Gateway", "marks": 1, "answer": "(d) Gateway."}, {"n": 6, "type": "Short answer", "topic": "Working with Functions (Review)", "q": "Write the output of the following code:\\ndef change(a, b=5):\\n    a = a + b\\n    b = a - b\\n    return a, b\\n\\nx, y = change(10)\\nprint(x, y)", "marks": 2, "answer": "Output:\\n15 10\\nTrace: a = 10, b = 5 (default); a = 10 + 5 = 15; b = 15 - 5 = 10; returns (15, 10). (1 mark for trace, 1 for output)"}, {"n": 7, "type": "Short answer", "topic": "Exception Handling in Python", "q": "Write the output of the following code and explain why:\\ntry:\\n    x = int(\"12a\")\\n    print(\"Done\")\\nexcept ValueError:\\n    print(\"Invalid\")\\nfinally:\\n    print(\"End\")", "marks": 2, "answer": "Output:\\nInvalid\\nEnd\\n(1)\\nint(\"12a\") raises ValueError, so print(\"Done\") is skipped and the except block runs; the finally block always executes. (1)"}, {"n": 8, "type": "Short answer", "topic": "Structured Query Language (SQL)", "q": "Differentiate between the WHERE and HAVING clauses in SQL with an example.", "marks": 2, "answer": "WHERE filters individual rows before grouping and cannot use aggregate functions; HAVING filters groups formed by GROUP BY and can use aggregate functions. (1)\\nExample: SELECT Class, AVG(Marks) FROM STUDENT WHERE Marks > 40 GROUP BY Class HAVING AVG(Marks) > 70; (1)"}, {"n": 9, "type": "Long answer", "topic": "Stack", "q": "Write a Python program with two functions:\\n(a) PUSH(Nums, Stk): pushes all numbers from the list Nums that are divisible by 5 onto the stack Stk.\\n(b) POP(Stk): pops and returns the top element; if the stack is empty, displays 'Stack Empty' and returns None.\\nThen, for Nums = [10, 12, 25, 33, 40], show the stack after PUSH and the output of popping all elements.", "marks": 5, "answer": "def PUSH(Nums, Stk):\\n    for n in Nums:\\n        if n % 5 == 0:\\n            Stk.append(n)\\n\\ndef POP(Stk):\\n    if len(Stk) == 0:\\n        print(\"Stack Empty\")\\n        return None\\n    return Stk.pop()\\n\\nStk = []\\nPUSH([10, 12, 25, 33, 40], Stk)\\nprint(Stk)\\nwhile Stk:\\n    print(POP(Stk))\\nPOP(Stk)\\n\\nMarking: PUSH logic with condition and append (2); POP with empty check and pop() (2); correct output (1).\\nOutput:\\n[10, 25, 40]\\n40\\n25\\n10\\nStack Empty"}, {"n": 10, "type": "Case-based", "topic": "Structured Query Language (SQL)", "q": "Read the case and answer.\\nA school stores data in table STUDENT(Rno, Name, Class, Marks):\\n1, Asha, 12A, 88\\n2, Ravi, 12B, 76\\n3, Meena, 12A, 92\\n4, John, 12B, 65\\n(i) Write the output: SELECT AVG(Marks) FROM STUDENT WHERE Class = '12A'; (1)\\n(ii) Write the output: SELECT Name FROM STUDENT WHERE Marks > 80 ORDER BY Marks DESC; (1)\\n(iii) Write a query to display each class with its highest marks. (1)\\n(iv) Write a query to increase John's marks by 5. (1)", "marks": 4, "answer": "(i) 90 (displayed as 90.0000 in MySQL): (88 + 92)/2 = 90.\\n(ii) Meena\\n     Asha\\n(iii) SELECT Class, MAX(Marks) FROM STUDENT GROUP BY Class;  -> 12A 92, 12B 76\\n(iv) UPDATE STUDENT SET Marks = Marks + 5 WHERE Name = 'John';"}]}, "Informatics Practices": {"book": "Informatics Practices", "questions": [{"n": 1, "type": "MCQ", "topic": "Database Query using SQL (Math functions)", "q": "What is the output of SELECT ROUND(15.678, 1); ?\\n(a) 15.6\\n(b) 15.7\\n(c) 16\\n(d) 15.68", "marks": 1, "answer": "(b) 15.7."}, {"n": 2, "type": "MCQ", "topic": "Plotting Data using Matplotlib", "q": "Which function of matplotlib.pyplot is used to draw a bar chart?\\n(a) plt.plot()\\n(b) plt.hist()\\n(c) plt.bar()\\n(d) plt.pie()", "marks": 1, "answer": "(c) plt.bar()."}, {"n": 3, "type": "Fill in the blank", "topic": "Data Handling using Pandas", "q": "The ________ attribute of a DataFrame returns a tuple giving the number of rows and columns.", "marks": 1, "answer": "shape (e.g. df.shape)."}, {"n": 4, "type": "Assertion-Reason", "topic": "Data Handling using Pandas", "q": "Assertion (A): A Pandas Series is size-immutable.\\nReason (R): The data values of a Pandas Series cannot be changed once it is created.\\n(a) Both A and R are true, and R is the correct explanation of A.\\n(b) Both A and R are true, but R is not the correct explanation of A.\\n(c) A is true, but R is false.\\n(d) A is false, but R is true.", "marks": 1, "answer": "(c) A is true, but R is false. (A Series is size-immutable but value-mutable.)"}, {"n": 5, "type": "MCQ", "topic": "Societal Impacts", "q": "Which of the following is an example of Free and Open Source Software (FOSS)?\\n(a) Microsoft Windows\\n(b) Linux\\n(c) Adobe Photoshop\\n(d) Microsoft Office", "marks": 1, "answer": "(b) Linux."}, {"n": 6, "type": "Short answer", "topic": "Data Handling using Pandas", "q": "Write the output of the following code:\\nimport pandas as pd\\ns = pd.Series([10, 20, 30, 40], index=['a', 'b', 'c', 'd'])\\nprint(s[s > 20])\\nprint(s['b'] * 2)", "marks": 2, "answer": "Output:\\nc    30\\nd    40\\ndtype: int64\\n40\\n(1 mark for the filtered Series, 1 mark for 40)"}, {"n": 7, "type": "Short answer", "topic": "Database Query using SQL (Text functions)", "q": "Write the output of:\\n(i) SELECT MID('INFORMATICS', 3, 4);\\n(ii) SELECT LENGTH(TRIM('  Python  '));", "marks": 2, "answer": "(i) FORM - 4 characters starting from position 3 (I-N-F-O-R-M: F is 3rd). (1)\\n(ii) 6 - TRIM removes leading and trailing spaces giving 'Python'. (1)"}, {"n": 8, "type": "Short answer", "topic": "Societal Impacts", "q": "What is a digital footprint? Differentiate between active and passive digital footprints.", "marks": 2, "answer": "Digital footprint: the trail of data we leave behind while using the Internet (websites visited, emails, posts, online forms). (1)\\nActive footprint: data we intentionally submit online (posts, emails, form entries). Passive footprint: data generated unintentionally (browsing history, cookies, IP address, location data). (1)"}, {"n": 9, "type": "Long answer", "topic": "Data Handling using Pandas (DataFrame)", "q": "Write Python statements to:\\n(a) Create a DataFrame df with columns Name ['Asha','Ravi','Meena','John'] and Marks [88, 76, 92, 65].\\n(b) Add a column Grade with values ['A','B','A','C'].\\n(c) Display rows where Marks > 80.\\n(d) Display the mean of Marks, with its output.\\n(e) Delete the column Grade permanently.", "marks": 5, "answer": "(a) import pandas as pd\\n    df = pd.DataFrame({'Name': ['Asha', 'Ravi', 'Meena', 'John'], 'Marks': [88, 76, 92, 65]})  (1)\\n(b) df['Grade'] = ['A', 'B', 'A', 'C']  (1)\\n(c) print(df[df['Marks'] > 80])  -> rows of Asha (88) and Meena (92)  (1)\\n(d) print(df['Marks'].mean())  -> 80.25  [(88+76+92+65)/4 = 321/4]  (1)\\n(e) df = df.drop('Grade', axis=1)   or   del df['Grade']  (1)"}, {"n": 10, "type": "Case-based", "topic": "Introduction to Computer Networks", "q": "Read the case and answer.\\nStarTech Ltd is setting up a network in its campus with four blocks: Admin (60 computers), Finance (20), HR (15) and Store (10). Distances: Admin-Finance 60 m, Admin-HR 110 m, Admin-Store 70 m, Finance-HR 50 m, HR-Store 80 m.\\n(i) Suggest the most suitable block to house the server, with reason. (1)\\n(ii) Suggest a suitable cable layout/topology connecting the blocks. (1)\\n(iii) Where should a repeater be placed if blocks are connected to Admin directly? (1)\\n(iv) Name the device used to connect computers within each block. (1)", "marks": 4, "answer": "(i) Admin block - it has the maximum number of computers (80:20 rule reduces traffic).\\n(ii) Star topology with Admin as the central hub, connecting Finance, HR and Store directly to Admin.\\n(iii) Between Admin and HR, as the distance (110 m) exceeds about 100 m, the limit for Ethernet twisted-pair cable.\\n(iv) Switch (or hub)."}]}, "English": {"book": "Flamingo & Vistas", "questions": [{"n": 1, "type": "MCQ", "topic": "The Last Lesson (Flamingo)", "q": "In 'The Last Lesson', the order from Berlin stated that:\\n(a) schools in Alsace and Lorraine would be closed\\n(b) only German would be taught in the schools of Alsace and Lorraine\\n(c) M. Hamel would be promoted\\n(d) French would be made compulsory", "marks": 1, "answer": "(b) Only German would be taught in the schools of Alsace and Lorraine."}, {"n": 2, "type": "MCQ", "topic": "Lost Spring (Flamingo)", "q": "Saheb's family had come to Seemapuri from:\\n(a) Firozabad\\n(b) Dhaka (Bangladesh)\\n(c) Kolkata\\n(d) Udipi", "marks": 1, "answer": "(b) Dhaka, Bangladesh (after storms swept away their fields and homes)."}, {"n": 3, "type": "Fill in the blank", "topic": "Indigo (Flamingo)", "q": "________, a poor sharecropper from Champaran, met Gandhi at the Lucknow session of the Congress in 1916 and persuaded him to visit Champaran.", "marks": 1, "answer": "Rajkumar Shukla."}, {"n": 4, "type": "MCQ", "topic": "My Mother at Sixty-six (Flamingo)", "q": "In 'My Mother at Sixty-six', the poet compares her mother's face to:\\n(a) a withered flower\\n(b) a late winter's moon\\n(c) a dying candle\\n(d) an autumn leaf", "marks": 1, "answer": "(b) A late winter's moon (pale, dim and lustreless, suggesting old age and decline)."}, {"n": 5, "type": "MCQ", "topic": "The Third Level (Vistas)", "q": "In 'The Third Level', Charley found himself on the third level of Grand Central Station, which belonged to the year:\\n(a) 1894\\n(b) 1904\\n(c) 1914\\n(d) 1880", "marks": 1, "answer": "(a) 1894."}, {"n": 6, "type": "Short answer", "topic": "The Enemy (Vistas)", "q": "Why did Dr Sadao help the wounded American prisoner of war despite knowing he was an enemy? (40-50 words)", "marks": 2, "answer": "Key points: Sadao was first a doctor and his professional ethics required him to save a life (1); his humanity and compassion overcame narrow patriotism - he could not throw a wounded man back into the sea, though he later arranged the soldier's escape to remain loyal to his country as well (1)."}, {"n": 7, "type": "Short answer", "topic": "On the Face of It (Flamingo)", "q": "How did Derry's meeting with Mr Lamb change his outlook on life? (40-50 words)", "marks": 2, "answer": "Key points: Mr Lamb, despite his tin leg, lived cheerfully and taught Derry that what matters is how one feels inside, not appearance; he advised Derry not to hide away and to stop worrying about what others say (1). Derry gained confidence and hope; he decided to return to Mr Lamb against his mother's wishes, showing he now wanted to face the world (1)."}, {"n": 8, "type": "Short answer", "topic": "Lost Spring (Flamingo)", "q": "Mukesh insists on being his own master. How is he different from other bangle-makers of Firozabad? (40-50 words)", "marks": 2, "answer": "Key points: Unlike his family and others who accept bangle-making as their inherited destiny and are trapped by the vicious circle of sahukars, middlemen, police and politicians (1), Mukesh dares to dream of becoming a motor mechanic and is willing to walk to a garage far away to learn - showing courage to break free (1)."}, {"n": 9, "type": "Long answer", "topic": "Indigo (Flamingo)", "q": "'The Champaran episode was a turning point in Gandhi's life.' Discuss with reference to the chapter 'Indigo'. (120-150 words)", "marks": 5, "answer": "Marking points (content 4, expression 1):\\n1. Background: British landlords forced sharecroppers to grow indigo on 15% of land (tinkathia); when synthetic indigo came, they demanded compensation - peasants were exploited.\\n2. Gandhi's defiance: he refused to obey the order to leave Champaran; civil disobedience - thousands of peasants gathered at Motihari court; the government withdrew the case.\\n3. Outcome: the landlords agreed to refund 25% of the money; this built peasants' courage and ended landlord control within a few years.\\n4. Gandhi's broader work: self-reliance - taught peasants to fight their own battles, refused the help of C.F. Andrews; set up schools, improved hygiene and health.\\n5. Significance: first successful civil disobedience in India; Gandhi said it proved the British could not order him about in his own country - the beginning of the freedom struggle's mass phase."}, {"n": 10, "type": "Case-based", "topic": "Reading Skills: Unseen Passage", "q": "Read the passage and answer.\\nCities are getting hotter. Concrete, asphalt and glass absorb sunlight during the day and release heat at night, making urban areas several degrees warmer than nearby villages. This is called the 'urban heat island' effect. Trees offer a simple remedy. A mature tree can cool its surroundings through shade and by releasing water vapour from its leaves. Studies show that streets lined with trees can be up to 5 degrees Celsius cooler than bare streets. Trees also absorb dust, reduce noise and give birds a home. Yet planners cut them to widen roads; they must treat trees as essential infrastructure, not decoration.\\n(i) What is the 'urban heat island' effect? (1)\\n(ii) Name two ways in which trees cool their surroundings. (1)\\n(iii) Mention two other benefits of trees given in the passage. (1)\\n(iv) Find a word in the passage that means 'a solution or cure'. (1)", "marks": 4, "answer": "(i) Urban areas become several degrees warmer than nearby villages because concrete, asphalt and glass absorb sunlight during the day and release heat at night.\\n(ii) By providing shade and by releasing water vapour from their leaves.\\n(iii) Any two: absorb dust, reduce noise, give birds a home.\\n(iv) Remedy."}]}}};
